(10106104, 101061, 'P1-C6-L1-O04', null, 4, 'أن يصف الطالب شكل المسار لحركة المقذوف.', 'أن يصف الطالب شكل مسار المقذوف (قطع مكافئ).', '[]'::jsonb, 'أن يصف الطالب شكل مسار المقذوف (قطع مكافئ).', 'اختصار التركيب «شكل المسار لحركة المقذوف» إلى مصطلح الكتاب «مسار المقذوف» مع ذكر شكله.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["مسار المقذوف","القطع المكافئ"]'::jsonb, null, '[161,162,163,179]'::jsonb, 'مغطى', 'ص161 «يتحرك في مسار منحنٍ أو على شكل قطع مكافئ ... تسمى مسار المقذوف»؛ ص163 «السرعة الأفقية الثابتة والتسارع الرأسي المنتظم قد أنتجا معًا مسارًا يتخذ شكل القطع المكافئ»؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106105, 101061, 'P1-C6-L1-O05', null, 5, 'أن يتعرف الطالب لسبب سرعة المقذوف في الاتجاه الأفقي تكون ثابتة.', 'أن يفسّر الطالب ثبات السرعة الأفقية للمقذوف بعدم وجود قوة أفقية تؤثر فيه عند إهمال مقاومة الهواء (a_x = 0).', '[]'::jsonb, 'أن يفسّر الطالب ثبات السرعة الأفقية للمقذوف بعدم وجود قوة أفقية تؤثر فيه عند إهمال مقاومة الهواء (a_x = 0).', '«يتعرف لسبب» غير قابل للقياس ومضطرب التركيب؛ استُبدل بـ«يفسّر» مع إضافة شرط إهمال مقاومة الهواء الذي يقيّد به الكتاب ثبات السرعة الأفقية.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["المركّبة الأفقية للسرعة","التسارع الأفقي","مقاومة الهواء"]'::jsonb, null, '[163,179]'::jsonb, 'مغطى', 'ص163: «إن السرعة في الاتجاه الأفقي ثابتة دائمًا لعدم وجود قوى تؤثر في الكرة في هذا الاتجاه»، والخطوة 3 من استراتيجيات حل المسألة «فلا يوجد تسارع أفقي؛ أي أن a_x = 0.0»؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106106, 101061, 'P1-C6-L1-O06', null, 6, 'أن يحل الطالب مسائل حسابية على حركة المقذوفات.', 'أن يحلّ الطالب مسائل حسابية على حركة المقذوفات التي تُطلق أفقيًا.', '[]'::jsonb, 'أن يحلّ الطالب مسائل حسابية على حركة المقذوفات التي تُطلق أفقيًا.', 'تقييد الهدف بالمقذوفات الأفقية لأن المقذوفات المطلقة بزاوية لها هدف مستقل (O12)، ولتطابق ترتيب الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["المقذوف الأفقي","زمن السقوط","المدى الأفقي"]'::jsonb, null, '[163,164,181,183]'::jsonb, 'مغطى', 'ص163 استراتيجيات حل المسألة «الحركة في بعدين»؛ ص164 المسألتان التدريبيتان 1–2 (حجر يُقذف أفقيًا من بناية)؛ ص181 الأسئلة 38–40؛ ص183 السؤال 8.', null, 'approved', '2026-11-16'::timestamptz),
(10106107, 101061, 'P1-C6-L1-O07', null, 7, 'أن يوضح الطالب حركة المقذوفات التي تطلق بزاوية بالرسم', 'أن يوضّح الطالب بالرسم حركة المقذوف الذي يُطلق بزاوية، مبيّنًا حركتيه الأفقية والرأسية.', '[]'::jsonb, 'أن يوضّح الطالب بالرسم حركة المقذوف الذي يُطلق بزاوية، مبيّنًا حركتيه الأفقية والرأسية.', 'إعادة ترتيب الجملة، وتحديد ما يُوضَّح بالرسم كما في الشكل 6-3، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'إجراءات ومهارات', '["المقذوف المطلق بزاوية","الحركة الأفقية","الحركة الرأسية"]'::jsonb, null, '[164]'::jsonb, 'مغطى', 'ص164 «المقذوفات التي تطلق بزاوية» والشكل 6-3a الذي يبين الحركتين الأفقية والرأسية بصورة منفصلة، والشكل 6-3b للجمع الاتجاهي.', null, 'approved', '2026-11-16'::timestamptz),
(10106108, 101061, 'P1-C6-L1-O08', null, 8, 'أن يذكر الطالب أمثلة على المقذوفات التي تطلق بزاوية.', 'أن يذكر الطالب أمثلة على المقذوفات التي تطلق بزاوية.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على المقذوفات التي تطلق بزاوية.', 'الهدف سليم.', 'لا تغيير', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المقذوف المطلق بزاوية"]'::jsonb, null, '[161,165,166,181]'::jsonb, 'مغطى', 'ص161 أمثلة (كرة قدم قُذفت، ضفدع يقفز، السهام والطلقات)؛ ص165 كرة قُذفت بزاوية 66°؛ ص166 لاعب يقذف كرة بزاوية 30.0°؛ ص181 سهم بزاوية 30.0°. لا يفرد الكتاب قائمة أمثلة مستقلة بل ترد ضمن النص والمسائل.', null, 'approved', '2026-11-16'::timestamptz),
(10106109, 101061, 'P1-C6-L1-O09', null, 9, 'أن يوضح الطالب مركبات كل من السرعة والتسارع في المقذوفات التي تطلق بزاوية', 'أن يوضّح الطالب مركّبتي السرعة المتجهة للمقذوف المطلق بزاوية (v_x ثابتة، و v_y متغيرة) وتسارعه (a_x = 0، و a_y = −g) في أثناء حركته.', '[]'::jsonb, 'أن يوضّح الطالب مركّبتي السرعة المتجهة للمقذوف المطلق بزاوية (v_x ثابتة، و v_y متغيرة) وتسارعه (a_x = 0، و a_y = −g) في أثناء حركته.', 'تحديد المركّبات كما يعرضها الكتاب، وإزالة الإيهام بأن للتسارع مركّبتين غير صفريتين، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["مركّبتا السرعة المتجهة","تسارع الجاذبية الأرضية","المقذوف المطلق بزاوية"]'::jsonb, null, '[164,165,180]'::jsonb, 'مغطى', 'ص164 الشكل 6-3a (v_x مع a_x = 0، و v_y مع a_y)؛ ص165 المثال 1: v_yi = v_i sin θ_i، a_y = −g؛ ص180 السؤال 28.', null, 'approved', '2026-11-16'::timestamptz),
(10106110, 101061, 'P1-C6-L1-O10', null, 10, 'أن يتعرف الطالب أن المقذوف عند أعلى نقطة تكون له سرعة أفقية فقط.', 'أن يبيّن الطالب أن سرعة المقذوف عند أقصى ارتفاع أفقية فقط لأن مركّبتها الرأسية تساوي صفرًا.', '[]'::jsonb, 'أن يبيّن الطالب أن سرعة المقذوف عند أقصى ارتفاع أفقية فقط لأن مركّبتها الرأسية تساوي صفرًا.', '«يتعرف أن» غير قابل للقياس؛ استُبدل بـ«يبيّن» مع ذكر التعليل الذي يورده الكتاب.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["أقصى ارتفاع","المركّبة الرأسية للسرعة"]'::jsonb, null, '[164,165,180]'::jsonb, 'مغطى', 'ص164: «أقصى ارتفاع يصل إليه المقذوف، حيث يكون له سرعة أفقية فقط؛ لأن سرعته الرأسية صفر»؛ ص165 المثال 1 (v_y = 0.0 m/s عند القمة)؛ ص180 السؤال 28c.', null, 'approved', '2026-11-16'::timestamptz),
(10106111, 101061, 'P1-C6-L1-O11', null, 11, 'أن يرسم الطالب مقذوف ويحدد عليه مسار المقذوف وزاوية اطلاقه واقصى ارتفاع يصل إليه والمدى الأفقي له وزمن التحليق ويحلل عند كل نقطة مركبتيه ( السرعة والتسارع.)', 'أن يرسم الطالب مسار مقذوف أُطلق بزاوية ويحدّد عليه زاوية الإطلاق وأقصى ارتفاع والمدى الأفقي، ويمثّل عند نقاط مختلفة من المسار مركّبتي السرعة المتجهة (v_x و v_y) ومتجه التسارع (g رأسيًّا إلى أسفل).', '["أن يرسم الطالب مسار مقذوف أُطلق بزاوية ويحدّد عليه زاوية الإطلاق وأقصى ارتفاع والمدى الأفقي.","أن يمثّل الطالب عند نقاط مختلفة من مسار المقذوف مركّبتي السرعة المتجهة (v_x و v_y) ومتجه التسارع (g رأسيًّا إلى أسفل)."]'::jsonb, 'أن يرسم الطالب مسار مقذوف أُطلق بزاوية ويحدّد عليه زاوية الإطلاق وأقصى ارتفاع والمدى الأفقي، ويمثّل عند نقاط مختلفة من المسار مركّبتي السرعة المتجهة (v_x و v_y) ومتجه التسارع (g رأسيًّا إلى أسفل).', 'الأصل يطلب تحليل «مركّبتي التسارع» عند كل نقطة، والكتاب يبين أن تسارع المقذوف ثابت رأسي إلى أسفل (a_x = 0، a_y = −g) فلا يُحلَّل إلى مركّبتين (ص164 الشكل 6-3a، ص179 «المركّبة الرأسية لحركة المقذوف لها تسارع ثابت»)؛ كما أن «زمن التحليق» كمية زمنية لا تُحدَّد على الرسم فحُذفت منه. وصُحح «مقذوف» إلى «مسار مقذوف» و«اطلاقه/اقصى» إملائيًا. يُقترح فصله لأنه يجمع رسم المسار وتحليل المتجهات.', 'تصحيح علمي', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["مسار المقذوف","زاوية الإطلاق","أقصى ارتفاع","المدى الأفقي","مركّبتا السرعة المتجهة","تسارع الجاذبية الأرضية"]'::jsonb, null, '[164,165,179,180]'::jsonb, 'مغطى', 'ص164 الشكل 6-3b (أقصى ارتفاع، المدى الأفقي R، الزاوية θ، والجمع الاتجاهي لـ v_x و v_y عند كل موضع)؛ ص165 رسم المثال 1؛ ص179؛ ص180 السؤال 28 (الشكل 6-11).', null, 'approved', '2026-11-16'::timestamptz),
(10106112, 101061, 'P1-C6-L1-O12', null, 12, 'أن يحل الطالب مسائل حسابية على المقذوفات التي تطلق بزاوية', 'أن يحل الطالب مسائل حسابية على المقذوفات التي تُطلق بزاوية.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على المقذوفات التي تُطلق بزاوية.', 'إضافة علامة الترقيم وضبط «تُطلق».', 'لغوي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["المقذوف المطلق بزاوية","زمن التحليق","أقصى ارتفاع","المدى الأفقي"]'::jsonb, null, '[165,166,167,181,183]'::jsonb, 'مغطى', 'ص165 المثال 1 (أقصى ارتفاع 0.86 m وزمن تحليق 0.84 s)؛ ص166 المسائل 3–5؛ ص167 المراجعة 7–8؛ ص181 السؤال 41؛ ص183 السؤالان 1 و6.', null, 'approved', '2026-11-16'::timestamptz),
(10106113, 101061, 'P1-C6-L1-O13', null, 13, 'أن يوضح الطالب أثر مقاومة الهواء في حركة المقذوفات.', 'أن يوضح الطالب أثر مقاومة الهواء في حركة المقذوفات.', '[]'::jsonb, 'أن يوضح الطالب أثر مقاومة الهواء في حركة المقذوفات.', 'الهدف سليم.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["مقاومة الهواء","المدى الأفقي"]'::jsonb, null, '[166]'::jsonb, 'مغطى', 'ص166 «مقاومة الهواء»: النتوءات على كرة الجولف تقلل مقاومة الهواء فيزداد المدى الأفقي، ودوران كرة البيسبول يحرفها عن مسارها، و«قوة مقاومة الهواء موجودة دائمًا، وقد تكون مهمة».', null, 'approved', '2026-11-16'::timestamptz),
(10106114, 101061, 'P1-C6-L1-O14', null, 14, 'أن يوضّح الطالب أن الحركتين الأفقية والرأسية للمقذوف مستقلتان، مستشهدًا بمقارنة كرة مقذوفة أفقيًا بأخرى تسقط سقوطًا حرًّا من الارتفاع نفسه.', 'أن يوضّح الطالب أن الحركتين الأفقية والرأسية للمقذوف مستقلتان، مستشهدًا بمقارنة كرة مقذوفة أفقيًا بأخرى تسقط سقوطًا حرًّا من الارتفاع نفسه.', '[]'::jsonb, 'أن يوضّح الطالب أن الحركتين الأفقية والرأسية للمقذوف مستقلتان، مستشهدًا بمقارنة كرة مقذوفة أفقيًا بأخرى تسقط سقوطًا حرًّا من الارتفاع نفسه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["استقلالية الحركة في بعدين","السقوط الحر"]'::jsonb, null, '[161,162,163,179]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). هدف الدرس ص161 «تلاحظ أن الحركتين الأفقية والرأسية للمقذوف مستقلتان»؛ ص162 «استقلالية الحركة في بعدين» والشكل 6-1 والتجربة «السقوط من فوق الحافة»؛ ص163 الشكل 6-2؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106115, 101061, 'P1-C6-L1-O15', null, 15, 'أن يعرّف الطالب كلًّا من: مسار المقذوف، والمدى الأفقي، وزمن التحليق.', 'أن يعرّف الطالب كلًّا من: مسار المقذوف، والمدى الأفقي، وزمن التحليق.', '[]'::jsonb, 'أن يعرّف الطالب كلًّا من: مسار المقذوف، والمدى الأفقي، وزمن التحليق.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["مسار المقذوف","المدى الأفقي","زمن التحليق"]'::jsonb, null, '[161,164,179]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). مفردات الدرس ص161؛ ص161 تعريف مسار المقذوف؛ ص164: «المدى الأفقي R وهي المسافة الأفقية التي يقطعها المقذوف. أما زمن التحليق فهو الزمن الذي يقضيه المقذوف في الهواء».', null, 'approved', '2026-11-16'::timestamptz),
(10106116, 101061, 'P1-C6-L1-O16', null, 16, 'أن يستنتج الطالب تماثل حركة المقذوف الذي يعود إلى مستوى إطلاقه: زمن الصعود يساوي زمن النزول، ومقدار السرعة الرأسية متساوٍ عند الارتفاع نفسه صعودًا ونزولًا.', 'أن يستنتج الطالب تماثل حركة المقذوف الذي يعود إلى مستوى إطلاقه: زمن الصعود يساوي زمن النزول، ومقدار السرعة الرأسية متساوٍ عند الارتفاع نفسه صعودًا ونزولًا.', '[]'::jsonb, 'أن يستنتج الطالب تماثل حركة المقذوف الذي يعود إلى مستوى إطلاقه: زمن الصعود يساوي زمن النزول، ومقدار السرعة الرأسية متساوٍ عند الارتفاع نفسه صعودًا ونزولًا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["تماثل مسار المقذوف","زمن الصعود","زمن النزول","زمن التحليق"]'::jsonb, null, '[164,165,180]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص164 «لاحظ التماثل في مقادير السرعة الرأسية، حيث يتساوى مقدار السرعة في أثناء الصعود والنزول عند كل نقطة»؛ ص165 المثال 1 «زمن الصعود = زمن النزول، زمن التحليق = 2t»؛ ص180 السؤالان 33–34.', null, 'approved', '2026-11-16'::timestamptz),
(10106117, 101061, 'P1-C6-L1-O17', null, 17, 'أن يفسّر الطالب كيف يعتمد شكل مسار المقذوف على الإطار المرجعي الذي يُلاحَظ منه.', 'أن يفسّر الطالب كيف يعتمد شكل مسار المقذوف على الإطار المرجعي الذي يُلاحَظ منه.', '[]'::jsonb, 'أن يفسّر الطالب كيف يعتمد شكل مسار المقذوف على الإطار المرجعي الذي يُلاحَظ منه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الإطار المرجعي","مسار المقذوف"]'::jsonb, null, '[161,166,180]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). هدف الدرس ص161 «تفسر كيف يعتمد شكل مسار المقذوف على الإطار المرجعي الذي يُلاحظ منه»؛ ص166 «مسارات المقذوفات تعتمد على موقع المشاهد» (كرة في حافلة)؛ ص180 السؤالان 29 و36.', null, 'approved', '2026-11-16'::timestamptz),
(10106201, 101062, 'P1-C6-L2-O01', null, 1, 'ان يوضح الطالب الحركة الدائرية المنتظمة', 'أن يوضّح الطالب المقصود بالحركة الدائرية المنتظمة.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالحركة الدائرية المنتظمة.', 'إثبات همزة «أن»، وإضافة «المقصود بـ» لأن الفعل «يوضح» لا يقع على المصطلح مباشرة، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الحركة الدائرية المنتظمة"]'::jsonb, null, '[168,179]'::jsonb, 'مغطى', 'ص168: «الحركة الدائرية المنتظمة هي حركة جسم أو جسيم بسرعة ثابتة المقدار حول دائرة نصف قطرها ثابت»؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106202, 101062, 'P1-C6-L2-O02', null, 2, 'ان يوضح الطالب المقصود بالتسارع المركزي', 'أن يوضّح الطالب المقصود بالتسارع المركزي.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالتسارع المركزي.', 'إثبات همزة «أن» وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["التسارع المركزي"]'::jsonb, null, '[168,169]'::jsonb, 'مغطى', 'ص168: «متجه التسارع في الحركة الدائرية المنتظمة يشير دائمًا إلى مركز الدائرة، لذا يسمى هذا التسارعُ التسارعَ المركزي» والشكل 6-6؛ ص169.', null, 'approved', '2026-11-16'::timestamptz),
(10106203, 101062, 'P1-C6-L2-O03', null, 3, 'ان يستنتج الطالب قانون حساب التسارع المركزي', 'أن يستنتج الطالب علاقة التسارع المركزي a_c = v²/r من تشابه مثلث متجهات الموقع ومثلث متجهات السرعة.', '[]'::jsonb, 'أن يستنتج الطالب علاقة التسارع المركزي a_c = v²/r من تشابه مثلث متجهات الموقع ومثلث متجهات السرعة.', 'إثبات همزة «أن» واستبدال «قانون حساب» بالعلاقة نفسها وطريقة استنتاجها في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["التسارع المركزي","تشابه المثلثات"]'::jsonb, null, '[169,179]'::jsonb, 'مغطى', 'ص169 «التسارع المركزي»: مقارنة مثلثي الشكلين 6-5b و6-6b، Δr/r = Δv/v، ثم a_c = v²/r؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106204, 101062, 'P1-C6-L2-O04', null, 4, 'ان يفسر الطالب تسارع الجسم الذي يتحرك بسرعة ثابتة المقدار في مسار دائري.', 'أن يفسّر الطالب تسارع الجسم الذي يتحرك بسرعة ثابتة المقدار في مسار دائري.', '[]'::jsonb, 'أن يفسّر الطالب تسارع الجسم الذي يتحرك بسرعة ثابتة المقدار في مسار دائري.', 'إثبات همزة «أن».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["التسارع المركزي","السرعة المتجهة"]'::jsonb, null, '[168,179,180]'::jsonb, 'مغطى', 'هدف الدرس ص168 «تفسر لماذا يتسارع الجسم الذي يتحرك بسرعة ثابتة المقدار في مسار دائري»؛ ص168 «لأن اتجاه حركة الحجر يتغير لحظيًا فإن السرعة المتجهة للحجر تتغير، لذلك فهو يتسارع»؛ ص180 السؤال 30.', null, 'approved', '2026-11-16'::timestamptz),
(10106205, 101062, 'P1-C6-L2-O05', null, 5, 'ان يصف الطالب كيف يعتمد مقدار التسارع المركزي على سرعة الجسم ونصف قطر مساره الدائري', 'أن يصف الطالب كيف يعتمد مقدار التسارع المركزي على مقدار سرعة الجسم ونصف قطر مساره الدائري.', '[]'::jsonb, 'أن يصف الطالب كيف يعتمد مقدار التسارع المركزي على مقدار سرعة الجسم ونصف قطر مساره الدائري.', 'إثبات همزة «أن» وإضافة علامة الترقيم و«مقدار» قبل السرعة وفق صياغة الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["التسارع المركزي","نصف القطر","مقدار السرعة"]'::jsonb, null, '[168,169,179]'::jsonb, 'مغطى', 'هدف الدرس ص168 «تصف كيف يعتمد مقدار التسارع المركزي على سرعة الجسم، ونصف قطر مساره الدائري»؛ ص169 صندوق a_c = v²/r «يساوي مقداره حاصل قسمة مربع السرعة على نصف قطر دائرة الحركة».', null, 'approved', '2026-11-16'::timestamptz),
(10106206, 101062, 'P1-C6-L2-O06', null, 6, 'ان يستنتج الطالب قانون حساب التسارع المركزي بدلالة الزمن الدوري', 'أن يستنتج الطالب علاقة التسارع المركزي بدلالة الزمن الدوري a_c = 4π²r/T².', '[]'::jsonb, 'أن يستنتج الطالب علاقة التسارع المركزي بدلالة الزمن الدوري a_c = 4π²r/T².', 'إثبات همزة «أن» واستبدال «قانون حساب» بالعلاقة نفسها كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["الزمن الدوري","التسارع المركزي"]'::jsonb, null, '[169,170,179]'::jsonb, 'مغطى', 'ص169: v = 2πr/T ومنه a_c = 4π²r/T²؛ ص170 المثال 2؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106207, 101062, 'P1-C6-L2-O07', null, 7, 'ان يوضح الطالب المقصود بالقوة المركزية', 'أن يوضّح الطالب المقصود بالقوة المركزية.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالقوة المركزية.', 'إثبات همزة «أن» وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة المركزية","القوة المحصلة"]'::jsonb, null, '[169,170]'::jsonb, 'مغطى', 'ص169: «لا بد أن تكون القوة المحصلة في اتجاه مركز الدائرة أيضًا ... وتسمى هذه القوةُ القوةَ المركزية»؛ ص170 «القوة المركزية هي تسمية أخرى لمحصلة القوى المؤثرة في اتجاه المركز».', null, 'approved', '2026-11-16'::timestamptz),
(10106208, 101062, 'P1-C6-L2-O08', null, 8, 'ان يحدد الطالب كيفية حركة جسم يتحرك حركة دائرية عند اختفاء القوة المركزية', 'أن يحدّد الطالب اتجاه حركة جسم يتحرك حركة دائرية عند زوال القوة المركزية (في خط مستقيم في اتجاه المماس للمسار عند نقطة الإفلات).', '[]'::jsonb, 'أن يحدّد الطالب اتجاه حركة جسم يتحرك حركة دائرية عند زوال القوة المركزية (في خط مستقيم في اتجاه المماس للمسار عند نقطة الإفلات).', 'إثبات همزة «أن» وتوضيح المطلوب تحديده كما يذكره الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["القوة المركزية","السرعة المماسية","القانون الأول لنيوتن"]'::jsonb, null, '[169,170,171]'::jsonb, 'مغطى', 'ص169 الشكل 6-7 (المطرقة تسير في خط مستقيم مماسي)؛ ص170 «لذا تنطلق المطرقة في اتجاه سرعتها المماسية للدائرة عند نقطة إفلاتها»؛ ص171 الشكل 6-8.', null, 'approved', '2026-11-16'::timestamptz),
(10106209, 101062, 'P1-C6-L2-O09', null, 9, 'ان يحل الطالب مسائل حسابية على الحركة الدائرية', 'أن يحلّ الطالب مسائل حسابية على الحركة الدائرية المنتظمة.', '[]'::jsonb, 'أن يحلّ الطالب مسائل حسابية على الحركة الدائرية المنتظمة.', 'إثبات همزة «أن» وإضافة «المنتظمة» وعلامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["التسارع المركزي","القوة المركزية","الزمن الدوري"]'::jsonb, null, '[170,171,181,183]'::jsonb, 'مغطى', 'ص170 المثال 2 (سدادة 13 g ← F_T = 0.34 N)؛ ص171 المسائل 10–12 والمراجعة 15 و17؛ ص181 الأسئلة 42–44؛ ص183 الأسئلة 2–4 و9.', null, 'approved', '2026-11-16'::timestamptz),
(10106210, 101062, 'P1-C6-L2-O10', null, 10, 'ان يذكر الطالب امثلة حياتية على القوة المركزية المسببة للتسارع المركزي', 'أن يذكر الطالب أمثلة حياتية على القوة المركزية المسببة للتسارع المركزي، محددًا مصدرها في كل مثال.', '[]'::jsonb, 'أن يذكر الطالب أمثلة حياتية على القوة المركزية المسببة للتسارع المركزي، محددًا مصدرها في كل مثال.', 'إثبات همزة «أن» وتصحيح «امثلة»، وإضافة تحديد مصدر القوة كما يطلب الكتاب في مسائله.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'مفاهيم', '["القوة المركزية","قوة التجاذب الكتلي","قوة الشد","قوة الاحتكاك"]'::jsonb, null, '[169,171,181]'::jsonb, 'مغطى', 'ص169: دوران الأرض حول الشمس (قوة التجاذب الكتلي) ودوران المطرقة (قوة الشد)؛ ص171 المسألة 10 «ما مصدر القوة المؤثرة فيه؟» والمراجعة 13 و18؛ ص181 السؤال 44 (الاحتكاك).', null, 'approved', '2026-11-16'::timestamptz),
(10106211, 101062, 'P1-C6-L2-O11', null, 11, 'ان يوضح الطالب المقصود بقوة الطرد المركزي', 'أن يفسّر الطالب أن قوة الطرد المركزي قوة وهمية لا وجود لها، وأن اندفاع الراكب نحو خارج المنعطف ناتج عن قصوره الذاتي (القانون الأول لنيوتن).', '[]'::jsonb, 'أن يفسّر الطالب أن قوة الطرد المركزي قوة وهمية لا وجود لها، وأن اندفاع الراكب نحو خارج المنعطف ناتج عن قصوره الذاتي (القانون الأول لنيوتن).', 'الأصل «يوضح المقصود بقوة الطرد المركزي» يوحي بأنها قوة حقيقية تُعرَّف، والكتاب ينص على أنها «قوة وهمية» «لا وجود لها» وأن قوانين نيوتن تفسر الحركة الدائرية دونها (ص171)؛ كما أُثبتت همزة «أن».', 'تصحيح علمي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة الوهمية","قوة الطرد المركزي","القانون الأول لنيوتن"]'::jsonb, null, '[171]'::jsonb, 'مغطى', 'ص171 «القوة الوهمية»: «أما ما يتحدث عنه البعض ... من أن هناك قوة تدفع الراكب إلى الخارج تسمى قوة الطرد المركزي فإن هذه القوة لا وجود لها»، والشكل 6-8، والمراجعة 16.', null, 'approved', '2026-11-16'::timestamptz),
(10106212, 101062, 'P1-C6-L2-O12', null, 12, 'أن يعرّف الطالب الزمن الدوري ويحسب مقدار سرعة جسم يتحرك حركة دائرية منتظمة من العلاقة v = 2πr/T.', 'أن يعرّف الطالب الزمن الدوري ويحسب مقدار سرعة جسم يتحرك حركة دائرية منتظمة من العلاقة v = 2πr/T.', '[]'::jsonb, 'أن يعرّف الطالب الزمن الدوري ويحسب مقدار سرعة جسم يتحرك حركة دائرية منتظمة من العلاقة v = 2πr/T.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وقوانين', '["الزمن الدوري","مقدار السرعة","محيط الدائرة"]'::jsonb, null, '[169,181]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص169: «قياس الزمن اللازم لإكمال دورة كاملة T، ويسمى الزمن الدوري ... يكون مقدار السرعة يساوي v = 2πr/T»؛ ص181 السؤال 42.', null, 'approved', '2026-11-16'::timestamptz),
(10106213, 101062, 'P1-C6-L2-O13', null, 13, 'أن يحدّد الطالب اتجاه متجه السرعة (مماسي للمسار وعمودي على متجه الموقع) واتجاه متجه التسارع (نحو المركز) لجسم يتحرك حركة دائرية منتظمة.', 'أن يحدّد الطالب اتجاه متجه السرعة (مماسي للمسار وعمودي على متجه الموقع) واتجاه متجه التسارع (نحو المركز) لجسم يتحرك حركة دائرية منتظمة.', '[]'::jsonb, 'أن يحدّد الطالب اتجاه متجه السرعة (مماسي للمسار وعمودي على متجه الموقع) واتجاه متجه التسارع (نحو المركز) لجسم يتحرك حركة دائرية منتظمة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["متجه الموقع","السرعة المماسية","التسارع المركزي"]'::jsonb, null, '[168,179]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص168 «متجه السرعة عموديّ على متجه الموقع؛ أي مماسّ لمحيط الدائرة ... يبقى مقداره ثابتًا، لكن اتجاهه يتغير» والشكلان 6-5 و6-6؛ ص179 «متجه السرعة لجسم له تسارع مركزي يكون دائمًا في اتجاه المماس للمسار الدائري».', null, 'approved', '2026-11-16'::timestamptz),
(10106214, 101062, 'P1-C6-L2-O14', null, 14, 'أن يطبّق الطالب القانون الثاني لنيوتن في الحركة الدائرية (F_محصلة = m a_c) باختيار محورين: مركزي (c) ومماسي (tang).', 'أن يطبّق الطالب القانون الثاني لنيوتن في الحركة الدائرية (F_محصلة = m a_c) باختيار محورين: مركزي (c) ومماسي (tang).', '[]'::jsonb, 'أن يطبّق الطالب القانون الثاني لنيوتن في الحركة الدائرية (F_محصلة = m a_c) باختيار محورين: مركزي (c) ومماسي (tang).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وقوانين', '["القانون الثاني لنيوتن في الحركة الدائرية","المحور المركزي","المحور المماسي"]'::jsonb, null, '[169,170,179]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص169 صندوق «القانون الثاني لنيوتن في الحركة الدائرية F_محصلة = m a_c»؛ ص170 «من المفيد اختيار محورين ... المحور c ... والمحور tang» والمثال 2؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106301, 101063, 'P1-C6-L3-O01', null, 1, 'ان يحل الطالب مسائل تتعلق بالسرعة النسبية باستخدام رسم متجهات السرعة', 'أن يحلّ الطالب مسائل تتعلق بالسرعة المتجهة النسبية باستعمال رسم متجهات السرعة.', '[]'::jsonb, 'أن يحلّ الطالب مسائل تتعلق بالسرعة المتجهة النسبية باستعمال رسم متجهات السرعة.', 'إثبات همزة «أن»، واستعمال مصطلح الكتاب «السرعة المتجهة النسبية» بدل «السرعة النسبية»، و«استعمال» بدل «استخدام»، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["السرعة المتجهة النسبية","الجمع الاتجاهي","مثلث السرعات"]'::jsonb, null, '[173,174,175,182]'::jsonb, 'مغطى', 'ص173 المثال 3 (كرة على قارب ← 4.1 m/s بزاوية 11° شمال الشرق)؛ ص174 المسائل 19–21؛ ص175 المراجعة 22–26؛ ص182 الأسئلة 45–48؛ ص183 السؤال 5.', null, 'approved', '2026-11-16'::timestamptz),
(10106302, 101063, 'P1-C6-L3-O02', null, 2, 'ان يوضح الطالب السرعة النسبية المتجهة لجسم باستخدام رسم متجهات السرعة', 'أن يوضّح الطالب مفهوم السرعة المتجهة النسبية لجسم باستعمال رسم متجهات السرعة.', '[]'::jsonb, 'أن يوضّح الطالب مفهوم السرعة المتجهة النسبية لجسم باستعمال رسم متجهات السرعة.', 'إثبات همزة «أن»، وضبط المصطلح «السرعة المتجهة النسبية» كما في الكتاب، وإضافة «مفهوم» وعلامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["السرعة المتجهة النسبية","الإطار المرجعي"]'::jsonb, null, '[172,173,174]'::jsonb, 'مغطى', 'ص172 الشكل 6-9 (أنت بالنسبة إلى القطار، والقطار بالنسبة إلى الأرض)؛ ص173 الشكل 6-10 (الطائرة والهواء)؛ ص174 «مفتاح التحليل الصحيح ... هو الرسم الصحيح لمثلث يمثل السرعات المتجهة الثلاث».', null, 'approved', '2026-11-16'::timestamptz),
(10106303, 101063, 'P1-C6-L3-O03', null, 3, 'أن يكتب الطالب معادلة السرعة المتجهة النسبية v_a/c = v_a/b + v_b/c ويفسّر دلالة رموزها.', 'أن يكتب الطالب معادلة السرعة المتجهة النسبية v_a/c = v_a/b + v_b/c ويفسّر دلالة رموزها.', '[]'::jsonb, 'أن يكتب الطالب معادلة السرعة المتجهة النسبية v_a/c = v_a/b + v_b/c ويفسّر دلالة رموزها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["السرعة المتجهة النسبية"]'::jsonb, null, '[172,179]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص172 صندوق «السرعة المتجهة النسبية v_a/c = v_a/b + v_b/c: سرعة الجسم a بالنسبة إلى الجسم c هي حاصل الجمع الاتجاهي ...»؛ ص179.', null, 'approved', '2026-11-16'::timestamptz),
(10106304, 101063, 'P1-C6-L3-O04', null, 4, 'أن يحسب الطالب السرعة المتجهة النسبية في بُعد واحد بالجمع عندما تكون الحركتان في الاتجاه نفسه، وبالطرح عندما تكونان متعاكستين.', 'أن يحسب الطالب السرعة المتجهة النسبية في بُعد واحد بالجمع عندما تكون الحركتان في الاتجاه نفسه، وبالطرح عندما تكونان متعاكستين.', '[]'::jsonb, 'أن يحسب الطالب السرعة المتجهة النسبية في بُعد واحد بالجمع عندما تكون الحركتان في الاتجاه نفسه، وبالطرح عندما تكونان متعاكستين.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["السرعة المتجهة النسبية","الحركة في خط مستقيم"]'::jsonb, null, '[172,174,180,183]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص172 الشكل 6-9 (21 m/s و19 m/s) «إذا كانت الحركة في خط مستقيم فإن الجمع والطرح يستعملان لإيجاد السرعة المتجهة النسبية»؛ ص174 المسألتان 19–20؛ ص180 السؤال 32؛ ص183 السؤال 5.', null, 'approved', '2026-11-16'::timestamptz),
(10106305, 101063, 'P1-C6-L3-O05', null, 5, 'أن يحلّل الطالب حالات يكون فيها نظام المحاور (الإطار المرجعي) متحركًا، مثل قارب في نهر جارٍ أو طائرة تهب عليها رياح.', 'أن يحلّل الطالب حالات يكون فيها نظام المحاور (الإطار المرجعي) متحركًا، مثل قارب في نهر جارٍ أو طائرة تهب عليها رياح.', '[]'::jsonb, 'أن يحلّل الطالب حالات يكون فيها نظام المحاور (الإطار المرجعي) متحركًا، مثل قارب في نهر جارٍ أو طائرة تهب عليها رياح.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["الإطار المرجعي المتحرك","السرعة المتجهة النسبية"]'::jsonb, null, '[172,173,174,175]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). هدف الدرس ص172 «تحلل حالات تكون فيها مجموعة المحاور متحركة»؛ ص173 الملاحون الجويون والقارب في تيار؛ ص174 الربط مع الأحياء (هجرة طيور الخرشنة)؛ ص175 السؤال 26.', null, 'approved', '2026-11-16'::timestamptz)
on conflict do nothing;

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-11-16'::timestamptz
from public.objectives o where o.code like 'P1-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-11-16'::timestamptz
from public.objectives o where o.code like 'P1-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C1-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالفيزياء؟', null, null, '["فرع من العلم يدرس تركيب الكائنات الحية ووظائفها","فرع من العلم يدرس المادة والطاقة والعلاقة بينهما","فرع من العلم يدرس تحوّل المواد إلى مواد جديدة","فرع من الرياضيات يدرس الأعداد والمعادلات والأشكال المجردة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 10 — ما الفيزياء؟'),
('mcq', 2, 'أكمل التعريف: الفيزياء علم دراسة ............ والعلاقة بينهما.', null, null, '["الكتلة والحجم","القوة والحركة","الضوء والصوت والحرارة","المادة والطاقة"]'::jsonb, 'تذكر', 'إكمال تعريف', 'سهل', 'الكتاب ص 25 — دليل مراجعة الفصل (المفاهيم الرئيسة)'),
('mcq', 3, 'أيّ الأسئلة الآتية سؤال فيزيائي لأنه يتناول المادة والطاقة في العالم الطبيعي؟', null, null, '["كيف تتغير سرعة قطعة نقد معدنية في أثناء سقوطها؟","كيف تنقسم الخلايا وتتكاثر في جذور النباتات الصغيرة؟","كيف تنتقل الصفات الوراثية من الآباء إلى الأبناء؟","كيف تتكيف الحيوانات الصحراوية مع قلة الماء؟"]'::jsonb, 'فهم', 'تطبيق تعريف', 'سهل', 'الكتاب ص 10 — ما الفيزياء؟'),
('mcq', 4, 'قال طالب: «الفيزياء علم يقتصر على حفظ المعادلات الرياضية». ما التصحيح الأدق لعبارته؟', null, null, '["عبارته صحيحة؛ فالفيزياء فرع من فروع الرياضيات","الفيزياء علم يقتصر على دراسة الأجهزة التقنية الحديثة","الفيزياء تدرس المادة والطاقة والعلاقة بينهما، والمعادلات أداة للتعبير عن ذلك","الفيزياء علم يدرس الكائنات الحية وعلاقتها بالبيئة"]'::jsonb, 'فهم', 'تصحيح مفهوم خاطئ', 'متوسط', 'الكتاب ص 10 — ما الفيزياء؟'),
('mcq', 5, 'الطاقة والمادة وكيفية ارتباطهما في العالم الطبيعي هي موضوع دراسة أيّ فرع من فروع العلم؟', null, null, '["علم الأحياء","علم الأرض","علم الفلك","الفيزياء"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 25 — دليل مراجعة الفصل (المفاهيم الرئيسة)'),
('mcq', 6, 'لماذا تُعد دراسة سقوط قطع النقد المعدنية موضوعًا فيزيائيًّا؟', null, null, '["لأنها تتناول حركة أجسام مادية وما يرتبط بها من طاقة","لأن القطع مصنوعة من فلز يتفاعل مع الهواء","لأنها تجربة عملية تُجرى داخل المختبر المدرسي بأدوات بسيطة","لأنها تعتمد على الحسابات الرياضية وحدها دون مشاهدة"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 9 — التجربة الاستهلالية'),
('mcq', 7, 'عرّف طالب الفيزياء بأنها «علم دراسة المادة». ما الذي ينقص تعريفه؟', null, null, '["وحدات القياس في النظام الدولي","أدوات القياس والأجهزة المستخدمة في المختبر","الطاقة والعلاقة بين المادة والطاقة","الكائنات الحية والعلاقة بينها"]'::jsonb, 'فهم', 'تحليل تعريف ناقص', 'متوسط', 'الكتاب ص 25 — دليل مراجعة الفصل (المفاهيم الرئيسة)'),
('essay', 1, 'عرّف الفيزياء، ثم اذكر الشيئين اللذين يتناولهما تعريفها وما الذي تدرسه بينهما.', null, null, null, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 10 — ما الفيزياء؟'),
('essay', 2, 'يدرس الفيزيائيون حركة الصواريخ، والطاقة في الموجات الصوتية. اشرح لماذا يقع كلا الموضوعين ضمن علم الفيزياء، مستندًا إلى تعريفه.', null, null, null, 'فهم', 'تفسير بالاستناد إلى تعريف', 'صعب', 'الكتاب ص 10 — ما الفيزياء؟'),
('essay', 3, 'صنّف الأسئلة الآتية إلى أسئلة يدرسها علم الفيزياء وأخرى لا يدرسها، مع التعليل في ضوء تعريف الفيزياء: (أ) لماذا تسقط الأجسام نحو الأرض؟ (ب) كيف تنتقل الطاقة في دائرة كهربائية؟ (ج) كيف ينتشر مرض معدٍ بين الناس؟ (د) ما الذي تتكون منه المادة في أصلها؟', null, null, null, 'تحليل', 'تصنيف وتعليل', 'صعب', 'الكتاب ص 10 — ما الفيزياء؟')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الفيزياء فرع من فروع العلم يُعنى بدراسة العالم الطبيعي: الطاقة والمادة وكيفية ارتباطهما؛ أي إنها علم دراسة المادة والطاقة والعلاقة بينهما.', '["هذا وصف علم الأحياء الذي يدرس الكائنات الحية، لا وصف الفيزياء.","","دراسة تحوّل المواد إلى مواد جديدة من موضوعات علم الكيمياء.","الرياضيات لغة تستخدمها الفيزياء، لكن الفيزياء علم يدرس العالم الطبيعي لا الأعداد المجردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-17T19:43:12.752Z"}'::jsonb),
('mcq', 2, 3, 'تُعرَّف الفيزياء بأنها علم دراسة المادة والطاقة والعلاقة بينهما.', '["الكتلة والحجم خاصيتان من خواص المادة فقط، ولا يشمل ذلك الطاقة.","القوة والحركة من موضوعات الفيزياء، لكنهما لا تمثلان ما يتناوله تعريفها العام.","الضوء والصوت والحرارة صور من صور الطاقة فقط، ولا يشمل ذلك المادة والعلاقة بينهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.753Z"}'::jsonb),
('mcq', 3, 0, 'سقوط قطعة النقد ظاهرة طبيعية تتعلق بحركة جسم مادي وما يرتبط بها من طاقة، وهذا من صميم ما تدرسه الفيزياء.', '["","تكاثر الخلايا موضوع من موضوعات علم الأحياء.","انتقال الصفات الوراثية موضوع من علم الأحياء يتعلق بالكائنات الحية، لا بالمادة والطاقة عمومًا.","تكيّف الحيوانات مع بيئتها موضوع من علم الأحياء، لا من موضوعات الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.753Z"}'::jsonb),
('mcq', 4, 2, 'الفيزياء علم يدرس المادة والطاقة والعلاقة بينهما في العالم الطبيعي، ويستخدم الرياضيات لغةً للتعبير عن القوانين والظواهر، فالمعادلات وسيلة لا غاية.', '["الفيزياء فرع من فروع العلم يدرس العالم الطبيعي، وليست فرعًا من الرياضيات وإن استخدمتها.","الأجهزة التقنية من تطبيقات الفيزياء، وموضوعها أوسع من ذلك؛ إنه المادة والطاقة.","","دراسة الكائنات الحية وعلاقتها بالبيئة من موضوعات علم الأحياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.753Z"}'::jsonb),
('mcq', 5, 3, 'الفيزياء فرع من فروع العلم يُعنى بدراسة العالم الطبيعي: الطاقة والمادة وكيفية ارتباطهما.', '["علم الأحياء يدرس الكائنات الحية وعملياتها الحيوية.","علم الأرض يدرس الأرض وصخورها وتركيبها، ولا يُعرَّف بدراسة المادة والطاقة عمومًا.","علم الفلك مجال مرتبط بالفيزياء، لكنه يختص بالأجرام السماوية، والتعريف المذكور هو تعريف الفيزياء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.753Z"}'::jsonb),
('mcq', 6, 0, 'يجعل الموضوعَ فيزيائيًّا أنه يتناول المادة (أجسام تسقط) والطاقة المرتبطة بحركتها، وهذا ما تدرسه الفيزياء.', '["","تفاعل الفلز مع الهواء موضوع كيميائي، وليس هو ما يجعل دراسة السقوط فيزيائية.","مكان إجراء التجربة لا يحدد نوع العلم؛ فالمختبر يُستخدم في علوم كثيرة.","التجربة تقوم على المشاهدة، والرياضيات أداة للتعبير لا موضوع الدراسة؛ وما يجعل الموضوع فيزيائيًّا أنه يتناول المادة والطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-17T19:43:12.753Z"}'::jsonb),
('mcq', 7, 2, 'الفيزياء علم دراسة المادة والطاقة والعلاقة بينهما؛ فاقتصار التعريف على المادة يُسقط الطاقة وارتباطها بالمادة.', '["وحدات القياس أدوات يستخدمها الفيزيائي، وليست جزءًا من تعريف الفيزياء.","أدوات القياس وسائل للدراسة، ولا يتضمنها تعريف الفيزياء.","","الكائنات الحية موضوع علم الأحياء، ولا تدخل في تعريف الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.754Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفيزياء فرع من فروع العلم يدرس العالم الطبيعي؛ فهي علم دراسة المادة والطاقة والعلاقة بينهما (كيفية ارتباطهما).', '["الفيزياء فرع من فروع العلم يدرس العالم الطبيعي","تتناول المادة والطاقة","تدرس العلاقة بين المادة والطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف بوصفها فرعًا من العلم يدرس العالم الطبيعي","marks":1},{"element":"ذكر المادة والطاقة","marks":1},{"element":"ذكر العلاقة بينهما","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل يذكر المادة والطاقة والعلاقة بينهما"},{"level":"2 درجتان","description":"يذكر المادة والطاقة دون العلاقة بينهما أو العكس"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاقتصار على المادة أو على الطاقة وحدها","تعريف الفيزياء بأنها فرع من الرياضيات","الخلط بين تعريف الفيزياء وموضوعاتها الجزئية كالحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-17T19:43:12.754Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الفيزياء علم دراسة المادة والطاقة والعلاقة بينهما. حركة الصواريخ دراسة لأجسام مادية متحركة وما يلزم لتحريكها من طاقة، فهي تربط المادة بالطاقة. والموجات الصوتية تنقل طاقة عبر وسط مادي كالهواء، فدراستها دراسة للطاقة وارتباطها بالمادة. لذلك يقع الموضوعان ضمن علم الفيزياء.', '["ذكر تعريف الفيزياء","ربط حركة الصواريخ بالمادة والطاقة","ربط الموجات الصوتية بالطاقة وانتقالها في المادة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر التعريف","marks":1},{"element":"تعليل حركة الصواريخ","marks":1},{"element":"تعليل الموجات الصوتية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر التعريف ويربط كلا الموضوعين به ربطًا صحيحًا"},{"level":"2 درجتان","description":"يربط موضوعًا واحدًا بالتعريف ربطًا صحيحًا مع ذكر التعريف"},{"level":"1 درجة","description":"يذكر التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بالقول إنهما من موضوعات الفيزياء دون ربطهما بالتعريف","إغفال أن الصوت ينتقل في وسط مادي","ربط الصواريخ بالتقنية فقط دون المادة والطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.754Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) فيزيائي: يتناول حركة أجسام مادية والقوة والطاقة المرتبطة بها. (ب) فيزيائي: يتناول انتقال الطاقة الكهربائية في مواد موصلة. (ج) غير فيزيائي: موضوع من علم الأحياء والطب يتعلق بالكائنات الحية. (د) فيزيائي: يتناول المادة ومكوناتها وأصلها. والمعيار أن الفيزياء تدرس المادة والطاقة والعلاقة بينهما.', '["(أ) فيزيائي مع التعليل","(ب) فيزيائي مع التعليل","(ج) غير فيزيائي مع التعليل","(د) فيزيائي مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) وتعليله","marks":1},{"element":"تصنيف (ب) وتعليله","marks":1},{"element":"تصنيف (ج) وتعليله","marks":1},{"element":"تصنيف (د) وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يصنف الأسئلة الأربعة تصنيفًا صحيحًا مع تعليل يستند إلى التعريف"},{"level":"2–3 درجات","description":"يصنف بعض الأسئلة صحيحًا مع تعليل، أو يصنفها كلها دون تعليل كافٍ"},{"level":"1 درجة","description":"يصنف سؤالًا واحدًا صحيحًا مع تعليله"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ انتشار المرض موضوعًا فيزيائيًّا","التصنيف دون الاستناد إلى تعريف الفيزياء","عدّ سؤال مكونات المادة سؤالًا كيميائيًّا فقط وإغفال دراسة الفيزياء لأصل المادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.755Z"}'::jsonb)
