('mcq', 5, 0, 'نمو جذور النبات وامتصاصها للماء عملية حيوية يدرسها علم الأحياء، أما بقية الموضوعات فيدرسها علماء الفيزياء.', '["","الطاقة في الدوائر الكهربائية من موضوعات الفيزياء.","حركة الصواريخ من موضوعات الفيزياء.","الطاقة في الموجات الصوتية من موضوعات الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.756Z"}'::jsonb),
('mcq', 6, 2, 'انتقال الصوت عبر الهواء ومقدار ما يحمله من طاقة هو دراسة للطاقة في الموجات الصوتية.', '["حركة الإلكترونات موضوع مختلف يتعلق بجسيمات المادة الصغيرة لا بانتقال الصوت.","مكونات الكون وأصل المادة موضوع يتعلق بنشأة المادة لا بانتقال الصوت.","","قد يحتوي مكبر الصوت على دائرة كهربائية، لكن السؤال عن انتقال الصوت وطاقته في الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.757Z"}'::jsonb),
('mcq', 7, 1, 'يدرس علماء الفيزياء حركة الإلكترونات (أصغر الجسيمات) والصواريخ، والطاقة في الموجات والدوائر الكهربائية، ومكونات الكون وأصل المادة؛ فموضوعاتهم تمتد من الصغير جدًّا إلى الكون كله.', '["علماء الفيزياء يدرسون حركة الإلكترونات التي لا تُرى بالعين.","","الأجهزة التقنية من تطبيقات الفيزياء، وموضوعاتها أوسع من ذلك بكثير.","الدوائر الكهربائية موضوع واحد من موضوعات كثيرة يدرسها علماء الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.757Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الموضوعات التي يدرسها علماء الفيزياء: طبيعة حركة الإلكترونات، وحركة الصواريخ، والطاقة في الموجات الضوئية والصوتية، والطاقة في الدوائر الكهربائية، ومكونات الكون وأصل المادة.', '["حركة الإلكترونات","حركة الصواريخ","الطاقة في الموجات الضوئية والصوتية","الطاقة في الدوائر الكهربائية","مكونات الكون وأصل المادة"]'::jsonb, '[]'::jsonb, '[{"element":"الموضوع الأول","marks":1},{"element":"الموضوع الثاني","marks":1},{"element":"الموضوع الثالث","marks":1},{"element":"الموضوع الرابع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر أربعة موضوعات صحيحة"},{"level":"2–3 درجات","description":"يذكر موضوعين أو ثلاثة صحيحة"},{"level":"1 درجة","description":"يذكر موضوعًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مهن دارسي الفيزياء (كالهندسة والتعليم) بدل موضوعات الدراسة","ذكر موضوعات من علوم أخرى كالأحياء","تكرار الموضوع نفسه بصياغتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-17T19:43:12.757Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ضوء الشمس الذي يدفئ الأرض ويضيء الغرفة: موجات ضوئية تنقل طاقة. (ب) المصباح الكهربائي في المنزل: تنتقل الطاقة في دائرته الكهربائية فيضيء. (ج) سقوط كرة أو حركة سيارة: حركة جسم يدرس الفيزيائيون كيف تتغير سرعته. (تُقبل أمثلة صحيحة أخرى.)', '["مثال صحيح على الطاقة في الموجات الضوئية مع وجه الارتباط","مثال صحيح على الطاقة في الدوائر الكهربائية مع وجه الارتباط","مثال صحيح على حركة الأجسام مع وجه الارتباط"]'::jsonb, '[]'::jsonb, '[{"element":"مثال (أ) وارتباطه","marks":1},{"element":"مثال (ب) وارتباطه","marks":1},{"element":"مثال (ج) وارتباطه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع بيان وجه ارتباط كل منها"},{"level":"2 درجتان","description":"مثالان صحيحان مع الارتباط"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مثال لا يرتبط بالطاقة أو الحركة","الاكتفاء بالمثال دون بيان وجه الارتباط","الخلط بين الموجات الضوئية والصوتية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.757Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) فيزيائي: طبيعة حركة الصواريخ. (2) فيزيائي: الطاقة في الموجات الضوئية. (3) ليس من موضوعات الفيزياء: تشخيص المرض من الطب. (4) فيزيائي: مكونات الكون وأصل المادة.', '["(1) حركة الصواريخ","(2) الطاقة في الموجات الضوئية","(3) ليس موضوعًا فيزيائيًّا","(4) مكونات الكون وأصل المادة"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (1)","marks":1},{"element":"الحالة (2)","marks":1},{"element":"الحالة (3)","marks":1},{"element":"الحالة (4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد الحالات الأربع والموضوع المرتبط بكل منها صحيحًا"},{"level":"2–3 درجات","description":"يحدد حالتين أو ثلاثًا صحيحًا"},{"level":"1 درجة","description":"يحدد حالة واحدة صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تشخيص المرض موضوعًا فيزيائيًّا","عدّ دراسة نشأة الكون من علم الأحياء","تحديد الحالة دون ذكر الموضوع المرتبط بها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.758Z"}'::jsonb)
