('mcq', 1, 0, 'يعمل بعض دارسي الفيزياء باحثين في الجامعات والكليات أو في المصانع ومراكز الأبحاث.', '["","لا يقتصر العمل البحثي لدارسي الفيزياء على الجامعات والكليات؛ فبعضهم يعمل في المصانع ومراكز الأبحاث.","لا يقتصر عملهم البحثي على مراكز الأبحاث؛ فهم يعملون أيضًا في الجامعات والكليات والمصانع.","المختبرات المدرسية أماكن تعليم لا أماكن العمل البحثي، والباحثون يعملون في الجامعات والكليات والمصانع ومراكز الأبحاث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.758Z"}'::jsonb),
('mcq', 2, 2, 'من المجالات المرتبطة بعلم الفيزياء التي يعمل فيها دارسوه: الفلك والهندسة وعلم الحاسب ومجال التعليم والصيدلة.', '["حركة الإلكترونات والصواريخ موضوع يدرسه علماء الفيزياء، وليست مجالًا أو مهنة يعمل فيها دارسوها.","التاريخ والآثار من العلوم الإنسانية، وليسا من المجالات المرتبطة بالفيزياء.","","الطاقة في الدوائر الكهربائية موضوع يدرسه علماء الفيزياء، وليست مجالًا أو مهنة يعمل فيها دارسوها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-17T19:43:12.759Z"}'::jsonb),
('mcq', 3, 1, 'يستخدم بعض دارسي الفيزياء مهارات حل المشكلات الفيزيائية في مجالات الأعمال التجارية والمالية وغيرها.', '["أجهزة قياس الطاقة أدوات مختبرية لا تُستخدم في الأعمال المالية.","","قانون حفظ الشحنة قانون فيزيائي خاص بالظواهر الكهربائية، ولا يُطبق في الأعمال المالية.","نماذج الذرة أدوات لتفسير تركيب المادة، ولا صلة لها بالأعمال المالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.759Z"}'::jsonb),
('mcq', 4, 3, 'التدريس عمل في مجال التعليم، وهو من المجالات المرتبطة بالفيزياء التي يعمل فيها دارسوها.', '["البحث في المصانع عمل بحثي، وأحمد يدرّس الطلاب ولا يجري أبحاثًا.","الصيدلة مجال يتعلق بالأدوية، وعمل أحمد تدريس.","الفلك مجال يدرس الأجرام السماوية، وعمل أحمد تدريس الطلاب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.759Z"}'::jsonb),
('mcq', 5, 1, 'الفلك والهندسة والصيدلة كلها من المجالات المرتبطة بعلم الفيزياء التي يعمل فيها دارسوه.', '["الترجمة مجال لغوي ليس من المجالات المرتبطة بالفيزياء، فالمجموعة لا تصح كلها.","","التاريخ من العلوم الإنسانية وليس من المجالات المرتبطة بالفيزياء، فالمجموعة لا تصح كلها.","الأدب مجال لغوي وليس من المجالات المرتبطة بالفيزياء، فالمجموعة لا تصح كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.759Z"}'::jsonb),
('mcq', 6, 3, 'الهندسة من المجالات المرتبطة بعلم الفيزياء؛ فهي تطبق قوانينه ومهارات حل المشكلات فيه، ولذلك يعمل فيها دارسو الفيزياء.', '["الفيزياء تدرس المادة والطاقة والعلاقة بينهما، وتصميم الأجهزة تطبيق من تطبيقاتها لا حدودها.","الفيزياء تدرس المادة والطاقة والعلاقة بينهما وتستخدم الرياضيات لغةً لها، ولا تقتصر على حل المعادلات.","دارسو الفيزياء يعملون في مجالات كثيرة كالبحث والتعليم والفلك والصيدلة والأعمال المالية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.760Z"}'::jsonb),
('mcq', 7, 0, 'يعمل دارسو الفيزياء باحثين في الجامعات والمصانع ومراكز الأبحاث، وفي مجالات مرتبطة كالفلك والهندسة وعلم الحاسب والتعليم والصيدلة، ويستخدم آخرون مهاراتهم في الأعمال التجارية والمالية؛ فمجالات عملهم متنوعة.', '["","البحث في الجامعات مجال واحد من مجالات كثيرة يعمل فيها دارسو الفيزياء.","المصانع ومراكز الأبحاث جزء من مجالات العمل البحثي، وليست كل مجالات عملهم.","التدريس مجال واحد من المجالات المرتبطة بالفيزياء، وليس المجال الوحيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.760Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أماكن العمل البحثي: الجامعات والكليات، والمصانع، ومراكز الأبحاث. المجالات المرتبطة: الفلك، والهندسة، وعلم الحاسب، والتعليم، والصيدلة (يكفي ثلاثة).', '["ثلاثة أماكن بحثية: الجامعات والكليات، المصانع، مراكز الأبحاث","ثلاثة مجالات مرتبطة من: الفلك، الهندسة، علم الحاسب، التعليم، الصيدلة"]'::jsonb, '[]'::jsonb, '[{"element":"المكان البحثي الأول","marks":1},{"element":"المكان البحثي الثاني","marks":1},{"element":"المكان البحثي الثالث","marks":1},{"element":"المجال المرتبط الأول","marks":1},{"element":"المجال المرتبط الثاني","marks":1},{"element":"المجال المرتبط الثالث","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"يذكر ثلاثة أماكن بحثية وثلاثة مجالات مرتبطة صحيحة"},{"level":"3–5 درجات","description":"يذكر بعضها صحيحًا"},{"level":"1–2 درجة","description":"يذكر عنصرًا أو عنصرين صحيحين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر موضوعات يدرسها علماء الفيزياء (كحركة الصواريخ) بدل أماكن العمل والمهن","الخلط بين الأماكن البحثية والمجالات المرتبطة","ذكر مجالات لا ترتبط بالفيزياء كالأدب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-17T19:43:12.760Z"}'::jsonb),
('essay', 2, null::int, null, null, 'رأيه غير صحيح. فدارسو الفيزياء يعملون باحثين في الجامعات والكليات، وفي المصانع ومراكز الأبحاث أيضًا، ويعمل آخرون في مجالات مرتبطة بالفيزياء كالفلك والهندسة وعلم الحاسب والتعليم والصيدلة، ويستخدم غيرهم مهارات حل المشكلات الفيزيائية في الأعمال التجارية والمالية. فدراسة الفيزياء تفتح مجالات عمل متنوعة.', '["الحكم بأن الرأي غير صحيح","ذكر أماكن بحثية غير الجامعة (المصانع، مراكز الأبحاث)","ذكر مجالات مرتبطة بالفيزياء","ذكر استخدام مهارات حل المشكلات في الأعمال التجارية والمالية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الرأي","marks":1},{"element":"أماكن بحثية أخرى","marks":1},{"element":"مجالات مرتبطة","marks":1},{"element":"الأعمال التجارية والمالية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم بالأنواع الثلاثة من مجالات العمل"},{"level":"2–3 درجات","description":"حكم صحيح مع شواهد ناقصة"},{"level":"1 درجة","description":"حكم صحيح دون شواهد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد رأي الزميل","الاكتفاء بذكر مجال التعليم شاهدًا وحيدًا","ذكر موضوعات الدراسة بدل مجالات العمل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.760Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عمل بحثي: باحث في مركز أبحاث، باحث في مصنع. مجال مرتبط بالفيزياء: مهندس، معلم، صيدلي. مجال يستخدم مهارات حل المشكلات: محلل مالي في شركة تجارية.', '["الباحثان في مركز الأبحاث والمصنع: عمل بحثي","المهندس والمعلم والصيدلي: مجالات مرتبطة","المحلل المالي: يستخدم مهارات حل المشكلات"]'::jsonb, '[]'::jsonb, '[{"element":"فئة العمل البحثي","marks":1},{"element":"فئة المجالات المرتبطة","marks":1},{"element":"فئة مهارات حل المشكلات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يصنف المهن الست كلها صحيحًا"},{"level":"2 درجتان","description":"يصنف فئتين صحيحًا"},{"level":"1 درجة","description":"يصنف فئة واحدة صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المحلل المالي باحثًا","عدّ الصيدلي خارج مجالات عمل دارسي الفيزياء","عدّ الباحث في المصنع من المجالات المرتبطة بدل العمل البحثي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-17T19:43:12.760Z"}'::jsonb)
