('mcq', 2, 'مثّل طالب قياساته لطول نابض عند تعليق كتل مختلفة به بالرسم البياني الآتي. ما الفائدة الرئيسة لتمثيل القياسات بهذا الرسم بدل كتابتها في قائمة من الأرقام؟', null, '[{"src":"qimg/phys1/c1l1-o04-spring-data.svg","alt":"رسم بياني محوره الأفقي «الكتلة المعلقة (g)» من 0 إلى 100 بتدريج كل 20، ومحوره الرأسي «طول النابض (cm)» من 0 إلى 25 بتدريج كل 5. عليه ست نقاط قياس: (0، 10) و(20، 12) و(40، 14) و(60، 16) و(80، 18) و(100، 20)، يمر بها جميعًا خط مستقيم صاعد."}]'::jsonb, '["يجعل القياسات المسجلة أدق مما كانت عليه في الجدول","يُظهر النمط في البيانات بشكل واضح وسريع","يثبت أن الفرضية صحيحة في كل الظروف","يلغي الحاجة إلى ذكر وحدات القياس"]'::jsonb, 'فهم', 'تفسير فائدة الرسم البياني', 'متوسط', 'الكتاب ص 10 — الرياضيات في الفيزياء'),
('mcq', 3, 'في علم الفيزياء تمثل المعادلات الرياضية أداة مهمة. ما الدور الذي تؤديه؟', null, null, '["تسجيل أسماء الأدوات المستخدمة في التجربة","استبدال المشاهدات بأرقام لا ترتبط بالظاهرة","نمذجة المشاهدات ووضع التوقعات لتفسير الظواهر","إثبات صحة النظريات العلمية كلها دون حاجة إلى إجراء تجارب"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 10 — الرياضيات في الفيزياء'),
('mcq', 4, 'أسقط طالب قطعًا نقدية، ثم حسب سرعة سقوطها بنماذج رياضية مختلفة، وقارن ما حسبه بنتائج تجربته. ما الذي تتيحه له هذه المقارنة؟', null, null, '["اختيار أفضل النماذج وتطوير نموذج يعبّر عن الظاهرة بشكل أفضل","الاستغناء عن تكرار التجربة مرة أخرى","إثبات أن النماذج الرياضية المختلفة كلها صحيحة بالقدر نفسه تمامًا","معرفة الكتلة الدقيقة لكل قطعة نقدية"]'::jsonb, 'تطبيق', 'تطبيق في موقف', 'متوسط', 'الكتاب ص 10 — الرياضيات في الفيزياء'),
('mcq', 5, 'يعبَّر عن العلاقة بين فرق الجهد $V$ وشدة التيار $I$ والمقاومة $R$ بالمعادلة $V = IR$. ما الميزة التي تقدمها هذه الصيغة الرياضية؟', null, null, '["تبيّن أن الكميات الثلاث لا يرتبط بعضها ببعض","تجعل قياس الكميات الثلاث غير ضروري","تصف العلاقة بين الكميات الثلاث بإيجاز وتتيح حساب أيّ منها","تصلح لوصف دائرة كهربائية واحدة ذات قيم محددة فقط ولا تصلح لغيرها"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 11 — مثال 1'),
('mcq', 6, 'ما الإجابة الأدق عن السؤال: لماذا توصف المفاهيم في الفيزياء بواسطة المعادلات الرياضية؟', null, null, '["لأن المعادلات أسهل حفظًا من الكلمات","لأنها تعبّر عن العلاقات بين الكميات بدقة وتتيح التوقع والتحقق تجريبيًّا","لأن المفاهيم الفيزيائية لا يمكن وصفها بالكلمات أبدًا","لأن المعادلات لا تحتاج إلى مقارنة بنتائج التجارب"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 15 — مراجعة 1-1'),
('mcq', 7, 'تُعطى سرعة جسم يتحرك من السكون بتسارع ثابت $a$ بعد زمن $t$ بالعلاقة $v_f = at$. كيف تفيد هذه المعادلة الفيزيائي؟', null, null, '["تبيّن أن سرعة الجسم ثابتة لا تتغير مهما طال زمن حركته","تغنيه عن معرفة قيمة تسارع الجسم","تحدد الكتلة التي يجب أن تكون للجسم","تتيح له توقع سرعة الجسم عند أيّ لحظة قبل قياسها"]'::jsonb, 'تطبيق', 'توظيف معادلة في التوقع', 'متوسط', 'الكتاب ص 11 — مسائل تدريبية'),
('essay', 1, 'وضّح أهمية استخدام الرياضيات في الفيزياء، مع ذكر ثلاث فوائد لها.', null, null, null, 'فهم', 'توضيح أهمية', 'متوسط', 'الكتاب ص 10 — الرياضيات في الفيزياء'),
('essay', 2, 'سجّل طالب طول نابض عند تعليق كتل مختلفة به في الجدول الآتي. (أ) ما الذي يتيحه تمثيل هذه البيانات بيانيًّا مقارنة بقراءتها من الجدول؟ (ب) كيف يفيد التعبير عن العلاقة بمعادلة رياضية في دراسة النابض؟', '{"headers":["الكتلة المعلقة (g)","طول النابض (cm)"],"rows":[["0","10"],["20","12"],["40","14"],["60","16"],["80","18"],["100","20"]]}'::jsonb, null, null, 'تطبيق', 'تطبيق على بيانات', 'صعب', 'الكتاب ص 10 — الرياضيات في الفيزياء'),
('essay', 3, 'قال طالب: «يمكن دراسة الفيزياء دون رياضيات؛ فيكفي وصف الظواهر بالكلمات». قوّم هذه العبارة مع التعليل.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 10 — الرياضيات في الفيزياء')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
