from (values
('mcq', 1, 3, 'يستخدم علماء الفيزياء الرياضيات بوصفها لغة قادرة على التعبير عن القوانين والظواهر الفيزيائية بشكل واضح ومفهوم.', '["الرياضيات لا تغني عن التجربة؛ فنتائج الحسابات تُقارن بنتائج التجارب.","الحسابات لا تزيل أخطاء القياس؛ فلكل قياس حدود دقة.","الرياضيات تعبّر عن الظواهر بوضوح، ولا تزيدها تعقيدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.761Z"}'::jsonb),
('mcq', 2, 1, 'الرسوم البيانية تتيح الوصول إلى المعلومات بسرعة وسهولة؛ فالأنماط التي لا يمكن رؤيتها بسهولة في قائمة من الأرقام تأخذ شكلًا واضحًا عندما تُمثّل بالرسم، كالخط المستقيم هنا.', '["الرسم يعرض القياسات نفسها ولا يغيّر دقتها.","","الرسم يكشف النمط في هذه البيانات فقط، ولا يثبت صحة الفرضية في كل الظروف.","وحدات القياس تُكتب على محاور الرسم، والرسم لا يلغي الحاجة إليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.761Z"}'::jsonb),
('mcq', 3, 2, 'تمثل المعادلات الرياضية أداة مهمة لنمذجة المشاهدات ووضع التوقعات لتفسير الظواهر الفيزيائية المختلفة.', '["تسجيل أسماء الأدوات ليس دورًا للمعادلات الرياضية.","المعادلات تعبّر عن المشاهدات نفسها والعلاقات بين كمياتها، ولا تستبدلها بأرقام لا معنى لها.","","التوقعات المستنتجة من المعادلات يجب أن تُقارن بنتائج التجارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-17T19:43:12.761Z"}'::jsonb),
('mcq', 4, 0, 'بحساب سرعة الجسم الساقط يمكن مقارنة نتائج التجربة بما تتوقعه النماذج، مما يتيح اختيار أفضلها والشروع في تطوير نموذج رياضي جديد يعبّر عن الظاهرة بشكل أفضل.', '["","المقارنة لا تغني عن تكرار التجربة؛ فالتجارب يجب أن تكون قابلة للتكرار.","النماذج المختلفة تعطي إجابات مختلفة، والمقارنة تميّز الأفضل منها لا تثبت صحتها كلها.","الهدف من المقارنة تقويم النماذج، لا قياس كتلة القطع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-17T19:43:12.761Z"}'::jsonb),
('mcq', 5, 2, 'المعادلة لغة موجزة واضحة تعبّر عن العلاقة بين الكميات، ويمكن إعادة كتابتها لحساب أيّ كمية مجهولة إذا عُلمت الكميتان الأخريان.', '["المعادلة تربط الكميات الثلاث بعضها ببعض، فهي تدل على وجود علاقة بينها.","المعادلة تحتاج إلى قيم مقيسة لكميتين على الأقل لحساب الثالثة.","","المعادلة عامة تصلح لدوائر مختلفة بتعويض قيمها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.761Z"}'::jsonb),
('mcq', 6, 1, 'المعادلات لغة دقيقة تعبّر عن العلاقات بين الكميات الفيزيائية، وتسمح بوضع توقعات يمكن مقارنتها بنتائج التجارب للتحقق منها.', '["سهولة الحفظ ليست سبب استخدام المعادلات؛ فالسبب دقتها في التعبير عن العلاقات.","","المفاهيم توصف بالكلمات أيضًا، لكن المعادلات أدق وأوضح في التعبير عن العلاقات الكمية.","توقعات المعادلات يجب أن تُقارن بنتائج التجارب للحكم على صحتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-17T19:43:12.762Z"}'::jsonb),
('mcq', 7, 3, 'المعادلة نموذج رياضي يتيح حساب السرعة $v_f$ عند أيّ زمن $t$ إذا عُلم التسارع، أي وضع توقعات يمكن التحقق منها بالقياس.', '["المعادلة تبيّن أن السرعة تزداد بزيادة الزمن، لا أنها ثابتة.","حساب السرعة من المعادلة يتطلب معرفة التسارع $a$.","المعادلة لا تتضمن الكتلة، فلا تحددها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-17T19:43:12.762Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يستخدم علماء الفيزياء الرياضيات لأنها: (1) لغة قادرة على التعبير عن القوانين والظواهر الفيزيائية بشكل واضح ومفهوم. (2) المعادلات الرياضية أداة لنمذجة المشاهدات ووضع التوقعات لتفسير الظواهر، ومقارنة التوقعات بنتائج التجارب لاختيار أفضل النماذج وتطويرها. (3) الرسوم البيانية تتيح الوصول إلى المعلومات بسرعة وسهولة، وتُظهر الأنماط التي لا تُرى بسهولة في قوائم الأرقام.', '["لغة للتعبير عن القوانين والظواهر بوضوح","المعادلات أداة للنمذجة ووضع التوقعات","الرسوم البيانية تُظهر الأنماط وتتيح الوصول السريع إلى المعلومات"]'::jsonb, '[]'::jsonb, '[{"element":"الفائدة الأولى","marks":1},{"element":"الفائدة الثانية","marks":1},{"element":"الفائدة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يوضح ثلاث فوائد صحيحة"},{"level":"2 درجتان","description":"يوضح فائدتين صحيحتين"},{"level":"1 درجة","description":"يوضح فائدة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرياضيات تغني عن التجربة","ذكر الفائدة نفسها بصياغات مختلفة","إغفال دور الرسوم البيانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.762Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عند تمثيل البيانات بيانيًّا تأخذ النقاط شكل خط مستقيم صاعد، فيظهر بسرعة ووضوح أن طول النابض يزداد بمقادير متساوية عند زيادة الكتلة بمقادير متساوية، وهو نمط يصعب ملاحظته بسرعة في قائمة الأرقام. (ب) المعادلة الرياضية تصف العلاقة بين الكتلة والطول بإيجاز، وتتيح توقع طول النابض عند كتل لم تُقس، ثم التحقق من التوقع بالتجربة.', '["الرسم يُظهر النمط (خط مستقيم) بسرعة ووضوح","النمط يصعب ملاحظته في قائمة الأرقام","المعادلة تصف العلاقة بإيجاز","المعادلة تتيح التوقع والتحقق تجريبيًّا"]'::jsonb, '[]'::jsonb, '[{"element":"فائدة الرسم في إظهار النمط","marks":1},{"element":"المقارنة بالجدول","marks":1},{"element":"إيجاز المعادلة في وصف العلاقة","marks":1},{"element":"التوقع والتحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يجيب عن الجزأين إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"يجيب عن جزء واحد كاملًا أو عن الجزأين بنقص"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرسم يزيد دقة القياسات","إغفال إمكانية التوقع بالمعادلة","عدّ المعادلة بديلًا عن التجربة لا وسيلة للتوقع والتحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.762Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير دقيقة. فالكلمات قد تصف الظاهرة وصفًا عامًّا، لكن الرياضيات لغة قادرة على التعبير عن القوانين والظواهر بوضوح ودقة؛ فالمعادلات تنمذج المشاهدات وتتيح وضع توقعات كمية يمكن مقارنتها بنتائج التجارب واختيار أفضل النماذج، والرسوم البيانية تكشف أنماطًا لا تُرى في قوائم الأرقام. فمثلًا يمكن بالكلمات القول إن الجسم الساقط تزداد سرعته، أما المعادلة فتحدد مقدار سرعته عند كل لحظة.', '["الحكم بأن العبارة غير دقيقة","الرياضيات لغة دقيقة للتعبير عن القوانين","المعادلات تتيح التوقع الكمي والمقارنة بالتجربة","مثال يوضح الفرق بين الوصف اللفظي والرياضي"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"دقة لغة الرياضيات","marks":1},{"element":"التوقع والمقارنة بالتجربة","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل متكامل ومثال مناسب"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو دون مثال"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد العبارة","القول إن الرياضيات تغني عن التجربة","الحكم دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.762Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
