('mcq', 3, 'دراجة تبدأ الحركة من السكون بتسارع ثابت مقداره 1.5 m/s². ما سرعتها بعد 6.0 s؟ علمًا بأن $v_f = at$.', null, null, '["4.0 m/s","0.25 m/s","7.5 m/s","9.0 m/s"]'::jsonb, 'تطبيق', 'حساب بالتعويض', 'سهل', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية'),
('mcq', 4, 'قوة مقدارها 600 N تؤثر عموديًّا في سطح مساحته 0.040 m². ما الضغط المؤثر في السطح؟ علمًا بأن $P = \frac{F}{A}$.', null, null, '["$24\\ \\text{N/m}^2$","$6.7\\times10^{-5}\\ \\text{N/m}^2$","$1.5\\times10^{4}\\ \\text{N/m}^2$","$1.5\\times10^{3}\\ \\text{N/m}^2$"]'::jsonb, 'تطبيق', 'حساب وكتابة بالتعبير العلمي', 'متوسط', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية'),
('mcq', 5, 'سيارة كتلتها $1.5\times10^{3}\ \text{kg}$. ما مقدار وزنها؟ علمًا بأن $\boldsymbol{F} = m\boldsymbol{g}$ و$g = 9.80\ \text{m/s}^2$.', null, null, '["$1.5\\times10^{4}\\ \\text{N}$","$1.5\\times10^{3}\\ \\text{N}$","$1.5\\times10^{2}\\ \\text{N}$","$1.5\\times10^{5}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب بالتعبير العلمي', 'صعب', 'الكتاب ص 27 — إتقان حل المسائل 1-1'),
('mcq', 6, 'قطعة فلز كتلتها 540 g وحجمها 200 cm³. ما كثافتها؟ علمًا بأن $D = \frac{m}{V}$.', null, null, '["$0.37\\ \\text{g/cm}^3$","$1.1\\times10^{5}\\ \\text{g/cm}^3$","$3.4\\times10^{2}\\ \\text{g/cm}^3$","$2.7\\ \\text{g/cm}^3$"]'::jsonb, 'تطبيق', 'حساب بالتعويض', 'متوسط', 'الكتاب ص 26 — تقويم الفصل (السؤال 29)'),
('mcq', 7, 'تتكون قطرة ماء في المتوسط من $1.7\times10^{21}$ جزيء. إذا كان الماء يتبخر بمعدل مليون جزيء في الثانية، فما الزمن اللازم لتبخر القطرة تمامًا؟', null, null, '["$1.7\\times10^{18}\\ \\text{s}$","$1.7\\times10^{15}\\ \\text{s}$","$1.7\\times10^{27}\\ \\text{s}$","$5.9\\times10^{-16}\\ \\text{s}$"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 28 — تقويم الفصل (السؤال 40)'),
('essay', 1, 'إذا كان مقدار قوة جذب الأرض لجسم $632\ \text{kg}\cdot\text{m/s}^2$، فاحسب كتلة الجسم، علمًا بأن $\boldsymbol{F} = m\boldsymbol{g}$ و$g = 9.80\ \text{m/s}^2$، واكتب الناتج بالتعبير العلمي مع الوحدة.', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 27 — إتقان حل المسائل 1-1 (السؤال 32)'),
('essay', 2, 'تبدأ سيارة الحركة من السكون بتسارع ثابت مقداره 2.50 m/s² مدة 8.00 s. (أ) احسب سرعتها النهائية من العلاقة $v_f = at$. (ب) إذا كانت كتلة السيارة $1.20\times10^{3}\ \text{kg}$ فاحسب مقدار القوة المحصلة اللازمة لإكسابها هذا التسارع من العلاقة $\boldsymbol{F} = m\boldsymbol{a}$.', null, null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 29 — اختبار مقنن'),
('essay', 3, 'صندوق وزنه 450 N يستقر على قاعدة مساحتها 1500 cm². احسب الضغط الذي يؤثر به الصندوق في الأرض بوحدة N/m²، علمًا بأن $P = \frac{F}{A}$ و$1\ \text{m}^2 = 10^{4}\ \text{cm}^2$.', null, null, null, 'تطبيق', 'مسألة مع تحويل وحدات', 'صعب', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
