from (values
('mcq', 1, 1, '$F = mg = (12.0\ \text{kg})(9.80\ \text{m/s}^2) = 117.6\ \text{kg}\cdot\text{m/s}^2$، وتُقرّب إلى ثلاثة أرقام معنوية فتصبح 118 N.', '["قسمة الكتلة على $g$ بدل ضربهما: $12.0 \\div 9.80 = 1.22$.","","جمع الكتلة و$g$ بدل ضربهما: $12.0 + 9.80 = 21.8$.","خطأ في موضع الفاصلة العشرية؛ الناتج الصحيح 117.6 لا 11.76."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-17T19:43:12.764Z"}'::jsonb),
('mcq', 2, 0, '$V = IR = (0.50\ \text{A})(24\ \Omega) = 12\ \text{V}$.', '["","قسمة المقاومة على شدة التيار: $24 \\div 0.50 = 48$.","قسمة شدة التيار على المقاومة: $0.50 \\div 24 = 0.021$.","جمع الكميتين بدل ضربهما: $0.50 + 24 = 24.5$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.764Z"}'::jsonb),
('mcq', 3, 3, '$v_f = at = (1.5\ \text{m/s}^2)(6.0\ \text{s}) = 9.0\ \text{m/s}$.', '["قسمة الزمن على التسارع: $6.0 \\div 1.5 = 4.0$.","قسمة التسارع على الزمن: $1.5 \\div 6.0 = 0.25$.","جمع التسارع والزمن بدل ضربهما: $1.5 + 6.0 = 7.5$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.764Z"}'::jsonb),
('mcq', 4, 2, '$P = \frac{F}{A} = \frac{600\ \text{N}}{0.040\ \text{m}^2} = 15000\ \text{N/m}^2 = 1.5\times10^{4}\ \text{N/m}^2$ (رقمان معنويان كما في 0.040).', '["ضرب القوة في المساحة بدل القسمة: $600 \\times 0.040 = 24$.","قسمة المساحة على القوة: $0.040 \\div 600 = 6.7\\times10^{-5}$.","","خطأ في الأس عند كتابة الناتج بالتعبير العلمي؛ 15000 تساوي $1.5\\times10^{4}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.764Z"}'::jsonb),
('mcq', 5, 0, '$F = mg = (1.5\times10^{3}\ \text{kg})(9.80\ \text{m/s}^2) = 14700\ \text{N} \approx 1.5\times10^{4}\ \text{N}$ (رقمان معنويان).', '["","كتابة الكتلة على أنها الوزن دون ضربها في $g$.","قسمة الكتلة على $g$: $1500 \\div 9.80 \\approx 153$.","خطأ في جمع الأسس؛ ضرب $10^{3}$ في عدد قريب من 10 يعطي $10^{4}$ لا $10^{5}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-17T19:43:12.765Z"}'::jsonb),
('mcq', 6, 3, '$D = \frac{m}{V} = \frac{540\ \text{g}}{200\ \text{cm}^3} = 2.7\ \text{g/cm}^3$.', '["قسمة الحجم على الكتلة: $200 \\div 540 = 0.37$.","ضرب الكتلة في الحجم: $540 \\times 200 = 108000$.","طرح الحجم من الكتلة: $540 - 200 = 340$، وهي عملية لا تحددها العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-17T19:43:12.765Z"}'::jsonb),
('mcq', 7, 1, 'المليون يساوي $10^{6}$، والزمن = عدد الجزيئات ÷ معدل التبخر: $t = \frac{1.7\times10^{21}}{1\times10^{6}\ \text{s}^{-1}} = 1.7\times10^{21-6}\ \text{s} = 1.7\times10^{15}\ \text{s}$.', '["عدّ المليون $10^{3}$ بدل $10^{6}$، فطُرح الأس 3 بدل 6.","","ضرب عدد الجزيئات في المعدل بدل القسمة عليه، فجُمع الأسّان: $21+6 = 27$.","قسمة المعدل على عدد الجزيئات (قلب الكسر): $\\frac{10^{6}}{1.7\\times10^{21}} = 5.9\\times10^{-16}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.765Z"}'::jsonb),
('essay', 1, null::int, null, null, '$m = \frac{F}{g} = \frac{632\ \text{kg}\cdot\text{m/s}^2}{9.80\ \text{m/s}^2} = 64.5\ \text{kg} = 6.45\times10^{1}\ \text{kg}$ (ثلاثة أرقام معنوية).', '["$m = \\frac{F}{g}$ والتعويض الصحيح","الناتج $64.5\\ \\text{kg}$ بثلاثة أرقام معنوية","كتابته بالتعبير العلمي $6.45\\times10^{1}\\ \\text{kg}$"]'::jsonb, '["$m = \\frac{F}{g}$","$m = \\frac{632\\ \\text{kg}\\cdot\\text{m/s}^2}{9.80\\ \\text{m/s}^2}$","$m = 64.5\\ \\text{kg}$","$m = 6.45\\times10^{1}\\ \\text{kg}$"]'::jsonb, '[{"element":"العلاقة والتعويض","marks":1},{"element":"الناتج العددي والوحدة","marks":1},{"element":"التعبير العلمي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعويض صحيح وناتج صحيح بالوحدة والتعبير العلمي"},{"level":"2 درجتان","description":"ناتج صحيح دون تعبير علمي أو دون وحدة"},{"level":"1 درجة","description":"علاقة وتعويض صحيحان مع خطأ حسابي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب القوة في $g$ بدل القسمة عليه فيكون الناتج نحو 6190","كتابة الناتج 64.49 بأرقام معنوية أكثر من المعطيات","إهمال الوحدة أو كتابتها N"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-17T19:43:12.765Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $v_f = at = (2.50\ \text{m/s}^2)(8.00\ \text{s}) = 20.0\ \text{m/s}$. (ب) $F = ma = (1.20\times10^{3}\ \text{kg})(2.50\ \text{m/s}^2) = 3.00\times10^{3}\ \text{N}$.', '["$v_f = 20.0\\ \\text{m/s}$","$F = 3.00\\times10^{3}\\ \\text{N}$","الوحدات صحيحة في الجزأين"]'::jsonb, '["$v_f = at = (2.50)(8.00) = 20.0\\ \\text{m/s}$","$F = ma = (1.20\\times10^{3})(2.50)$","$F = 3.00\\times10^{3}\\ \\text{kg}\\cdot\\text{m/s}^2 = 3.00\\times10^{3}\\ \\text{N}$"]'::jsonb, '[{"element":"حساب السرعة","marks":2},{"element":"حساب القوة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الجزآن صحيحان بالوحدات والأرقام المعنوية"},{"level":"2–3 درجات","description":"جزء صحيح كاملًا والآخر فيه خطأ"},{"level":"1 درجة","description":"تعويض صحيح في أحد الجزأين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في السرعة بدل التسارع","كتابة 20 m/s بدل 20.0 m/s","خطأ في أس العشرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.766Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُحوّل المساحة: $A = 1500\ \text{cm}^2 \times \frac{1\ \text{m}^2}{10^{4}\ \text{cm}^2} = 0.1500\ \text{m}^2$. ثم $P = \frac{450\ \text{N}}{0.1500\ \text{m}^2} = 3.00\times10^{3}\ \text{N/m}^2$.', '["تحويل المساحة إلى 0.1500 m²","التعويض في العلاقة","الناتج $3.00\\times10^{3}\\ \\text{N/m}^2$"]'::jsonb, '["$A = 1500 \\div 10^{4} = 0.1500\\ \\text{m}^2$","$P = \\frac{450}{0.1500}$","$P = 3.00\\times10^{3}\\ \\text{N/m}^2$"]'::jsonb, '[{"element":"تحويل الوحدة","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج بالوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحويل صحيح وناتج صحيح بالوحدة"},{"level":"2 درجتان","description":"خطأ في التحويل مع تعويض وحساب صحيحين"},{"level":"1 درجة","description":"علاقة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل cm² إلى m² فيكون الناتج 0.300","القسمة على 100 بدل $10^{4}$ عند تحويل المساحة","ضرب الوزن في المساحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.766Z"}'::jsonb)
