('mcq', 2, 'أعد كتابة المعادلة $v_f = at$ لإيجاد الزمن $t$.', null, null, '["$t = v_f\\,a$","$t = \\frac{a}{v_f}$","$t = v_f - a$","$t = \\frac{v_f}{a}$"]'::jsonb, 'تطبيق', 'إعادة كتابة معادلة', 'سهل', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية'),
('mcq', 3, 'تُحسب القوة المؤثرة في شحنة تتحرك في مجال مغناطيسي بالعلاقة $F = Bqv$. أيّ مما يأتي يعطي $v$ بدلالة $F$ و$B$ و$q$؟', null, null, '["$v = \\frac{F}{Bq}$","$v = FBq$","$v = \\frac{Bq}{F}$","$v = \\frac{FB}{q}$"]'::jsonb, 'تطبيق', 'إعادة كتابة معادلة', 'متوسط', 'الكتاب ص 15 — مراجعة 1-1'),
('mcq', 4, 'تُعرَّف الكثافة بالعلاقة $D = \frac{m}{V}$. أيّ الصيغ الآتية تعطي الحجم $V$؟', null, null, '["$V = mD$","$V = \\frac{D}{m}$","$V = m - D$","$V = \\frac{m}{D}$"]'::jsonb, 'تطبيق', 'إعادة كتابة معادلة', 'سهل', 'الكتاب ص 29 — اختبار مقنن'),
('mcq', 5, 'في العلاقة $F = \frac{mv^2}{r}$، أيّ مما يأتي يعطي $v$ بدلالة $F$ و$m$ و$r$؟', null, null, '["$v = \\frac{Fr}{m}$","$v = \\sqrt{\\frac{Fr}{m}}$","$v = \\sqrt{\\frac{F}{mr}}$","$v = \\sqrt{\\frac{m}{Fr}}$"]'::jsonb, 'تحليل', 'إعادة كتابة معادلة تربيعية', 'صعب', 'الكتاب ص 26 — تقويم الفصل'),
('mcq', 6, 'أيّ مما يأتي يعطي التسارع $a$ من العلاقة $d = v_i t + \frac{1}{2}at^2$؟', null, null, '["$a = \\frac{d - v_i t}{2t^2}$","$a = \\frac{2d - v_i t}{t^2}$","$a = \\frac{2(d - v_i t)}{t^2}$","$a = \\frac{2(d + v_i t)}{t^2}$"]'::jsonb, 'تطبيق', 'إعادة كتابة معادلة متعددة الحدود', 'صعب', 'الكتاب ص 9 — الرياضيات والفيزياء'),
('mcq', 7, 'عند إعادة كتابة المعادلة $V = IR$ لإيجاد $I$، ما العملية التي تُجرى على طرفي المعادلة؟', null, null, '["قسمة الطرفين على $R$","ضرب الطرفين في $R$","طرح $R$ من الطرفين","قسمة الطرفين على $V$"]'::jsonb, 'فهم', 'خطوات فصل المتغير', 'متوسط', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية'),
('essay', 1, 'أعد كتابة المعادلة $P = \frac{F}{A}$ لإيجاد القوة $F$، ثم احسب القوة إذا كان $P = 2.50\times10^{4}\ \text{N/m}^2$ و$A = 0.0300\ \text{m}^2$.', null, null, null, 'تطبيق', 'إعادة كتابة وحساب', 'متوسط', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية'),
('essay', 2, 'أردت حساب التسارع بوحدة m/s²، والقوة مقيسة بوحدة N والكتلة بوحدة g، حيث $1\ \text{N} = 1\ \text{kg}\cdot\text{m/s}^2$. (أ) أعد كتابة المعادلة $\boldsymbol{F} = m\boldsymbol{a}$ لإيجاد $a$. (ب) ما معامل التحويل اللازم لتحويل g إلى kg؟ (ج) احسب تسارع جسم كتلته 450 g تؤثر فيه قوة محصلة مقدارها 3.6 N.', null, null, null, 'تطبيق', 'إعادة كتابة مع تحويل وحدات', 'متوسط', 'الكتاب ص 29 — اختبار مقنن'),
('essay', 3, 'تُعطى السرعة النهائية لجسم يتحرك بتسارع ثابت بالعلاقة $v_f = v_i + at$. (أ) أعد كتابتها لإيجاد $a$. (ب) أعد كتابتها لإيجاد $t$. (ج) احسب الزمن اللازم لتتغير سرعة جسم من 4.0 m/s إلى 16.0 m/s بتسارع ثابت مقداره 3.0 m/s².', null, null, null, 'تحليل', 'إعادة كتابة معادلة متعددة الحدود', 'صعب', 'الكتاب ص 11 — مثال 1 ومسائل تدريبية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
