('mcq', 1, 2, 'بقسمة طرفي المعادلة $V = IR$ على $I$ نحصل على $R = \frac{V}{I}$.', '["ضرب $V$ في $I$ بدل القسمة عليها.","قلب الكسر؛ القسمة على $I$ تجعل $V$ في البسط.","","طرح $I$ من الطرفين، والمعادلة فيها ضرب لا جمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-17T19:43:12.766Z"}'::jsonb),
