('mcq', 3, 0, 'بقسمة طرفي المعادلة على $Bq$ نحصل على $v = \frac{F}{Bq}$.', '["","ضرب $F$ في $Bq$ بدل القسمة عليهما.","قلب الكسر؛ $F$ يجب أن يبقى في البسط.","القسمة على $q$ فقط وضرب $B$ بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.767Z"}'::jsonb),
('mcq', 4, 3, 'بضرب الطرفين في $V$ نحصل على $DV = m$، ثم بقسمتهما على $D$ نحصل على $V = \frac{m}{D}$.', '["ضرب $m$ في $D$ بدل القسمة عليها.","قلب الكسر؛ $m$ يبقى في البسط.","طرح $D$ من $m$، والعلاقة قسمة لا جمع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-17T19:43:12.767Z"}'::jsonb),
('mcq', 5, 1, 'بضرب الطرفين في $r$: $Fr = mv^2$، وبالقسمة على $m$: $v^2 = \frac{Fr}{m}$، ثم بأخذ الجذر التربيعي: $v = \sqrt{\frac{Fr}{m}}$.', '["نسيان أخذ الجذر التربيعي؛ هذه قيمة $v^2$ لا $v$.","","القسمة على $r$ بدل الضرب فيه؛ $r$ في المقام في الطرف الأيمن فينتقل إلى البسط.","قلب الكسر كله بعد أخذ الجذر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-17T19:43:12.767Z"}'::jsonb),
('mcq', 6, 2, 'بطرح $v_i t$ من الطرفين: $d - v_i t = \frac{1}{2}at^2$، وبالضرب في 2 ثم القسمة على $t^2$: $a = \frac{2(d - v_i t)}{t^2}$.', '["القسمة على 2 بدل الضرب فيه للتخلص من $\\frac{1}{2}$.","ضرب $d$ وحده في 2 دون ضرب الحد $v_i t$.","","خطأ في الإشارة؛ $v_i t$ يُطرح من الطرفين لا يُجمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-17T19:43:12.767Z"}'::jsonb),
