('essay', 3, null::int, null, null, '(أ) $a = \frac{v_f - v_i}{t}$. (ب) $t = \frac{v_f - v_i}{a}$. (ج) $t = \frac{16.0\ \text{m/s} - 4.0\ \text{m/s}}{3.0\ \text{m/s}^2} = 4.0\ \text{s}$.', '["$a = \\frac{v_f - v_i}{t}$","$t = \\frac{v_f - v_i}{a}$","$t = 4.0\\ \\text{s}$"]'::jsonb, '["طرح $v_i$ من الطرفين: $v_f - v_i = at$","القسمة على $t$ أو على $a$","$t = \\frac{12.0}{3.0} = 4.0\\ \\text{s}$"]'::jsonb, '[{"element":"إيجاد $a$","marks":1},{"element":"إيجاد $t$","marks":1},{"element":"الحساب والوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"2 درجتان","description":"جزآن صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة $t = \\frac{v_f}{a} - v_i$","القسمة على $a$ قبل طرح $v_i$","التعويض بـ 16.0 بدل الفرق 12.0 فيكون الناتج 5.3 s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.768Z"}'::jsonb)
