from (values
('mcq', 1, 'ما المقصود بالطريقة العلمية؟', null, null, '["أسلوب للإجابة عن تساؤلات علمية بهدف تفسير الظواهر الطبيعية","مجموعة من المعادلات الرياضية الثابتة التي لا تتغير","قائمة مرتبة بأسماء الأجهزة والأدوات المستخدمة في مختبر الفيزياء","تخمين علمي عن ارتباط المتغيرات بعضها ببعض"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 2, 'بمَ تبدأ الطريقة العلمية؟', null, null, '["كتابة الاستنتاج النهائي","طرح أسئلة بناءً على مشاهدات","صياغة قانون علمي","نشر النتائج في مجلة علمية متخصصة"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 3, 'ما الهدف الذي تسعى الطريقة العلمية إلى تحقيقه؟', null, null, '["جمع البيانات وتسجيلها في جداول فقط","تأكيد آراء العلماء القدماء","تفسير الظواهر الطبيعية المختلفة","تصميم أجهزة تقنية تجارية مربحة للشركات"]'::jsonb, 'فهم', 'تفسير هدف', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 4, 'لاحظ طالب أن الكرة المطاطية ترتد إلى ارتفاع أقل في كل مرة، فسأل: لماذا يقل ارتفاع ارتدادها؟ ثم بحث عن إجابة منطقية يمكن اختبارها. ماذا يمثل ما فعله الطالب؟', null, null, '["صياغة نظرية علمية","صياغة قانون علمي","اختبار الفرضية بالتجربة وتحليل النتائج","بداية اتباع الطريقة العلمية"]'::jsonb, 'فهم', 'تصنيف موقف', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 5, 'أيّ العبارات الآتية تصف الطريقة العلمية وصفًا صحيحًا؟', null, null, '["عملية تعتمد على التخمين وحده دون تجريب","عملية تنتهي دائمًا بإثبات صحة الفرضية الأولى التي وضعها العالم","عملية منظمة تجمع بين المشاهدة والتجريب والتحليل","عملية يقتصر استخدامها على علماء الفيزياء"]'::jsonb, 'فهم', 'تمييز وصف صحيح', 'صعب', 'الكتاب ص 25 — دليل مراجعة الفصل (المفاهيم الرئيسة)'),
('mcq', 6, 'اعتقد أرسطو أن سرعة سقوط الجسم تزداد بزيادة وزنه، ثم استقصى جاليليو ذلك للتأكد من صحته. ما الذي يجعل طريقة جاليليو طريقة علمية؟', null, null, '["أنه اختبر الفكرة بالتجربة والمشاهدة بدل قبولها لشهرة قائلها","أنه قبل الفكرة لأن قائلها فيلسوف مشهور له مكانة كبيرة","أنه رفض الفكرة مباشرة دون إجراء أي تجربة أو مشاهدة","أنه اعتمد على الحسابات الرياضية وحدها دون أي مشاهدة"]'::jsonb, 'تطبيق', 'تطبيق في موقف تاريخي', 'صعب', 'الكتاب ص 9 — التجربة الاستهلالية'),
('mcq', 7, 'أيّ الأسئلة الآتية يمكن الإجابة عنه باتباع الطريقة العلمية؟', null, null, '["أيّ العالِمَين أعظم شأنًا: نيوتن أم أينشتاين؟","هل يستحق اكتشاف الجاذبية أن يُعدّ أهم اكتشاف في التاريخ؟","هل ينبغي أن يُنفَق على أبحاث الفضاء أكثر من أبحاث الطب؟","هل تسقط قطعة نقد واحدة أبطأ من أربع قطع ملتصقة؟"]'::jsonb, 'تحليل', 'تمييز سؤال علمي', 'متوسط', 'الكتاب ص 9 — التجربة الاستهلالية'),
('essay', 1, 'ما المقصود بالطريقة العلمية؟ وبمَ تبدأ؟', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 12 — الطريقة العلمية'),
('essay', 2, 'صف كيف تُستخدم الطريقة العلمية للإجابة عن السؤال: «هل يؤثر وزن الجسم في سرعة سقوطه؟»، مبينًا: المشاهدة التي يُبنى عليها السؤال، والإجابة المنطقية المقترحة، وكيف يُتحقق منها.', null, null, null, 'تطبيق', 'تطبيق الطريقة العلمية', 'متوسط', 'الكتاب ص 9 — التجربة الاستهلالية'),
('essay', 3, 'قال طالب: «الطريقة العلمية خطوات ثابتة تُطبق مرة واحدة بالترتيب نفسه، وتنتهي دائمًا بإثبات صحة الفرضية». قوّم هذه العبارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 26 — تقويم الفصل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
