from (values
('mcq', 1, 0, 'تمثل الطريقة العلمية أسلوبًا للإجابة عن تساؤلات علمية بهدف تفسير الظواهر الطبيعية المختلفة.', '["","المعادلات أداة تستخدمها الفيزياء، وليست هي الطريقة العلمية.","أسماء الأجهزة لا تمثل أسلوبًا للإجابة عن التساؤلات العلمية.","هذا تعريف الفرضية، وهي جزء من الطريقة العلمية لا الطريقة كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-17T19:43:12.769Z"}'::jsonb),
('mcq', 2, 1, 'تبدأ الطريقة العلمية بطرح أسئلة بناءً على مشاهدات، ثم محاولة البحث عن إجابات منطقية لها عن طريق وضع الفرضيات.', '["الاستنتاج يأتي في نهاية الطريقة العلمية بعد التجريب والتحليل.","","القانون العلمي لا يُصاغ إلا بعد مشاهدات مترابطة متكررة، فلا يكون بداية.","نشر النتائج يكون بعد التوصل إليها، لا في البداية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.769Z"}'::jsonb),
('mcq', 3, 2, 'الطريقة العلمية أسلوب للإجابة عن تساؤلات علمية بهدف تفسير الظواهر الطبيعية المختلفة.', '["جمع البيانات وتسجيلها خطوة من خطوات الطريقة العلمية لا هدفها؛ فهدفها تفسير الظواهر.","الطريقة العلمية تختبر الآراء بالتجربة، وقد تنقضها لا أن تؤكدها بالضرورة.","","تصميم الأجهزة قد يكون تطبيقًا للعلم، لكنه ليس هدف الطريقة العلمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.769Z"}'::jsonb),
('mcq', 4, 3, 'الطالب بدأ بمشاهدة، ثم طرح سؤالًا بناءً عليها، ثم بحث عن إجابة منطقية (فرضية)، وهذه بداية الطريقة العلمية.', '["النظرية العلمية إطار يجمع عناصر البناء العلمي ومدعوم بنتائج تجريبية، والطالب لم يختبر شيئًا بعد.","القانون العلمي يجمع مشاهدات مترابطة لظاهرة متكررة، والطالب ما زال في مرحلة السؤال.","الطالب لم يُجرِ تجربة بعد؛ فقد طرح سؤالًا واقترح إجابة يمكن اختبارها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.769Z"}'::jsonb),
('mcq', 5, 2, 'الطريقة العلمية عملية منظمة للمشاهدة والتجريب والتحليل للإجابة عن الأسئلة حول العالم الطبيعي.', '["التخمين (الفرضية) خطوة واحدة فيها، ويجب اختباره بالتجريب.","قد تُعدَّل الفرضية إذا لم تؤيدها النتائج، فلا تنتهي دائمًا بإثباتها.","","الطريقة العلمية يستخدمها العلماء في مختلف فروع العلم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.769Z"}'::jsonb),
('mcq', 6, 0, 'الطريقة العلمية تقوم على اختبار الأفكار بالتجربة والمشاهدة وتحليل النتائج، لا على قبولها أو رفضها بلا دليل؛ وهذا ما فعله جاليليو حين استقصى رأي أرسطو.', '["","قبول الفكرة لشهرة قائلها ليس طريقة علمية؛ فالفكرة تُختبر بالتجربة.","رفض الفكرة دون تجربة حكم بلا دليل، وليس طريقة علمية.","الحسابات وحدها لا تكفي؛ فتوقعاتها تُقارن بنتائج التجربة والمشاهدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.770Z"}'::jsonb),
('mcq', 7, 3, 'سؤال سقوط قطع النقد يمكن اختباره بالتجربة والمشاهدة والقياس، فيُجاب عنه بالطريقة العلمية.', '["المفاضلة بين العلماء حكم تقديري شخصي لا يُختبر بالتجربة والقياس.","الحكم بأهمية اكتشاف ما حكم قيمي لا يُختبر بالتجربة والمشاهدة.","هذا سؤال عن قرار وأولويات يُجاب عنه بالموازنة بين القيم، لا بالتجربة والمشاهدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.770Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطريقة العلمية أسلوب للإجابة عن تساؤلات علمية بهدف تفسير الظواهر الطبيعية المختلفة، أي عملية منظمة للمشاهدة والتجريب والتحليل. وتبدأ بطرح أسئلة بناءً على مشاهدات، ثم البحث عن إجابات منطقية لها بوضع الفرضيات.', '["أسلوب للإجابة عن تساؤلات علمية","هدفه تفسير الظواهر الطبيعية","تبدأ بطرح أسئلة بناءً على مشاهدات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الهدف","marks":1},{"element":"البداية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل مع الهدف والبداية"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الطريقة العلمية والفرضية","القول إنها تبدأ بالتجربة","إغفال هدف تفسير الظواهر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-17T19:43:12.770Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المشاهدة: الأجسام المختلفة تسقط نحو الأرض عند إفلاتها. السؤال: هل يسقط الجسم الأثقل أسرع؟ الإجابة المنطقية المقترحة (فرضية): سرعة سقوط الجسم لا تعتمد على وزنه (أو تزداد بزيادته). التحقق: تصميم تجربة كإسقاط قطعة نقد واحدة وأربع قطع ملتصقة معًا في الوقت نفسه من الارتفاع نفسه، وملاحظة وصولهما، وتسجيل النتائج وتحليلها، وتكرار التجربة.', '["مشاهدة مناسبة","فرضية تربط الوزن بسرعة السقوط","تجربة مناسبة للتحقق مع تثبيت الارتفاع","تسجيل النتائج وتحليلها وتكرارها"]'::jsonb, '[]'::jsonb, '[{"element":"المشاهدة","marks":1},{"element":"الفرضية","marks":1},{"element":"التجربة","marks":1},{"element":"التسجيل والتحليل والتكرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف متكامل للمراحل الأربع"},{"level":"2–3 درجات","description":"وصف صحيح لمرحلتين أو ثلاث"},{"level":"1 درجة","description":"مرحلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تثبيت الارتفاع عند المقارنة","الاكتفاء بالرأي دون تجربة","إغفال تكرار التجربة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.770Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. فالطريقة العلمية عملية منظمة للمشاهدة والتجريب والتحليل، لكنها ليست خطًّا واحدًا ينتهي بإثبات الفرضية؛ فإذا لم تؤيد النتائج الفرضية تُعدَّل الفرضية ويُعاد اختبارها، والتجارب يجب أن تكون قابلة للتكرار ليعيدها باحثون آخرون. وقد تؤدي النتائج إلى رفض الفرضية أو تعديلها لا إلى إثباتها دائمًا.', '["الحكم بعدم صحة العبارة","الطريقة العلمية تتضمن تعديل الفرضية عند عدم تأييد النتائج","التجارب تُكرر","النتائج قد ترفض الفرضية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تعديل الفرضية","marks":1},{"element":"التكرار","marks":1},{"element":"الفرضية لا تُثبت دائمًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح بتعليل متكامل"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد العبارة","القول إن الفرضية المرفوضة تُهمل دون تعديل","إغفال قابلية التكرار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.770Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
