('mcq', 3, 'أيّ العبارات الآتية تمثل فرضية؟', null, null, '["طول النابض 12 cm عند تعليق حلقة واحدة","كلما زادت الكتلة المعلقة بالنابض زاد طوله","قِس طول النابض بالمسطرة بعد تعليق ثلاث حلقات معدنية به","النابض مصنوع من سلك فلزي لامع"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 4, 'ما الذي يميز الفرضية من المشاهدة؟', null, null, '["الفرضية تخمين يربط بين متغيرين ويحتاج إلى اختبار","الفرضية حقيقة مثبتة لا تحتاج إلى اختبار","الفرضية قياس عددي يُسجل في جدول البيانات","الفرضية وصف لما تراه العين مباشرة دون أيّ تخمين أو تفسير"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 5, 'صاغ طالب العبارة: «تزداد سرعة سقوط الجسم بزيادة وزنه». ما الوصف العلمي المناسب لهذه العبارة قبل اختبارها؟', null, null, '["قانون علمي ثابت","فرضية تحتاج إلى اختبار بالتجربة","نظرية علمية مدعومة بالتجارب","حقيقة علمية مثبتة"]'::jsonb, 'فهم', 'تصنيف عبارة', 'متوسط', 'الكتاب ص 9 — التجربة الاستهلالية'),
('mcq', 6, 'أيّ العبارات الآتية فرضية قابلة للاختبار وتربط بين متغيرين؟', null, null, '["أسقِط الكرة من ارتفاع 2 m في كل محاولة","تسقط الكرة لأنها تريد العودة إلى مكانها","سقطت الكرة على الأرض بعد إفلاتها","يزداد زمن سقوط الكرة كلما زاد الارتفاع الذي تسقط منه"]'::jsonb, 'تحليل', 'تمييز فرضية قابلة للاختبار', 'صعب', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 7, 'على أيّ شيء تُبنى الفرضية عادةً؟', null, null, '["على نتائج نهائية مثبتة لا تقبل التعديل","على آراء شخصية وتفضيلات لا ترتبط بالمشاهدة أو التجربة","على مشاهدات وأسئلة سابقة، فتقدّم إجابة منطقية محتملة","على حفظ القوانين دون طرح أسئلة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('essay', 1, 'عرّف الفرضية، ثم اكتب مثالًا لفرضية تربط بين متغيرين.', null, null, null, 'تذكر', 'تعريف مع مثال', 'سهل', 'الكتاب ص 12 — الطريقة العلمية'),
('essay', 2, 'ما الفرق بين الفرضية والمشاهدة؟ وضّح إجابتك بمثال من تجربة يُعلَّق فيها عدد من الحلقات المعدنية المتماثلة بنابض ويُقاس طوله.', null, null, null, 'فهم', 'مقارنة مع مثال', 'صعب', 'الكتاب ص 12 — الطريقة العلمية'),
('essay', 3, 'أسقط طالب ثلاث كرات متماثلة الحجم مختلفة الكتلة من الارتفاع نفسه، ولاحظ أن أزمنة سقوطها متقاربة جدًّا. (أ) اكتب فرضية مناسبة يمكن أن يختبرها في تجارب لاحقة. (ب) حدد المتغيرين اللذين تربط بينهما فرضيتك. (ج) لماذا تُعد عبارتك فرضية لا نتيجة مثبتة؟', null, null, null, 'إبداع', 'صياغة فرضية', 'صعب', 'الكتاب ص 12 — الطريقة العلمية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
