('mcq', 3, 1, 'العبارة تخمين يربط بين متغيرين (الكتلة المعلقة وطول النابض)، فهي فرضية يمكن اختبارها.', '["هذه نتيجة قياس (مشاهدة كمية)، لا تخمين عن ارتباط متغيرين.","","هذه خطوة إجرائية في التجربة، لا تخمين.","هذا وصف لمادة النابض، ولا يربط بين متغيرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.771Z"}'::jsonb),
('mcq', 4, 0, 'المشاهدة وصف لما يُرى أو يُقاس، أما الفرضية فتخمين علمي عن كيفية ارتباط المتغيرات، يُختبر بالتجارب.', '["","الفرضية تخمين يُختبر، وليست حقيقة مثبتة.","القياس العددي نتيجة مشاهدة، لا فرضية.","وصف ما تراه العين مشاهدة، لا فرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.772Z"}'::jsonb),
('mcq', 5, 1, 'العبارة تخمين عن ارتباط متغيرين (الوزن وسرعة السقوط) لم يُختبر بعد، فهي فرضية.', '["القانون العلمي يجمع مشاهدات مترابطة مؤكدة لظاهرة متكررة، والعبارة لم تُختبر بعد.","","النظرية مدعومة بنتائج تجريبية، والعبارة لم تُختبر.","العبارة لم تُختبر، فلا توصف بأنها حقيقة مثبتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb),
('mcq', 6, 3, 'العبارة تربط بين متغيرين قابلين للقياس (الارتفاع وزمن السقوط)، ويمكن اختبارها بالتجربة.', '["هذه تعليمات إجرائية في التجربة، لا تخمين عن ارتباط متغيرين.","رغبة الكرة أمر لا يمكن قياسه أو اختباره، فليست فرضية علمية.","هذه مشاهدة لحدث واحد، لا تخمين عن ارتباط متغيرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb),
('mcq', 7, 2, 'تبدأ الطريقة العلمية بطرح أسئلة بناءً على مشاهدات، ثم البحث عن إجابات منطقية لها بوضع الفرضيات.', '["الفرضية تسبق الاختبار، وقد تُعدَّل؛ فليست مبنية على نتائج نهائية.","الفرضية تخمين علمي مبني على المشاهدة، لا رأي شخصي.","","الفرضية إجابة منطقية عن سؤال، لا حفظ للقوانين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفرضية تخمين علمي عن كيفية ارتباط المتغيرات بعضها مع بعض. مثال: «يزداد طول النابض كلما زادت الكتلة المعلقة به» (تُقبل أمثلة صحيحة أخرى تربط متغيرين قابلين للقياس).', '["التعريف","مثال يربط متغيرين قابلين للقياس"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"2 درجتان","description":"تعريف صحيح ومثال مناسب"},{"level":"1 درجة","description":"تعريف صحيح أو مثال مناسب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الفرضية بأنها حقيقة مثبتة","إعطاء مشاهدة بدل فرضية","مثال لا يربط بين متغيرين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (2 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المشاهدة وصف لما يُرى أو يُقاس مباشرة، مثل: «طول النابض 14 cm عند تعليق حلقتين». أما الفرضية فتخمين علمي عن كيفية ارتباط المتغيرات يُختبر بالتجربة، مثل: «يزداد طول النابض بزيادة عدد الحلقات المعلقة به».', '["المشاهدة وصف لما يُرى أو يُقاس","الفرضية تخمين عن ارتباط المتغيرات يُختبر","مثال صحيح للمشاهدة","مثال صحيح للفرضية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المشاهدة","marks":1},{"element":"تعريف الفرضية","marks":1},{"element":"مثال المشاهدة","marks":1},{"element":"مثال الفرضية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"فرق واضح مع مثالين صحيحين"},{"level":"2–3 درجات","description":"فرق صحيح مع مثال واحد أو أمثلة دون فرق واضح"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ نتيجة القياس فرضية","كتابة فرضية لا تتضمن متغيرين","الخلط بين الفرضية والاستنتاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) «لا يعتمد زمن سقوط الجسم على كتلته عند سقوطه من الارتفاع نفسه». (ب) المتغيران: كتلة الكرة وزمن سقوطها. (ج) لأنها تخمين علمي عن ارتباط المتغيرين مبني على مشاهدة محدودة، ويحتاج إلى اختبار بتجارب متكررة قبل قبوله.', '["فرضية صحيحة الصياغة تربط متغيرين","تحديد المتغيرين","تعليل كونها فرضية: تخمين يحتاج إلى اختبار"]'::jsonb, '[]'::jsonb, '[{"element":"صياغة الفرضية","marks":2},{"element":"تحديد المتغيرين","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"فرضية سليمة ومتغيران صحيحان وتعليل صحيح"},{"level":"2–3 درجات","description":"فرضية سليمة مع نقص في المتغيرين أو التعليل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة المشاهدة نفسها بدل فرضية","عدّ الحجم متغيرًا مع أنه ثابت في التجربة","القول إن مشاهدة واحدة تكفي لإثبات الفرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.773Z"}'::jsonb)
