select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الخط البياني مستقيم يمر بنقطة الأصل، وتتضاعف الكتلة عند مضاعفة الحجم (من 30 g عند 10 cm³ إلى 60 g عند 20 cm³)، فالعلاقة خطية طردية.', '["في العلاقة العكسية تتناقص إحدى الكميتين عند زيادة الأخرى، والكتلة هنا تزداد بزيادة الحجم.","التمثيل البياني للعلاقة التربيعية منحنى (قطع مكافئ)، والخط هنا مستقيم.","","تغير الكتلة بانتظام مع الحجم يدل على وجود علاقة واضحة بينهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.774Z"}'::jsonb),
('mcq', 2, 0, 'يتناقص الزمن عند زيادة السرعة، وحاصل ضربهما ثابت: $10\times12 = 20\times6 = 30\times4 = 120$، والمنحنى قطع زائد؛ فالعلاقة عكسية.', '["","في العلاقة الطردية تزداد الكميتان معًا، والزمن هنا يتناقص بزيادة السرعة.","منحنى العلاقة التربيعية قطع مكافئ، وحاصل ضرب الكميتين هنا ثابت وهو ما يميز العلاقة العكسية.","الخط البياني هنا منحنٍ لا مستقيم، فليست علاقة خطية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-17T19:43:12.774Z"}'::jsonb),
('mcq', 3, 1, 'عند مضاعفة الزمن من 1 s إلى 2 s يزداد الموقع من 2 m إلى 8 m (أربعة أمثال)، وعند 4 s يصبح 32 m (16 مثلًا)؛ فالموقع يتناسب مع $t^2$، والمنحنى قطع مكافئ.', '["لو كانت العلاقة خطية لكان الخط مستقيمًا ولتضاعف الموقع عند مضاعفة الزمن، لكنه يصبح أربعة أمثاله.","","في العلاقة العكسية يتناقص أحد المتغيرين بزيادة الآخر، والموقع هنا يزداد.","الموقع يتغير من 0 إلى 32 m، فليس ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-17T19:43:12.774Z"}'::jsonb),
('mcq', 4, 3, 'الخط مستقيم نازل لا يمر بنقطة الأصل، فالعلاقة خطية ميلها سالب ($y = -\frac{1}{2}x + 3$). ولا تكون عكسية؛ لأن حاصل الضرب عند (0، 3) يساوي 0، وعند (2، 2) يساوي 4، فهو غير ثابت، كما أن منحنى العلاقة العكسية قطع زائد لا يقطع المحورين.', '["تناقص $y$ بزيادة $x$ لا يكفي للحكم بأن العلاقة عكسية؛ فالعكسية يكون فيها حاصل الضرب ثابتًا والمنحنى قطعًا زائدًا.","العلاقة الطردية يمر خطها بنقطة الأصل ويزداد فيها $y$ بزيادة $x$، والخط هنا نازل.","التمثيل البياني للعلاقة التربيعية قطع مكافئ لا خط مستقيم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.774Z"}'::jsonb),
('mcq', 5, 3, '$r$ في مقام الكسر، وعند ثبات $m$ و$v$ يكون $Fr = mv^2$ ثابتًا؛ فإذا زاد $r$ قلّت $F$، والعلاقة عكسية.', '["العلاقة الطردية تكون عندما تظهر الكمية في البسط مرفوعة للأس 1، و$r$ هنا في المقام.","العلاقة التربيعية بين $F$ و$v$ لا بين $F$ و$r$.","$r$ موجود في المعادلة، فتغيره يغير $F$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-17T19:43:12.775Z"}'::jsonb),
('mcq', 6, 1, '$F$ تتناسب مع $v^2$؛ فعند مضاعفة $v$ تصبح $F$ مضروبة في $2^2 = 4$.', '["عدّ العلاقة خطية طردية ونسيان تربيع $v$.","","عدّ العلاقة عكسية، و$v$ في البسط لا في المقام.","عدّ العلاقة عكسية تربيعية، و$v^2$ في البسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.775Z"}'::jsonb),
('mcq', 7, 0, 'حاصل ضرب $x$ و$y$ ثابت في كل الأزواج: $1\times20 = 2\times10 = 4\times5 = 5\times4 = 20$، أي $y = \frac{20}{x}$؛ فالعلاقة عكسية.', '["","تتناقص $y$ بزيادة $x$، وفي العلاقة الطردية تزدادان معًا.","في العلاقة التربيعية تتغير $y$ مع $x^2$، وهنا حاصل الضرب ثابت.","لو كانت العلاقة خطية لكان الميل بين أيّ نقطتين ثابتًا، لكن الميل بين النقاط المتتالية يساوي $-10$ ثم $-2.5$ ثم $-1$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.775Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) علاقة عكسية؛ لأن $\lambda f = v$ ثابت، و$f$ في مقام الكسر. (ب) عند مضاعفة $f$ يصبح الطول الموجي نصف قيمته.', '["العلاقة عكسية مع التعليل","يصبح $\\lambda$ نصف قيمته"]'::jsonb, '[]'::jsonb, '[{"element":"نوع العلاقة وتعليله","marks":1},{"element":"أثر مضاعفة التردد","marks":1}]'::jsonb, '[{"level":"2 درجتان","description":"الجزآن صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العلاقة طردية لأن $\\lambda$ و$f$ في المعادلة نفسها","القول إن $\\lambda$ تتضاعف","القول إن $\\lambda$ تصبح ربع قيمتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (2 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-17T19:43:12.775Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العلاقة بين $x$ و$A$ خطية طردية: النسبة $\frac{A}{x} = 6$ ثابتة في كل الأزواج ($\frac{6}{1} = \frac{12}{2} = \frac{36}{6} = 6$)، أي $A = 6x$، وخطها البياني مستقيم يمر بنقطة الأصل. والعلاقة بين $x$ و$B$ عكسية: حاصل الضرب $xB = 12$ ثابت ($1\times12 = 2\times6 = 3\times4 = 6\times2 = 12$)، أي $B = \frac{12}{x}$.', '["العلاقة بين $x$ و$A$ طردية","التعليل: $\\frac{A}{x}$ ثابت","العلاقة بين $x$ و$B$ عكسية","التعليل: $xB$ ثابت"]'::jsonb, '["حساب $\\frac{A}{x}$ لكل زوج: 6","حساب $xB$ لكل زوج: 12"]'::jsonb, '[{"element":"نوع العلاقة مع $A$","marks":1},{"element":"تعليلها بالحساب","marks":1},{"element":"نوع العلاقة مع $B$","marks":1},{"element":"تعليلها بالحساب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد العلاقتين ويعللهما بالحساب"},{"level":"2–3 درجات","description":"يحدد العلاقتين دون تعليل كافٍ أو يحدد واحدة مع تعليلها"},{"level":"1 درجة","description":"يحدد علاقة واحدة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على العلاقة مع $B$ بأنها عكسية لمجرد تناقصها دون التحقق من ثبات حاصل الضرب","حساب الفروق بدل النسب","الخلط بين العلاقتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.775Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $F$ و$r$: عكسية؛ $Fr$ ثابت، والتمثيل البياني قطع زائد يتناقص فيه $F$ بزيادة $r$. (ب) $F$ و$m$: خطية طردية؛ $F$ تساوي ثابتًا مضروبًا في $m$، والتمثيل خط مستقيم يمر بنقطة الأصل. (ج) $F$ و$v$: تربيعية؛ $F$ تتناسب مع $v^2$، والتمثيل منحنى (قطع مكافئ) يزداد انحداره بزيادة $v$.', '["(أ) عكسية — قطع زائد","(ب) طردية خطية — مستقيم يمر بالأصل","(ج) تربيعية — قطع مكافئ"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) النوع والشكل","marks":2},{"element":"(ب) النوع والشكل","marks":2},{"element":"(ج) النوع والشكل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة مع الشكل البياني"},{"level":"3–5 درجات","description":"تحديد صحيح لبعض العلاقات أو دون وصف الشكل"},{"level":"1–2 درجة","description":"علاقة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العلاقة بين $F$ و$v$ طردية خطية","عدّ العلاقة بين $F$ و$r$ طردية","وصف العلاقة العكسية بخط مستقيم نازل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-17T19:43:12.776Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
