select (select id from public.objectives where code = 'P1-C1-L1-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تجربة عملية، غيّر طالب درجة حرارة الغاز داخل بالون، وقاس حجم الغاز عند كل درجة حرارة. ما المتغير المستقل في هذه التجربة؟', null, null, '["حجم الغاز داخل البالون","درجة حرارة الغاز","كتلة البالون","نوع الغاز المستخدم في البالون"]'::jsonb, 'تطبيق', 'تحديد متغير', 'سهل', 'الكتاب ص 26 — تقويم الفصل (السؤال 25)'),
('mcq', 2, 'علّق طالب حلقات معدنية متماثلة بنابض واحدة بعد الأخرى، وقاس طول النابض في كل مرة. ما المتغير التابع في هذه التجربة؟', null, null, '["عدد الحلقات المعلقة","نوع فلز الحلقات","مكان تثبيت النابض","طول النابض"]'::jsonb, 'تطبيق', 'تحديد متغير', 'سهل', 'الكتاب ص 12 — تجربة قياس التغير'),
('mcq', 3, 'ما المقصود بالمتغير المستقل في التجربة؟', null, null, '["العامل الذي يعتمد على غيره ويتغير تبعًا له","العامل الذي يبقى ثابتًا ولا يتغير طوال مدة إجراء التجربة","العامل الذي يغيّره المجرب أو يعدّله في أثناء التجربة","النتيجة النهائية التي تُكتب في الاستنتاج"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 196 — دليل الرياضيات (المتغير المستقل والتابع)'),
('mcq', 4, 'مثّل طالب نتائج تجربته كما في الرسم البياني الآتي، وفق القاعدة المتبعة في تمثيل المتغيرات على المحورين. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c1l1-o10-gas-volume.svg","alt":"رسم بياني لنتائج تجربة: المحور الأفقي «درجة الحرارة (°C)» من 0 إلى 100 بتدريج كل 20، والمحور الرأسي «حجم الغاز (cm³)» من 0 إلى 600 بتدريج كل 100. عليه النقاط (0، 400) و(20، 428) و(40، 456) و(60، 484) و(80، 512) و(100، 540) يمر بها خط مستقيم صاعد."}]'::jsonb, '["درجة الحرارة متغير مستقل، وحجم الغاز متغير تابع","حجم الغاز متغير مستقل، ودرجة الحرارة متغير تابع","درجة الحرارة وحجم الغاز كلاهما متغيران مستقلان","درجة الحرارة وحجم الغاز كلاهما متغيران تابعان"]'::jsonb, 'تطبيق', 'تحديد متغيرات من رسم', 'متوسط', 'الكتاب ص 196 — دليل الرياضيات (المتغير المستقل والتابع)'),
('mcq', 5, 'يُسقط طالب كرة من ارتفاعات مختلفة يختارها، ويقيس زمن سقوطها في كل مرة. ما المتغير التابع؟', null, null, '["الارتفاع الذي تسقط منه الكرة","كتلة الكرة المستخدمة","قطر الكرة المستخدمة","زمن سقوط الكرة"]'::jsonb, 'تطبيق', 'تحديد متغير', 'متوسط', 'الكتاب ص 26 — تقويم الفصل (السؤال 25)'),
('mcq', 6, 'أراد طالب دراسة أثر القوة المؤثرة في عربة في المسافة التي تقطعها خلال 5 s. أيّ الخطط الآتية تحدد المتغيرين تحديدًا صحيحًا؟', null, null, '["يغيّر المسافة ويقيس القوة، مع تثبيت كتلة العربة","يغيّر القوة والكتلة معًا ويقيس المسافة","يغيّر القوة ويقيس المسافة، مع تثبيت كتلة العربة","يثبّت القوة ويقيس المسافة لعربات مختلفة الكتل"]'::jsonb, 'تحليل', 'تخطيط تجربة', 'صعب', 'الكتاب ص 27 — تقويم الفصل (السؤال 39)'),
('mcq', 7, 'يدرس طالب كيف تؤثر زاوية ميل لوح في سرعة كرة عند أسفله؛ فيغيّر زاوية الميل في كل محاولة ويقيس سرعة الكرة، مستخدمًا الكرة نفسها في كل مرة. أيّ مما يأتي يحدد المتغير المستقل والمتغير التابع في هذه التجربة تحديدًا صحيحًا؟', null, null, '["المستقل: سرعة الكرة، والتابع: زاوية الميل","المستقل: زاوية الميل، والتابع: سرعة الكرة","المستقل: كتلة الكرة، والتابع: سرعة الكرة","المستقل: زاوية الميل، والتابع: كتلة الكرة"]'::jsonb, 'تطبيق', 'تمييز المتغيرات والثوابت', 'صعب', 'الكتاب ص 23 — مختبر الفيزياء (المتغيرات المستقلة والتابعة)'),
('essay', 1, 'حدد المتغير المستقل والمتغير التابع في كل من التجربتين الآتيتين: (أ) يغيّر طالب طول خيط بندول، ويقيس زمن عشر اهتزازات له في كل مرة. (ب) يغيّر طالب فرق جهد البطارية في دائرة كهربائية، ويقيس شدة التيار المار في المصباح.', null, null, null, 'تطبيق', 'تحديد متغيرات', 'متوسط', 'الكتاب ص 26 — تقويم الفصل (السؤال 25)'),
('essay', 2, 'خطط لتجربة تدرس أثر الكتلة المعلقة بنابض في طوله: حدد المتغير المستقل، والمتغير التابع، واثنين من الثوابت، والمحور الذي تمثل عليه كلًّا من المتغيرين عند رسم النتائج بيانيًّا.', null, null, null, 'تطبيق', 'تخطيط تجربة', 'متوسط', 'الكتاب ص 12 — تجربة قياس التغير'),
('essay', 3, 'في تجربة لقياس حجم الغاز داخل بالون عند درجات حرارة مختلفة، قال طالب: «الحجم هو المتغير المستقل؛ لأنه الكمية التي نقيسها». قوّم قوله، وصحّحه إن لزم.', null, null, null, 'تقويم', 'تقويم قول', 'صعب', 'الكتاب ص 26 — تقويم الفصل (السؤال 25)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
