from (values
('mcq', 1, 1, 'المتغير المستقل هو العامل الذي يغيّره المجرب أو يعدّله في أثناء التجربة، وهو هنا درجة الحرارة.', '["حجم الغاز هو المتغير التابع؛ لأنه يُقاس ويعتمد على درجة الحرارة.","","كتلة البالون لم يغيّرها الطالب، فهي ثابتة في التجربة.","نوع الغاز لم يتغير، فهو من الثوابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-17T19:43:12.776Z"}'::jsonb),
('mcq', 2, 3, 'المتغير التابع هو الذي يعتمد على المتغير المستقل ويُقاس، وهو هنا طول النابض الذي يتغير بتغير عدد الحلقات.', '["عدد الحلقات هو ما يغيّره الطالب، فهو المتغير المستقل.","الحلقات متماثلة، فنوع الفلز ثابت في التجربة.","مكان تثبيت النابض لا يتغير، فهو من الثوابت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.776Z"}'::jsonb),
('mcq', 3, 2, 'المتغير المستقل هو العامل الذي يُغيَّر أو يُعدَّل خلال التجربة، ويُمثل عادة على المحور الأفقي.', '["هذا وصف المتغير التابع.","العامل الثابت يسمى من الثوابت، لا متغيرًا مستقلًا.","","الاستنتاج خلاصة التجربة، لا متغير فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.777Z"}'::jsonb),
('mcq', 4, 0, 'يمثل المحور الأفقي عادة المتغير المستقل والمحور الرأسي المتغير التابع؛ فدرجة الحرارة (المحور الأفقي) هي ما غيّره الطالب، وحجم الغاز (المحور الرأسي) يتغير تبعًا لها.', '["","هذا عكس القاعدة؛ فالمتغير على المحور الأفقي هو المستقل.","في التجربة متغير واحد يُغيَّر وآخر يُقاس تبعًا له، فلا يكون كلاهما مستقلًا.","لا بد من متغير يغيّره المجرب، فلا يكون كلاهما تابعًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-17T19:43:12.777Z"}'::jsonb),
('mcq', 5, 3, 'الزمن هو ما يُقاس ويعتمد على الارتفاع الذي يختاره الطالب، فهو المتغير التابع.', '["الارتفاع يختاره الطالب ويغيّره، فهو المتغير المستقل.","الكرة نفسها في كل مرة، فكتلتها ثابتة.","الكرة نفسها في كل مرة، فقطرها ثابت ولا يتغير تبعًا للارتفاع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.777Z"}'::jsonb),
('mcq', 6, 2, 'المتغير المستقل هو القوة (يغيّرها الطالب)، والتابع هو المسافة (تُقاس)، ويجب تثبيت بقية العوامل كالكتلة حتى يُنسب تغير المسافة إلى القوة وحدها.', '["هذه الخطة تعكس المتغيرين؛ فالقوة هي العامل الذي يُراد دراسة أثره.","تغيير عاملين معًا يمنع معرفة أيهما سبب تغير المسافة.","","هذه الخطة تدرس أثر الكتلة لا أثر القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-17T19:43:12.778Z"}'::jsonb),
('mcq', 7, 1, 'المتغير المستقل هو ما يغيّره الطالب (زاوية الميل)، والمتغير التابع هو ما يُقاس ويعتمد عليه (سرعة الكرة)؛ أما كتلة الكرة فلا تتغير لأنه استخدم الكرة نفسها.', '["هذا عكس المتغيرين؛ فالزاوية هي ما يغيّره الطالب، والسرعة هي ما يقيسه.","","كتلة الكرة لم تتغير لأن الطالب استخدم الكرة نفسها، فلا تكون المتغير المستقل.","الكتلة لم تُقس ولم تتغير؛ فالمتغير التابع هو السرعة التي تُقاس وتعتمد على الزاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.778Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المستقل: طول خيط البندول، والتابع: زمن عشر اهتزازات. (ب) المستقل: فرق الجهد، والتابع: شدة التيار.', '["(أ) المستقل طول الخيط","(أ) التابع زمن الاهتزازات","(ب) المستقل فرق الجهد","(ب) التابع شدة التيار"]'::jsonb, '[]'::jsonb, '[{"element":"مستقل (أ)","marks":1},{"element":"تابع (أ)","marks":1},{"element":"مستقل (ب)","marks":1},{"element":"تابع (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للمتغيرات الأربعة"},{"level":"2–3 درجات","description":"تحديد صحيح لتجربة واحدة كاملة أو لمتغيرات متفرقة"},{"level":"1 درجة","description":"متغير واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ما يُقاس متغيرًا مستقلًا","عكس المتغيرين في إحدى التجربتين","عدّ المصباح متغيرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.778Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المتغير المستقل: الكتلة المعلقة (تُغيَّر بإضافة كتل مختلفة). المتغير التابع: طول النابض (يُقاس). الثوابت: النابض نفسه، وطريقة القياس ومكان تثبيت النابض (أو أداة القياس نفسها). عند الرسم: الكتلة على المحور الأفقي، والطول على المحور الرأسي.', '["المستقل: الكتلة المعلقة","التابع: طول النابض","ثابتان مناسبان","الكتلة على المحور الأفقي والطول على الرأسي"]'::jsonb, '[]'::jsonb, '[{"element":"المستقل","marks":1},{"element":"التابع","marks":1},{"element":"الثوابت","marks":1},{"element":"المحاور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطة كاملة صحيحة"},{"level":"2–3 درجات","description":"تحديد صحيح للمتغيرين مع نقص في الثوابت أو المحاور"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير النابض بين القياسات","تمثيل الطول على المحور الأفقي","عدّ الطول متغيرًا مستقلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.778Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قوله غير صحيح. فالمتغير المستقل هو العامل الذي يغيّره المجرب أو يعدّله، وهو هنا درجة الحرارة. أما الحجم فهو الكمية التي تُقاس وتعتمد على درجة الحرارة، فهو المتغير التابع. والصواب: درجة الحرارة متغير مستقل يُمثل على المحور الأفقي، والحجم متغير تابع يُمثل على المحور الرأسي.', '["الحكم بخطأ القول","المستقل هو ما يغيّره المجرب: درجة الحرارة","ما يُقاس ويعتمد على غيره هو التابع: الحجم","تمثيل كل منهما على المحور المناسب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تحديد المستقل وتعليله","marks":1},{"element":"تحديد التابع وتعليله","marks":1},{"element":"المحاور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تصحيح وتعليل كاملين"},{"level":"2–3 درجات","description":"حكم صحيح مع تصحيح ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد قول الطالب","الخلط بين ما يُقاس وما يُغيَّر","تمثيل الحجم على المحور الأفقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-17T19:43:12.779Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
