('essay', 2, 'ما المقصود بقابلية التجارب للتكرار؟ ولماذا تُعد شرطًا في التجارب العلمية؟', null, null, null, 'فهم', 'توضيح مفهوم', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية (اختبار صحة الفرضية)'),
('essay', 3, 'اقترح طالب الفرضية: «يزداد زمن الاهتزازة الكاملة للبندول بزيادة طول خيطه». صف خطوات اختبار صحة هذه الفرضية، مبينًا ما يغيّره وما يقيسه وما يثبّته، وكيف يسجل نتائجه ويحللها، ولماذا يكرر التجربة.', null, null, null, 'تطبيق', 'تطبيق خطوات الاختبار', 'صعب', 'الكتاب ص 12 — الطريقة العلمية (اختبار صحة الفرضية)')
