from (values
('mcq', 1, 0, 'لاختبار صحة الفرضية تُصمَّم التجارب العلمية وتُنفَّذ، ثم تُسجل النتائج وتُنظم، ثم تُحلل.', '["","الاستنتاج يأتي بعد التجريب وتحليل النتائج، لا قبلها.","الفرضية لا تصبح قانونًا قبل اختبارها، والقانون يجمع مشاهدات مترابطة متكررة.","الفرضية تخمين يُختبر أولًا، ولا تُنشر حقيقةً قبل اختبارها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.779Z"}'::jsonb),
('mcq', 2, 2, 'تُصمم التجارب وتُنفذ أولًا، ثم تُسجل النتائج وتُنظم، ثم تُحلل في محاولة لتفسيرها أو توقع إجابات جديدة.', '["لا يمكن تحليل نتائج قبل إجراء التجربة والحصول عليها.","لا توجد نتائج تُسجل قبل تصميم التجربة وتنفيذها.","","التحليل يكون للنتائج بعد تسجيلها وتنظيمها، لا قبل ذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('mcq', 3, 3, 'يجب أن تكون التجارب والنتائج قابلة للتكرار عند قيام باحثين آخرين بإعادة التجربة والحصول على النتائج نفسها، مما يؤكد موثوقيتها.', '["الغرض من التكرار الحصول على النتائج نفسها، لا نتائج مختلفة.","قابلية التكرار لا تحول الفرضية إلى قانون، ولا تغني عن التحليل.","التكرار لا يغني عن تسجيل النتائج وتنظيمها، بل يتطلب ذلك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('mcq', 4, 1, 'تُحلل النتائج في محاولة لتفسيرها أو توقع إجابات جديدة، ومن ثم الحكم على مدى تأييدها للفرضية.', '["زيادة القياسات تكون في أثناء التجريب، لا هدفًا للتحليل.","","اختيار الأدوات جزء من تصميم التجربة قبل تنفيذها.","تحديد المكان من تصميم التجربة لا من تحليل النتائج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('mcq', 5, 1, 'إذا لم تؤيد النتائج الفرضية تُعدَّل الفرضية ثم تُختبر من جديد بالتجربة.', '["إهمال النتائج يناقض الطريقة العلمية التي تقوم على الأدلة التجريبية.","","تغيير النتائج تزوير يُفقد التجربة قيمتها العلمية.","النتائج خالفت الفرضية، فلا يصح إعلانها قانونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('mcq', 6, 0, 'من شروط التجارب العلمية أن تكون قابلة للتكرار؛ فإذا لم يحصل باحثون آخرون على النتائج نفسها لم يُعتمد على النتيجة.', '["","الأسبقية لا تجعل النتيجة موثوقة؛ فالمعيار قابلية تكرارها.","تأييد النتيجة للفرضية لا يكفي إن لم تتكرر عند الآخرين.","النظرية تتطلب دعمًا قويًّا بنتائج تجريبية متكررة، والنتيجة هنا لم تتكرر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('mcq', 7, 2, 'اختبار الفرضية يتطلب تجربة يُغيَّر فيها المتغير المستقل (الكتلة) ويُقاس التابع (الطول)، ثم تسجيل النتائج وتنظيمها وتحليلها.', '["قياس واحد دون تغيير الكتلة لا يبين كيف يرتبط الطول بالكتلة.","آراء الزملاء ليست نتائج تجربة، والفرضية تُختبر بالتجريب.","","تغيير النابض ولونه لا علاقة له بالفرضية، والكتلة لم تتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لاختبار صحة الفرضية: (1) تُصمَّم التجارب العلمية وتُنفَّذ. (2) تُسجَّل النتائج وتُنظَّم. (3) تُحلَّل النتائج في محاولة لتفسيرها أو توقع إجابات جديدة. ويجب أن تكون التجارب والنتائج قابلة للتكرار.', '["تصميم التجارب وتنفيذها","تسجيل النتائج وتنظيمها","تحليل النتائج لتفسيرها أو التوقع","قابلية التكرار"]'::jsonb, '[]'::jsonb, '[{"element":"التصميم والتنفيذ","marks":1},{"element":"التسجيل والتنظيم","marks":1},{"element":"التحليل","marks":1},{"element":"قابلية التكرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث بالترتيب مع شرط التكرار"},{"level":"2–3 درجات","description":"خطوتان أو ثلاث صحيحة"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["البدء بالتحليل قبل التجربة","إغفال شرط قابلية التكرار","الخلط بين خطوات الاختبار ووضع الفرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.780Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قابلية التكرار أن يتمكن باحثون آخرون من إعادة التجربة بالخطوات نفسها والحصول على النتائج نفسها. وهي شرط لأنها تؤكد أن النتائج ليست مصادفة ولا ناتجة عن خطأ في تجربة واحدة، فيمكن الاعتماد عليها في الحكم على الفرضية.', '["تعريف قابلية التكرار","سبب اشتراطها: التأكد من موثوقية النتائج"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"2 درجتان","description":"تعريف وتعليل صحيحان"},{"level":"1 درجة","description":"أحدهما صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التكرار وزيادة عدد القياسات في التجربة نفسها فقط","القول إن التكرار يجعل الفرضية قانونًا","إغفال دور الباحثين الآخرين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (2 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-17T19:43:12.781Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) يصمم التجربة وينفذها: يغيّر طول الخيط (مثلًا 20 cm ثم 40 cm ثم 60 cm)، ويقيس لكل طول زمن عشر اهتزازات ثم يقسمه على 10، مع تثبيت كتلة الثقل وزاوية الإفلات. (2) يسجل الأطوال والأزمنة في جدول منظم. (3) يحلل النتائج، كأن يمثلها بيانيًّا؛ فإذا ازداد الزمن بزيادة الطول أيدت النتائج الفرضية، وإلا لم تؤيدها. (4) يكرر القياسات، ويجب أن تكون التجربة قابلة للتكرار بحيث يحصل باحثون آخرون على النتائج نفسها؛ للتأكد من أنها ليست مصادفة أو خطأ في تجربة واحدة.', '["تغيير طول الخيط وقياس زمن الاهتزازة","تثبيت كتلة الثقل وزاوية الإفلات","تسجيل النتائج وتنظيمها في جدول","تحليل النتائج والحكم على الفرضية","تكرار التجربة وقابليتها للتكرار"]'::jsonb, '[]'::jsonb, '[{"element":"التصميم: ما يُغيَّر وما يُقاس","marks":1},{"element":"الثوابت","marks":1},{"element":"التسجيل والتنظيم","marks":1},{"element":"التحليل والحكم","marks":1},{"element":"التكرار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل للخطوات مع الثوابت والتكرار"},{"level":"3–4 درجات","description":"وصف صحيح مع نقص عنصر أو عنصرين"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير طول الخيط وكتلة الثقل معًا","تحليل النتائج قبل تسجيلها وتنظيمها","إغفال تكرار التجربة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.781Z"}'::jsonb)
