('mcq', 4, 'صنع طالب مجسمًا من كرات وأسلاك يمثل ترتيب الذرات في جزيء. ما نوع هذا النموذج العلمي؟', null, null, '["نموذج حاسوبي","نموذج فكري","نموذج مادي","قانون علمي"]'::jsonb, 'تطبيق', 'تصنيف نموذج', 'متوسط', 'الكتاب ص 13 — النماذج والقوانين والنظريات'),
