('mcq', 2, 0, 'للنماذج العلمية أنواع متعددة منها: النماذج المادية، والحاسوبية، والفكرية.', '["","هذه أنواع العلاقات بين المتغيرات، لا أنواع النماذج.","هذه أوصاف المتغيرات في التجربة، لا أنواع النماذج.","هذه أوصاف للوحدات والقياس، لا أنواع النماذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('mcq', 3, 1, 'تسهّل النماذج العلمية دراسة الظواهر الطبيعية والعلمية وتفسيرها، وتساعد على تصور الأشياء التي تصعب رؤيتها أو تخيلها.', '["النماذج تعتمد على التجريب، ولا تغني عنه.","","النماذج قد تتغير وتُطوَّر عند ظهور مشاهدات جديدة.","النماذج أدوات علمية للدراسة والتفسير، لا للزينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('mcq', 4, 2, 'المجسم شيء محسوس مصنوع من مواد (كرات وأسلاك)، فهو نموذج مادي.', '["النموذج الحاسوبي يُبنى ببرنامج على الحاسوب، والمجسم هنا مصنوع يدويًّا من مواد.","النموذج الفكري تصور ذهني، والمجسم هنا شيء محسوس.","","القانون العلمي قاعدة تصف ظاهرة متكررة، لا مجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('mcq', 5, 0, 'البرنامج يحاكي الظاهرة باستخدام الحاسوب، فهو نموذج حاسوبي.', '["","النموذج المادي مجسم محسوس، والمحاكاة هنا على شاشة الحاسوب.","النظرية إطار يجمع عناصر البناء العلمي، والبرنامج أداة نمذجة.","الفرضية تخمين عن ارتباط المتغيرات، والبرنامج نموذج يحاكي الظاهرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('mcq', 6, 2, 'تساعد النماذج على تصور الأشياء التي تصعب رؤيتها أو تخيلها كالذرة، وتسهّل دراستها وتفسير المشاهدات المتعلقة بها.', '["الذرة موجودة، لكنها صغيرة جدًّا لا تُرى مباشرة.","النموذج تمثيل يساعد على التصور والتفسير، وقد تعاقبت نماذج مختلفة للذرة، فليس صورة مطابقة.","","النماذج تعتمد على التجريب، ودراسة الذرة تتطلب تجارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('mcq', 7, 3, 'قراءة مقياس الحرارة نتيجة قياس (مشاهدة)، وليست نمذجة لفكرة أو تركيب أو نظام؛ أما البقية فنماذج مادية أو رياضية أو حاسوبية.', '["المجسم نموذج مادي يمثل تركيب الأرض وشكلها.","المعادلة الرياضية نموذج يمثل الظاهرة ويتيح التوقع.","المحاكاة الحاسوبية نموذج حاسوبي للظاهرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النماذج العلمية نمذجة فكرة أو معادلة أو تركيب أو نظام لظاهرة نحاول تفسيرها، وتسهّل دراسة الظواهر وتفسيرها. ومن أنواعها: النماذج المادية، والحاسوبية، والفكرية.', '["التعريف","النماذج المادية","النماذج الحاسوبية","النماذج الفكرية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"النوع الأول","marks":1},{"element":"النوع الثاني","marks":1},{"element":"النوع الثالث","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وثلاثة أنواع"},{"level":"2–3 درجات","description":"تعريف مع نوع أو نوعين، أو الأنواع دون تعريف"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النموذج والفرضية","ذكر أنواع العلاقات (طردية/عكسية) بدل أنواع النماذج","تعريف النموذج بأنه صورة مطابقة للواقع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مادي: مجسم الكرة الأرضية، يساعد على تصور شكل الأرض ومواقع القارات. حاسوبي: برنامج يحاكي حركة الكواكب حول الشمس، يساعد على دراسة حركتها وتوقع مواقعها. فكري: تصور الذرة نواةً تدور حولها الإلكترونات، يساعد على تخيل تركيب لا يُرى بالعين. (تُقبل أمثلة صحيحة أخرى.)', '["مثال مادي مع فائدته","مثال حاسوبي مع فائدته","مثال فكري مع فائدته"]'::jsonb, '[]'::jsonb, '[{"element":"المثال المادي وفائدته","marks":1},{"element":"المثال الحاسوبي وفائدته","marks":1},{"element":"المثال الفكري وفائدته","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع بيان الفائدة"},{"level":"2 درجتان","description":"مثالان صحيحان"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء مثال لا يمثل ظاهرة (كقراءة جهاز)","الخلط بين النموذج الحاسوبي والمادي","الاكتفاء بالمثال دون الفائدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.782Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لأن الذرة صغيرة جدًّا يصعب رؤيتها، والنموذج يساعد على تصورها وتفسير المشاهدات المتعلقة بها. (ب) المجسم نموذج مادي، والتصور الذهني نموذج فكري. (ج) يعتمد النموذج على التجريب؛ فيُبنى لتفسير المشاهدات والقياسات، ويُقبل ما دامت البيانات التجريبية تؤكده.', '["الحاجة إلى النموذج: صعوبة رؤية الذرة","المجسم: نموذج مادي","التصور الذهني: نموذج فكري","النموذج يعتمد على التجريب والمشاهدات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) النموذج المادي","marks":1},{"element":"(ب) النموذج الفكري","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل صحيح للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"جزآن صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النموذج نسخة مطابقة للذرة","عدّ التصور الذهني نموذجًا حاسوبيًّا","القول إن النموذج يُقبل دون تجريب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.783Z"}'::jsonb)
