('mcq', 2, 3, 'التعريف الوارد هو تعريف القانون العلمي: قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة.', '["النظرية إطار يجمع عناصر البناء العلمي ويفسر المشاهدات، وليست قاعدة تصف ظاهرة متكررة.","الفرضية تخمين علمي عن ارتباط المتغيرات، ولم تُبنَ بعد على مشاهدات مترابطة مؤكدة.","الطريقة العلمية أسلوب للإجابة عن التساؤلات العلمية، وليست قاعدة تصف ظاهرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.783Z"}'::jsonb),
('mcq', 3, 0, 'ينص تعريف القانون العلمي على أنه يصف ظاهرة طبيعية متكررة؛ فهو يجمع مشاهدات مترابطة تتكرر.', '["","المشاهدة الواحدة لا تكفي لصياغة قانون؛ فالقانون يصف ظاهرة متكررة.","القانون قاعدة طبيعية تجمع مشاهدات فعلية، فلا يُبنى على ظاهرة لم تُشاهَد.","القانون يصف ظاهرة متكررة ثابتة النمط، ولو اختلفت النتيجة في كل مرة لما أمكن وصفها بقاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('mcq', 4, 2, 'العبارة قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة (تساوي زاويتي السقوط والانعكاس)؛ فهي قانون علمي (قانون الانعكاس).', '["الفرضية تخمين يسبق الاختبار، أما هذه العبارة فتجمع مشاهدات مترابطة مؤكدة لظاهرة متكررة.","النظرية تفسر سبب حدوث الظاهرة ضمن إطار يجمع عناصر البناء العلمي، والعبارة هنا تصف الظاهرة فقط.","","النموذج تمثيل لفكرة أو نظام لتسهيل التفسير والتخيل، وليس قاعدة تجمع مشاهدات متكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('mcq', 5, 1, 'القانون العلمي قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة.', '["القانون لا يجمع تخمينات غير مختبرة، بل مشاهدات مترابطة لظاهرة متكررة.","","القانون لا يقوم على الآراء، بل على مشاهدات طبيعية مترابطة.","تفسير الأسباب من شأن النظرية العلمية؛ أما القانون فيصف الظاهرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('mcq', 6, 2, 'يجمع القانون العلمي المشاهدات المترابطة لوصف ظاهرة طبيعية متكررة؛ فغرضه الوصف لا التفسير.', '["القانون لا يفسر سبب حدوث الظاهرة، وإنما يقدم وصفًا لها؛ والتفسير من شأن النظرية.","التخمين بعلاقة غير مختبرة هو الفرضية لا القانون.","","هذا من وظائف النماذج العلمية لا القانون العلمي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('mcq', 7, 0, 'القانون العلمي قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة؛ فهو مبني على المشاهدة لا على الرأي، وقول الطالب خاطئ.', '["","اتفاق العلماء ليس أساس القانون؛ فالقانون قاعدة طبيعية تجمع مشاهدات مترابطة.","الحكم بالخطأ صحيح لكن التعليل خاطئ؛ فالقانون يصف الظاهرة ولا يفسر سببها.","القانون مبني أصلًا على مشاهدات مترابطة متكررة، فلا يستغني عنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القانون العلمي قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة. (أ) يجمع مشاهدات مترابطة. (ب) الظاهرة طبيعية متكررة. (ج) الغرض وصف الظاهرة لا تفسير سببها.', '["تعريف القانون العلمي تعريفًا صحيحًا","يجمع مشاهدات مترابطة","يتناول ظاهرة طبيعية متكررة","غرضه الوصف"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"ما يجمعه القانون","marks":1},{"element":"صفة الظاهرة","marks":1},{"element":"الغرض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع تحديد العناصر الثلاثة"},{"level":"2–3 درجات","description":"تعريف صحيح مع إغفال عنصر أو عنصرين"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين تعريف القانون وتعريف النظرية","القول إن غرض القانون تفسير سبب الظاهرة","إغفال صفة التكرار في الظاهرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لا تصح تسميتها قانونًا علميًا؛ لأن القانون قاعدة طبيعية تجمع مشاهدات مترابطة لظاهرة متكررة، والطالب بنى عبارته على مشاهدة واحدة فقط. كما أن المشاهدات الأخرى لا تؤيدها؛ فعند إسقاط قطع نقد ملتصقة وقطعة نقد منفردة معًا تصل جميعها في الوقت نفسه تقريبًا رغم اختلاف أوزانها، فالعبارة لا تصف ظاهرة متكررة ثابتة. وأقصى ما يمكن عدّها به أنها تخمين (فرضية) يحتاج إلى اختبار.', '["الحكم: لا تُعد قانونًا","السبب الأول: مشاهدة واحدة لا مشاهدات مترابطة متكررة","السبب الثاني: مشاهدات أخرى لا تؤيدها (الأجسام المختلفة الوزن تسقط معًا تقريبًا)","يمكن عدّها فرضية تحتاج إلى اختبار"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"السبب الأول","marks":1},{"element":"السبب الثاني","marks":1},{"element":"تصنيف العبارة فرضية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع سببين صحيحين وتصنيف العبارة"},{"level":"2–3 درجات","description":"حكم صحيح مع سبب واحد أو دون تصنيف"},{"level":"1 درجة","description":"حكم صحيح دون تعليل مقبول"},{"level":"صفر","description":"حكم خاطئ أو لا إجابة"}]'::jsonb, '["قبول العبارة قانونًا لأن الطالب جرّبها بنفسه","إغفال اشتراط تكرار المشاهدات","الظن أن الوزن وحده يحدد سرعة السقوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-17T19:43:12.784Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تعريف القانون: قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة. (1) الظاهرة الطبيعية المتكررة: انعكاس الضوء عن السطوح العاكسة، وهي ظاهرة تتكرر في كل مرة يسقط فيها الضوء على سطح عاكس. (2) المشاهدات المترابطة: قياسات كثيرة لزاويتي السقوط والانعكاس وُجدتا فيها متساويتين دائمًا. (3) الوصف: العبارة تصف ما يحدث (تساوي الزاويتين) دون أن تفسر سبب حدوثه. لذا فهي قانون علمي (قانون الانعكاس).', '["ذكر التعريف","الظاهرة المتكررة: انعكاس الضوء","المشاهدات المترابطة: قياسات متكررة لتساوي الزاويتين","العبارة تصف ولا تفسر"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الظاهرة المتكررة","marks":1},{"element":"المشاهدات المترابطة","marks":1},{"element":"الوصف دون التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يطابق أجزاء التعريف الثلاثة مع العبارة مطابقة صحيحة بعد ذكر التعريف"},{"level":"2–3 درجات","description":"يطابق جزأين أو يغفل ذكر التعريف"},{"level":"1 درجة","description":"يذكر التعريف فقط دون مطابقة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العبارة نظرية لأنها تتعلق بالضوء","القول إن العبارة تفسر سبب انعكاس الضوء","إغفال التكرار في المشاهدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.785Z"}'::jsonb)
