('essay', 1, 'وضّح بأسلوبك المقصود بالنظرية العلمية، مبيّنًا ثلاثة عناصر أساسية في تعريفها.', null, null, null, 'فهم', 'توضيح مفهوم', 'متوسط', 'الكتاب ص 14، 25 — النظرية العلمية'),
('essay', 2, 'قال أحد الأشخاص: «نظرية الجاذبية الكونية مجرد نظرية، أي أنها تخمين لا دليل عليه». ناقش هذا القول في ضوء المقصود بالنظرية العلمية.', null, null, null, 'تقويم', 'مناقشة تصور خاطئ', 'صعب', 'الكتاب ص 14 — النظرية العلمية'),
('essay', 3, 'وصف جاليليو أن سرعة سقوط الأجسام تعتمد على زمن سقوطها لا على كتلتها، ثم أرجع نيوتن سبب سقوط الأجسام إلى قوة تجاذب بين الأرض وهذه الأجسام. أيّ العملين يعبّر عن المقصود بالنظرية العلمية تعبيرًا أوضح؟ وضّح إجابتك.', null, null, null, 'تحليل', 'تحليل مثالين', 'صعب', 'الكتاب ص 14 — النظرية العلمية (تطور نظرية سقوط الأجسام)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
