from (values
('mcq', 1, 2, 'النظرية العلمية إطار يجمع بين عناصر البناء العلمي في موضوع من موضوعات العلم، وهو قادر على تفسير المشاهدات والملاحظات المدعومة بنتائج تجريبية.', '["هذا تعريف القانون العلمي، وهو يصف الظاهرة ولا يفسرها.","هذا تعريف الفرضية، وهي تخمين لم تدعمه التجارب بعد.","","هذا وصف الطريقة العلمية لا النظرية العلمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.785Z"}'::jsonb),
('mcq', 2, 0, 'تتميز النظرية العلمية بأنها قادرة على تفسير المشاهدات والملاحظات المدعومة بنتائج تجريبية، بينما يقتصر القانون على وصف الظاهرة.', '["","هذا ما يقوم به القانون العلمي نفسه، فلا يميز النظرية.","هذا عمل الفرضية، والنظرية مدعومة بالتجارب لا تخمين قبلها.","جمع المشاهدات المترابطة لوصف ظاهرة متكررة هو أساس القانون العلمي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.785Z"}'::jsonb),
('mcq', 3, 3, 'النظرية العلمية إطار يجمع بين عناصر البناء العلمي (فرضيات وحقائق ومفاهيم وقوانين ونماذج) في موضوع من موضوعات العلم.', '["تجربة واحدة لا تكوّن إطارًا؛ فالنظرية تجمع عناصر البناء العلمي كافة في موضوع ما.","النظرية لا تجمع آراء متعارضة، بل تفسيرًا متسقًا مدعومًا بالتجارب.","جمع القياسات دون تفسير لا يكوّن نظرية؛ فالنظرية قادرة على التفسير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.785Z"}'::jsonb),
('mcq', 4, 1, 'التفسير يقدّم سبب الظاهرة (قوة التجاذب) ويدعمه التجريب بقوة؛ وهذا ما يميز النظرية العلمية.', '["القانون يصف الظاهرة دون أن يفسر سببها، وهنا قُدّم سبب السقوط (قوة التجاذب).","","الفرضية تخمين قبل الاختبار، وهذا التفسير مدعوم بقوة بنتائج التجارب.","النموذج المادي تمثيل مجسم لشيء أو نظام، وليس تفسيرًا لسبب حدوث ظاهرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.785Z"}'::jsonb),
('mcq', 5, 3, 'النظرية إطار لأنها تجمع عناصر البناء العلمي كافة في موضوع من موضوعات العلم: فرضيات وحقائق ومفاهيم وقوانين ونماذج.', '["المعادلة التي تصف علاقة بين متغيرات من سمات القانون، والنظرية أوسع منه.","التخمينات غير المختبرة فرضيات، والنظرية مدعومة بنتائج التجارب.","النظرية تخص موضوعًا من موضوعات العلم، ولا تجمع كل النظريات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb),
('mcq', 6, 1, 'النظرية العلمية تفسير مدعوم بنتائج التجارب، وهي أفضل تفسير ممكن لمبدأ عمل الأشياء.', '["الوصف دون تفسير من سمات القانون العلمي لا النظرية.","","التخمين الذي يحتاج إلى اختبار هو الفرضية.","المجسم الذي يحاكي الشيء نموذج مادي لا نظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb),
('mcq', 7, 2, 'التفسير يجمع عناصر البناء العلمي كافة في موضوع واحد ويفسر المشاهدات المدعومة بالتجارب؛ وهذا هو المقصود بالنظرية العلمية.', '["احتواؤه قوانين لا يجعله قانونًا؛ فهو إطار تفسيري أوسع يضم القوانين وغيرها.","النماذج أحد عناصره فقط، والإطار الجامع المفسر هو النظرية.","","وجود فرضيات ضمن الإطار لا يجعله فرضية؛ فهو مدعوم بنتائج تجارب كثيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظرية العلمية إطار يجمع بين عناصر البناء العلمي في موضوع من موضوعات العلم، وهو قادر على تفسير المشاهدات والملاحظات المدعومة بنتائج تجريبية. وعناصر التعريف: (1) أنها إطار جامع يضم الفرضيات والحقائق والمفاهيم والقوانين والنماذج. (2) أنها تخص موضوعًا من موضوعات العلم. (3) أنها تفسر المشاهدات (تبيّن سبب حدوثها) ولا تكتفي بوصفها. (4) أن هذه المشاهدات مدعومة بنتائج تجريبية.', '["تعريف النظرية بلغة صحيحة","إطار يجمع عناصر البناء العلمي","تفسّر المشاهدات","مدعومة بنتائج تجريبية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العنصر الأول","marks":1},{"element":"العنصر الثاني","marks":1},{"element":"العنصر الثالث","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع ثلاثة عناصر صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع عنصر أو عنصرين"},{"level":"1 درجة","description":"تعريف ناقص دون عناصر"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النظرية والقانون (الوصف بدل التفسير)","وصف النظرية بأنها رأي أو تخمين","إغفال الدعم التجريبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb),
('essay', 2, null::int, null, null, 'هذا القول خاطئ؛ لأنه يخلط بين المعنى اليومي لكلمة «نظرية» (رأي أو ظن) والمعنى العلمي. فالنظرية العلمية إطار يجمع عناصر البناء العلمي في موضوع ما، ويفسر المشاهدات والملاحظات المدعومة بنتائج تجريبية، ولا يطلق اسم نظرية إلا على التفسير الذي تدعمه بقوة نتائج التجارب. أما التخمين الذي لم يُختبر فهو الفرضية. ونظرية الجاذبية الكونية تفسر مشاهدات كثيرة (مثل سقوط الأجسام وانجذاب الكتل بعضها إلى بعض) تدعمها التجارب.', '["الحكم بأن القول خاطئ","المعنى العلمي للنظرية: إطار تفسيري مدعوم بالتجارب","التخمين غير المختبر يسمى فرضية لا نظرية","تطبيق ذلك على نظرية الجاذبية الكونية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المعنى العلمي للنظرية","marks":1},{"element":"التمييز عن الفرضية","marks":1},{"element":"التطبيق على المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع توضيح المعنى العلمي والتمييز عن الفرضية والتطبيق على المثال"},{"level":"2–3 درجات","description":"حكم صحيح مع توضيح ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد القول أو لا إجابة"}]'::jsonb, '["تأييد القول لأن كلمة نظرية تعني رأيًا","الظن أن النظرية تصبح قانونًا عند ثبوتها","إغفال الدعم التجريبي للنظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عمل نيوتن يعبّر عن المقصود بالنظرية تعبيرًا أوضح؛ لأن النظرية العلمية تفسر المشاهدات المدعومة بنتائج تجريبية، ونيوتن قدّم تفسيرًا لسبب السقوط (قوة التجاذب بين الأرض والأجسام) وربط به مشاهدات كثيرة، فهو إطار تفسيري. أما عبارة جاليليو فتصف كيف تتغير سرعة السقوط مع الزمن دون أن تبين سبب السقوط، فهي أقرب إلى الوصف الذي يقدمه القانون.', '["اختيار عمل نيوتن","النظرية تفسر سبب الظاهرة","نيوتن قدّم سببًا (قوة التجاذب)","عبارة جاليليو وصف دون تفسير"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار الصحيح","marks":1},{"element":"معيار التفسير في النظرية","marks":1},{"element":"تحليل عمل نيوتن","marks":1},{"element":"تحليل عبارة جاليليو","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار صحيح مع تحليل العملين في ضوء معيار التفسير"},{"level":"2–3 درجات","description":"اختيار صحيح مع تحليل أحد العملين"},{"level":"1 درجة","description":"اختيار صحيح دون تعليل"},{"level":"صفر","description":"اختيار خاطئ أو لا إجابة"}]'::jsonb, '["اختيار عبارة جاليليو لأنها أقدم أو أبسط","عدّ أي عبارة علمية نظرية","إغفال الفرق بين الوصف والتفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.786Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
