('mcq', 6, 'أيّ الأزواج الآتية يتكون من قانونين علميين؟', null, null, '["قانون الانعكاس ونظرية الجاذبية الكونية","نظرية الانفجار العظيم وقانون حفظ الشحنة","قانون حفظ الشحنة وقانون الانعكاس","نظرية الجاذبية الكونية ونظرية الانفجار العظيم"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 13، 14 — القوانين والنظريات'),
('mcq', 7, 'أيّ العبارات الآتية تمثّل قانونًا علميًا؟', null, null, '["تسقط الأجسام بسبب قوة تجاذب بينها وبين الأرض","ربما يعتمد زمن سقوط الجسم على لونه","تنجذب جميع الكتل في الكون إلى كتل أخرى","تبقى الشحنة الكهربائية ثابتة قبل تحولات المادة وبعدها"]'::jsonb, 'تحليل', 'تمييز مثال', 'صعب', 'الكتاب ص 14 — أمثلة على القانون العلمي'),
('essay', 1, 'اذكر مثالين على قوانين علمية، واكتب نص كل منهما.', null, null, null, 'تذكر', 'ذكر أمثلة', 'متوسط', 'الكتاب ص 14 — أمثلة على القانون العلمي'),
('essay', 2, 'طبّق القانونين العلميين المناسبين للإجابة عمّا يأتي، مسمّيًا القانون في كل حالة: (أ) سقط شعاع ضوئي على مرآة مستوية بزاوية سقوط $50^\circ$؛ ما زاوية انعكاسه؟ (ب) كانت الشحنة الكلية لساق وقطعة قماش صفرًا قبل دلك إحداهما بالأخرى، وبعد الدلك أصبحت شحنة الساق $+5$ وحدات شحنة؛ ما شحنة قطعة القماش؟', null, null, null, 'تطبيق', 'تطبيق أمثلة القوانين', 'صعب', 'الكتاب ص 14 — أمثلة على القانون العلمي'),
('essay', 3, 'وضّح لماذا يُعدّ كل من «حفظ الشحنة» و«الانعكاس» قانونًا علميًا لا نظرية علمية.', null, null, null, 'تحليل', 'تعليل التصنيف', 'صعب', 'الكتاب ص 14 — أمثلة على القانون العلمي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
