from (values
('mcq', 1, 0, 'قانون حفظ الشحنة قانون علمي يصف ثبات الشحنة الكهربائية في أثناء تحولات المادة.', '["","هذه نظرية علمية تفسر انجذاب الكتل، وليست قانونًا.","هذه نظرية علمية في نشأة الكون، وليست قانونًا.","هذه نماذج علمية تعاقبت لتفسير المشاهدات، وليست قانونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 2, 2, 'النص هو نص قانون حفظ الشحنة: الشحنة الكهربائية تبقى ثابتة قبل تحولات المادة وبعدها.', '["قانون الانعكاس يتعلق بتساوي زاويتي سقوط الضوء وانعكاسه، لا بالشحنة.","النص يتحدث عن ثبات الشحنة الكهربائية لا الكتلة.","","هذه نظرية عن انجذاب الكتل، ولا تتناول الشحنة الكهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 3, 1, 'ينص قانون الانعكاس على أن زاوية سقوط الشعاع الضوئي على السطح العاكس تساوي زاوية انعكاسه عن السطح نفسه.', '["القانون ينص على تساوي الزاويتين لا على أن إحداهما ضعف الأخرى.","","القانون ينص على تساوي الزاويتين، ومجموعهما لا يساوي $90^\\circ$ إلا إذا كانت كل منهما $45^\\circ$.","الزاويتان متساويتان دائمًا وفق القانون، فلا تكون إحداهما أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 4, 3, 'وفق قانون الانعكاس تتساوى زاويتا السقوط والانعكاس، فزاوية الانعكاس $35^\circ$.', '["هذه متممة زاوية السقوط ($90^\\circ - 35^\\circ$)؛ والقانون ينص على تساوي زاويتي السقوط والانعكاس.","هذا مجموع الزاويتين أو ضعف زاوية السقوط، والقانون ينص على التساوي.","هذا ناتج طرح زاوية السقوط من $180^\\circ$، ولا علاقة له بقانون الانعكاس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 5, 0, 'ينص قانون حفظ الشحنة على أن الشحنة الكهربائية تبقى ثابتة قبل التحول وبعده، فتبقى الشحنة الكلية $-2$ وحدة شحنة.', '["","التحول لا يلغي الشحنة؛ فالقانون ينص على بقاء الشحنة الكلية ثابتة.","تغيير إشارة الشحنة الكلية يعني تغيّر مقدارها، والقانون ينص على ثباتها.","مضاعفة الشحنة تعني أن الشحنة لم تُحفَظ، وهذا يخالف القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 6, 2, 'قانون حفظ الشحنة وقانون الانعكاس كلاهما قانون علمي يصف ظاهرة طبيعية متكررة.', '["نظرية الجاذبية الكونية نظرية علمية لا قانون.","نظرية الانفجار العظيم نظرية علمية لا قانون.","","كلاهما نظرية علمية، فلا يحتوي الزوج على أي قانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('mcq', 7, 3, 'عبارة ثبات الشحنة هي نص قانون حفظ الشحنة؛ تصف ظاهرة متكررة دون تفسير سببها، وبقية العبارات تفسير (نظرية) أو تخمين (فرضية).', '["العبارة تفسر سبب السقوط، والتفسير من شأن النظرية لا القانون.","العبارة تخمين لم يُختبر بعد، فهي فرضية لا قانون.","هذا نص نظرية الجاذبية الكونية، وهي نظرية علمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.787Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) قانون حفظ الشحنة: خلال التحولات المختلفة للمادة تبقى الشحنة الكهربائية ثابتة قبل التحول وبعده. (2) قانون الانعكاس: زاوية سقوط الشعاع الضوئي على السطح العاكس تساوي زاوية انعكاسه عن السطح نفسه.', '["اسم القانون الأول","نص القانون الأول","اسم القانون الثاني","نص القانون الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"اسم قانون صحيح","marks":1},{"element":"نصه","marks":1},{"element":"اسم قانون ثانٍ صحيح","marks":1},{"element":"نصه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مثالان صحيحان مع نصيهما"},{"level":"2–3 درجات","description":"مثالان دون نص كامل، أو مثال واحد مع نصه"},{"level":"1 درجة","description":"اسم قانون واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر نظرية الجاذبية الكونية مثالًا على قانون","كتابة نص قانون الانعكاس بأن الزاويتين متتامتان","الخلط بين حفظ الشحنة وحفظ الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.788Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) وفق قانون الانعكاس: زاوية الانعكاس = زاوية السقوط = $50^\circ$. (ب) وفق قانون حفظ الشحنة: تبقى الشحنة الكلية ثابتة قبل التحول وبعده، فهي صفر بعد الدلك أيضًا؛ إذن شحنة الساق + شحنة القماش = 0، فشحنة القماش = $-5$ وحدات شحنة.', '["تسمية قانون الانعكاس","زاوية الانعكاس $50^\\circ$","تسمية قانون حفظ الشحنة","شحنة القماش $-5$ وحدات"]'::jsonb, '["(أ) زاوية الانعكاس = زاوية السقوط = $50^\\circ$","(ب) الشحنة الكلية قبل = الشحنة الكلية بعد = 0","شحنة القماش $= 0 - (+5) = -5$ وحدات شحنة"]'::jsonb, '[{"element":"تسمية قانون الانعكاس","marks":1},{"element":"زاوية الانعكاس","marks":1},{"element":"تسمية قانون حفظ الشحنة","marks":1},{"element":"شحنة القماش بإشارتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية القانونين وإجابتان صحيحتان"},{"level":"2–3 درجات","description":"إجابة واحدة صحيحة كاملة، أو إجابتان دون تسمية"},{"level":"1 درجة","description":"تسمية قانون واحد دون إجابة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة زاوية الانعكاس $40^\\circ$ (متممة زاوية السقوط)","إعطاء شحنة القماش $+5$ أو صفرًا","إغفال إشارة الشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.788Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لأن كلًّا منهما قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة: فقانون حفظ الشحنة يصف ما يحدث للشحنة في أثناء تحولات المادة (تبقى ثابتة)، وقانون الانعكاس يصف العلاقة بين زاويتي السقوط والانعكاس (متساويتان). وكلاهما يصف الظاهرة ولا يفسر سبب حدوثها، بينما النظرية إطار يجمع عناصر البناء العلمي ويفسر المشاهدات (مثل نظرية الجاذبية الكونية).', '["كلاهما يجمع مشاهدات مترابطة لظاهرة متكررة","وصف ما يحدث في حفظ الشحنة","وصف العلاقة في الانعكاس","القانون يصف ولا يفسر، والنظرية تفسر"]'::jsonb, '[]'::jsonb, '[{"element":"معيار القانون","marks":1},{"element":"تحليل حفظ الشحنة","marks":1},{"element":"تحليل الانعكاس","marks":1},{"element":"التمييز عن النظرية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل صحيح للمثالين مع معيار القانون والتمييز عن النظرية"},{"level":"2–3 درجات","description":"تحليل مثال واحد أو إغفال التمييز عن النظرية"},{"level":"1 درجة","description":"ذكر معيار عام دون تحليل المثالين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القانون أثبت من النظرية لذلك سُمّي قانونًا","القول إن قانون الانعكاس يفسر سبب انعكاس الضوء","إغفال صفة الوصف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.788Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
