('mcq', 4, 'لماذا لا يمكن صياغة قانون علمي من ظاهرة شوهدت مرة واحدة فقط؟', null, null, '["لأن القانون يجب أن يفسر سبب حدوث الظاهرة","لأن القانون يُصاغ دائمًا قبل إجراء المشاهدات","لأن القانون يجمع مشاهدات مترابطة لظاهرة طبيعية متكررة","لأن الظاهرة الواحدة لا تحتوي على أي متغيرات"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 14 — سمات القانون العلمي'),
('mcq', 5, 'يمكن كتابة قانون الانعكاس على الصورة: «زاوية السقوط = زاوية الانعكاس». ما سمة القانون العلمي التي توضحها هذه الصورة؟', null, null, '["يفسر القانون سبب انعكاس الضوء عن السطوح","يمكن التعبير عن العلاقة بين المتغيرات بمعادلة رياضية","يجمع القانون عناصر البناء العلمي كافة","يُبنى القانون على تخمين لم يُختبر بعد"]'::jsonb, 'فهم', 'ربط مثال بسمة', 'متوسط', 'الكتاب ص 14 — سمات القانون العلمي'),
('mcq', 6, 'أيّ العبارات الآتية تتوافر فيها سمات القانون العلمي؟', null, null, '["تبقى الشحنة الكهربائية ثابتة في أثناء تحولات المادة كلها","شاهدتُ أمس جسمًا يسقط ببطء نحو الأرض","تسقط الأجسام لأنها تبحث عن أماكنها الطبيعية","قد يتأثر زمن السقوط بلون الجسم الساقط"]'::jsonb, 'تحليل', 'تمييز عبارة', 'متوسط', 'الكتاب ص 14 — سمات القانون العلمي'),
('mcq', 7, 'سأل طالب: «لماذا تتساوى زاويتا السقوط والانعكاس؟». هل يجيب قانون الانعكاس عن سؤاله؟', null, null, '["نعم؛ فالقانون يفسر سبب تساوي الزاويتين","نعم؛ لأن كل قانون يتضمن تفسيرًا لظاهرته","لا؛ لأن قانون الانعكاس لم تؤكده مشاهدات متكررة","لا؛ فالقانون يصف تساوي الزاويتين ولا يفسر سببه"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 14 — سمات القانون العلمي'),
('essay', 1, 'وضّح ثلاثًا من سمات القانون العلمي.', null, null, null, 'فهم', 'توضيح سمات', 'متوسط', 'الكتاب ص 14 — سمات القانون العلمي'),
('essay', 2, 'حلّل قانون حفظ الشحنة في ضوء سمات القانون العلمي: (أ) ما الظاهرة المتكررة التي يصفها؟ (ب) ما المتغيران اللذان يربط بينهما؟ (ج) اكتبه في صورة معادلة رياضية مستخدمًا الرمز $q_i$ للشحنة الكلية قبل التحول و$q_f$ للشحنة الكلية بعده. (د) هل يفسر سبب ثبات الشحنة؟', null, null, null, 'تحليل', 'تحليل قانون في ضوء سماته', 'صعب', 'الكتاب ص 14 — سمات القانون العلمي'),
('essay', 3, 'وضّح جاليليو أن سرعة سقوط الأجسام تعتمد على زمن سقوطها لا على كتلتها. بيّن ثلاث سمات للقانون العلمي تتوافر في هذه العبارة.', null, null, null, 'تحليل', 'ربط سمات بمثال', 'صعب', 'الكتاب ص 14 — سمات القانون العلمي وتطور نظرية سقوط الأجسام')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O16') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'من سمات القانون العلمي أنه يقدم وصفًا للظاهرة ولا يفسر سبب حدوثها.', '["القانون لا يفسر سبب حدوث الظواهر، والتفسير من شأن النظرية.","","القانون يجمع مشاهدات مترابطة لظاهرة متكررة، لا مشاهدة واحدة.","يمكن في معظم الحالات التعبير عن القانون بمعادلة رياضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 2, 3, 'يعبَّر عن القانون بعبارة تصف العلاقة بين متغيرين أو أكثر، ويمكن التعبير عن هذه العلاقة في معظم الحالات بمعادلة رياضية.', '["النموذج المادي تمثيل لشيء أو نظام، والقانون يعبَّر عنه غالبًا بمعادلة.","الفرضيات تخمينات قبل الاختبار، والقانون عبارة مبنية على مشاهدات متكررة.","الخريطة المفاهيمية تنظم خطوات أو مفاهيم، وليست الصورة المعتادة للتعبير عن القانون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 3, 0, 'القانون العلمي يعبَّر عنه بعبارة تصف العلاقة بين متغيرين أو أكثر، مثل زاويتي السقوط والانعكاس.', '["","القانون يصف علاقة بين متغيرات (كميات)، لا بين نظرية وفرضية.","القانون يصف علاقة بين متغيرات في ظاهرة طبيعية، لا بين أشخاص.","القانون مبني على مشاهدات مترابطة متكررة، لا على تجارب متعارضة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 4, 2, 'من سمات القانون أنه يجمع مشاهدات مترابطة لظاهرة طبيعية متكررة؛ فالمشاهدة الواحدة لا تكفي لصياغته.', '["القانون لا يفسر سبب الظاهرة أصلًا؛ والمانع هنا هو غياب التكرار.","القانون يأتي بعد جمع المشاهدات المترابطة لا قبلها.","","الظاهرة الواحدة قد تحتوي متغيرات؛ المشكلة أنها لم تتكرر مشاهدتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 5, 1, 'الصورة المعطاة معادلة رياضية تربط متغيرين (زاوية السقوط وزاوية الانعكاس)، وهذا يوضح أن القانون يمكن التعبير عنه في معظم الحالات بمعادلة رياضية.', '["المعادلة تصف تساوي الزاويتين ولا تبيّن سبب الانعكاس.","","جمع عناصر البناء العلمي من سمات النظرية لا القانون.","القانون مبني على مشاهدات مترابطة متكررة، لا على تخمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 6, 0, 'عبارة ثبات الشحنة تصف ظاهرة متكررة مبنية على مشاهدات مترابطة، وتصف العلاقة بين الشحنة قبل التحول وبعده دون تفسير؛ فتتوافر فيها سمات القانون.', '["","هذه مشاهدة واحدة لا تصف ظاهرة متكررة ولا علاقة بين متغيرات.","هذه محاولة تفسير لسبب السقوط، والقانون يصف ولا يفسر.","هذه فرضية (تخمين) لم تدعمها مشاهدات مترابطة متكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('mcq', 7, 3, 'القانون العلمي لا يفسر سبب حدوث الظواهر ولكنه يقدم وصفًا لها؛ فقانون الانعكاس يصف تساوي الزاويتين، ولا يجيب عن سؤال «لماذا؟».', '["القانون لا يفسر سبب حدوث الظاهرة، بل يقدم وصفًا لها.","القوانين لا تتضمن تفسيرًا لأسباب الظواهر؛ هذا عمل النظريات.","الحكم صحيح لكن التعليل خاطئ؛ فالقانون مبني على مشاهدات متكررة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.789Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) يجمع مشاهدات مترابطة لظاهرة طبيعية متكررة. (2) يعبَّر عنه بعبارة تصف العلاقة بين متغيرين أو أكثر، ويمكن في معظم الحالات التعبير عن هذه العلاقة بمعادلة رياضية. (3) يقدم وصفًا للظاهرة ولا يفسر سبب حدوثها.', '["يجمع مشاهدات مترابطة لظاهرة متكررة","يصف العلاقة بين متغيرين أو أكثر، وغالبًا بمعادلة رياضية","يصف الظاهرة ولا يفسر سببها"]'::jsonb, '[]'::jsonb, '[{"element":"السمة الأولى","marks":1},{"element":"السمة الثانية","marks":1},{"element":"السمة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاث سمات صحيحة موضحة"},{"level":"2 درجتان","description":"سمتان صحيحتان"},{"level":"1 درجة","description":"سمة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «يفسر سبب الظاهرة» سمة للقانون","ذكر «يجمع عناصر البناء العلمي» وهي سمة النظرية","القول إن القانون لا يتغير أبدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.790Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الظاهرة: تحولات المادة المختلفة وما يحدث فيها للشحنة الكهربائية، وهي ظاهرة تتكرر مشاهدتها. (ب) يربط بين الشحنة الكلية قبل التحول والشحنة الكلية بعده. (ج) $q_i = q_f$. (د) لا؛ فهو يصف ثبات الشحنة ولا يفسر سببه، وهذه سمة القانون العلمي.', '["الظاهرة المتكررة: تحولات المادة","المتغيران: الشحنة قبل التحول وبعده","المعادلة: $q_i = q_f$","القانون يصف ولا يفسر"]'::jsonb, '[]'::jsonb, '[{"element":"الظاهرة","marks":1},{"element":"المتغيران","marks":1},{"element":"المعادلة","marks":1},{"element":"الوصف دون التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة عن البنود الأربعة"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة معادلة يكون فيها مجموع الشحنتين صفرًا دائمًا","القول إن القانون يفسر سبب ثبات الشحنة","عدّ المتغيرين «الشحنة» و«المادة»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.790Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) تصف العلاقة بين متغيرين: سرعة سقوط الجسم وزمن سقوطه. (2) يمكن التعبير عن هذه العلاقة بمعادلة رياضية (السرعة تزداد بازدياد زمن السقوط؛ ومن أمثلة ذلك — للاستئناس لا للمطالبة — $v = gt$ لجسم يسقط من السكون بإهمال مقاومة الهواء). (3) تصف كيف يسقط الجسم ولا تفسر سبب سقوطه؛ إذ جاء تفسير السبب لاحقًا عندما أرجعه نيوتن إلى قوة التجاذب بين الأرض والأجسام. كما أنها مبنية على مشاهدات مترابطة متكررة لسقوط الأجسام.', '["علاقة بين متغيرين: السرعة والزمن","إمكان كتابتها بمعادلة رياضية","تصف ولا تفسر سبب السقوط","مبنية على مشاهدات متكررة (عنصر إضافي مقبول)"]'::jsonb, '[]'::jsonb, '[{"element":"السمة الأولى مع ربطها بالعبارة","marks":1},{"element":"السمة الثانية مع ربطها بالعبارة","marks":1},{"element":"السمة الثالثة مع ربطها بالعبارة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاث سمات صحيحة مربوطة بالعبارة"},{"level":"2 درجتان","description":"سمتان صحيحتان مربوطتان بالعبارة"},{"level":"1 درجة","description":"سمة واحدة صحيحة أو سمات دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكتلة متغيرًا تعتمد عليه السرعة","القول إن العبارة تفسر سبب السقوط","سرد سمات عامة دون ربطها بالعبارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.790Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
