('mcq', 2, 'ما النظرية التي تنص على أن «جميع الكتل في الكون تنجذب إلى كتل أخرى ويجذب بعضها بعضًا»؟', null, null, '["نظرية الجاذبية الكونية","نظرية الانفجار العظيم","قانون حفظ الشحنة","نظرية أرسطو في السقوط"]'::jsonb, 'تذكر', 'تحديد النظرية من نصها', 'سهل', 'الكتاب ص 14 — أمثلة على النظريات العلمية'),
('mcq', 3, 'حاول بعض العلماء في منتصف ستينيات القرن الماضي إزالة تشويش مستمر في هوائي فلكي دون جدوى، ثم عُرف أن التشويش ناتج عن موجات معينة تصدر من الفضاء الخارجي. لأيّ نظرية عُدّ ذلك دعمًا تجريبيًّا؟', null, null, '["نظرية الجاذبية الكونية","نظرية سقوط الأجسام","قانون الانعكاس","نظرية الانفجار العظيم"]'::jsonb, 'تذكر', 'ربط دليل بنظرية', 'سهل', 'الكتاب ص 13 — الدعم التجريبي لنظرية الانفجار العظيم'),
('mcq', 4, 'ما النظرية التي مرّت بمراجعات متتالية بدأت بآراء الفلاسفة الإغريق، ثم جاليليو، ثم نيوتن، ثم أينشتاين؟', null, null, '["نظرية الانفجار العظيم","نظرية سقوط الأجسام","قانون حفظ الشحنة","النماذج المختلفة للذرة"]'::jsonb, 'تذكر', 'تذكر مثال', 'متوسط', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('mcq', 5, 'ما الإضافة التي قدّمها نيوتن إلى نظرية سقوط الأجسام؟', null, null, '["بيّن أن سرعة السقوط تعتمد على زمن السقوط لا على الكتلة","رأى أن الأجسام تسقط لأنها تبحث عن أماكنها الطبيعية","أرجع سبب السقوط إلى قوة تجاذب بين الأرض والأجسام","افترض أن التجاذب سببه تحدّب الفضاء (الزمكان) حول الكتلة"]'::jsonb, 'تذكر', 'تذكر مرحلة من تطور نظرية', 'متوسط', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('mcq', 6, 'ما الرأي الذي قدّمه الفلاسفة الإغريق في سقوط الأجسام؟', null, null, '["سرعة سقوط الجسم تعتمد على زمن سقوطه فقط","الأجسام تسقط بسبب قوة تجاذب بينها وبين الأرض","جميع الأجسام تسقط بالسرعة نفسها أيًّا كانت كتلتها","كلما كانت كتلة الجسم أكبر كان سقوطه أسرع"]'::jsonb, 'تذكر', 'تذكر مرحلة من تطور نظرية', 'متوسط', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('mcq', 7, 'ما الترتيب الزمني الصحيح لأصحاب المراحل التي مرّت بها نظرية سقوط الأجسام؟', null, null, '["الإغريق ← جاليليو ← نيوتن ← أينشتاين","جاليليو ← الإغريق ← نيوتن ← أينشتاين","الإغريق ← نيوتن ← جاليليو ← أينشتاين","الإغريق ← جاليليو ← أينشتاين ← نيوتن"]'::jsonb, 'فهم', 'ترتيب مراحل', 'صعب', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('essay', 1, 'اذكر مثالين على نظريات علمية، مبيّنًا مضمون كل منهما في جملة واحدة.', null, null, null, 'تذكر', 'ذكر أمثلة', 'متوسط', 'الكتاب ص 13، 14 — أمثلة على النظريات العلمية'),
('essay', 2, 'صف المراحل الأربع التي مرّت بها نظرية سقوط الأجسام، ذاكرًا صاحب كل مرحلة وفكرتها الأساسية.', null, null, null, 'فهم', 'وصف تطور نظرية', 'صعب', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('essay', 3, 'اذكر مثالًا على دعم تجريبي لنظرية علمية، ووضّح كيف دعم هذا الدليل النظرية.', null, null, null, 'فهم', 'توضيح مثال', 'صعب', 'الكتاب ص 13 — الدعم التجريبي لنظرية الانفجار العظيم')
