from (values
('mcq', 1, 2, 'نظرية الجاذبية الكونية مثال على نظرية علمية، تنص على أن جميع الكتل في الكون تنجذب إلى كتل أخرى ويجذب بعضها بعضًا.', '["هذا قانون علمي يصف تساوي زاويتي السقوط والانعكاس، وليس نظرية.","هذا قانون علمي يصف ثبات الشحنة، وليس نظرية.","","الطريقة العلمية أسلوب للإجابة عن التساؤلات العلمية، وليست نظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-17T19:43:12.790Z"}'::jsonb),
('mcq', 2, 0, 'هذا نص نظرية الجاذبية الكونية.', '["","نظرية الانفجار العظيم تتعلق بنشأة الكون، لا بتجاذب الكتل.","هذا قانون عن ثبات الشحنة الكهربائية، لا عن تجاذب الكتل.","رأي أرسطو أن سرعة السقوط تزداد بازدياد الوزن، ولا ينص على تجاذب جميع الكتل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-17T19:43:12.790Z"}'::jsonb),
('mcq', 3, 3, 'عُدّ اكتشاف أن التشويش المستمر في الهوائي ناتج عن موجات تصدر من الفضاء الخارجي دعمًا تجريبيًّا لنظرية الانفجار العظيم.', '["التشويش الصادر من الفضاء عُدّ دعمًا لنظرية نشأة الكون لا لنظرية تجاذب الكتل.","الموجات الصادرة من الفضاء الخارجي لا علاقة لها بتفسير سقوط الأجسام.","هذا قانون علمي لا نظرية، ولا يتعلق بموجات الفضاء الخارجي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('mcq', 4, 1, 'نظرية سقوط الأجسام خضعت للكثير من التعديل والمراجعة: من رأي الإغريق، إلى جاليليو، ثم نيوتن، ثم أينشتاين.', '["هذه النظرية تتعلق بنشأة الكون، والمراحل المذكورة تخص تفسير سقوط الأجسام.","","هذا قانون لا نظرية، ولم يرتبط بهذه المراحل.","هذه نماذج تعاقبت في الكيمياء، لا في تفسير سقوط الأجسام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('mcq', 5, 2, 'رأى نيوتن أن جاليليو كان محقًّا، وأرجع سبب سقوط الأجسام إلى وجود قوة تجاذب بين الأرض وهذه الأجسام.', '["هذه إضافة جاليليو التي سبقت نيوتن.","هذا رأي الفلاسفة الإغريق.","","هذا ما افترضه أينشتاين فيما بعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('mcq', 6, 3, 'اعتقد الفلاسفة الإغريق أن الأجسام تسقط لأنها تبحث عن أماكنها الطبيعية، وأنه كلما كانت كتلة الجسم أكبر كان سقوطه أسرع.', '["هذا رأي جاليليو الذي راجع رأي الإغريق.","هذا تفسير نيوتن.","هذا يخالف رأي الإغريق الذين ربطوا سرعة السقوط بالكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('mcq', 7, 0, 'بدأت بالإغريق (الكتلة الأكبر أسرع سقوطًا)، ثم جاليليو (السرعة تعتمد على الزمن لا الكتلة)، ثم نيوتن (قوة التجاذب)، ثم أينشتاين (تحدّب الزمكان).', '["","رأي الإغريق هو الأقدم، وقد راجعه جاليليو بعدهم.","نيوتن أيّد رأي جاليليو وبنى عليه، فجاليليو سبقه.","أينشتاين جاء بعد نيوتن، وافترض فيما بعد أن التجاذب سببه تحدّب الزمكان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) نظرية الجاذبية الكونية: جميع الكتل في الكون تنجذب إلى كتل أخرى ويجذب بعضها بعضًا. (2) نظرية الانفجار العظيم: تفسر نشأة الكون، ومن الأدلة التجريبية الداعمة لها التشويش المستمر في الهوائيات الناتج عن موجات تصدر من الفضاء الخارجي. (ويُقبل: نظرية سقوط الأجسام التي ترجع السقوط إلى قوة تجاذب بين الأرض والأجسام.)', '["اسم النظرية الأولى","مضمونها","اسم النظرية الثانية","مضمونها أو الدليل عليها"]'::jsonb, '[]'::jsonb, '[{"element":"نظرية أولى صحيحة","marks":1},{"element":"مضمونها","marks":1},{"element":"نظرية ثانية صحيحة","marks":1},{"element":"مضمونها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نظريتان صحيحتان مع مضمون كل منهما"},{"level":"2–3 درجات","description":"نظريتان دون مضمون كامل، أو نظرية واحدة مع مضمونها"},{"level":"1 درجة","description":"اسم نظرية واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر قانون الانعكاس أو حفظ الشحنة مثالًا على نظرية","الخلط بين مضموني النظريتين","ذكر اسم دون أي مضمون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الفلاسفة الإغريق: الأجسام تسقط لأنها تبحث عن أماكنها الطبيعية، وكلما كانت كتلتها أكبر كان سقوطها أسرع. (2) جاليليو: سرعة سقوط الأجسام تعتمد على زمن سقوطها لا على كتلتها. (3) نيوتن: رأي جاليليو صحيح، وسبب السقوط وجود قوة تجاذب بين الأرض والأجسام. (4) أينشتاين: ما زالت مقترحات جاليليو ونيوتن تحتفظ بصحتها، وافترض أن قوة التجاذب بين جسمين سببها الكتلة التي تؤدي إلى تحدّب الفضاء (الزمكان) حولها.', '["مرحلة الإغريق وفكرتها","مرحلة جاليليو وفكرتها","مرحلة نيوتن وفكرتها","مرحلة أينشتاين وفكرتها"]'::jsonb, '[]'::jsonb, '[{"element":"الإغريق","marks":1},{"element":"جاليليو","marks":1},{"element":"نيوتن","marks":1},{"element":"أينشتاين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المراحل الأربع بترتيبها الصحيح مع أفكارها"},{"level":"2–3 درجات","description":"مرحلتان أو ثلاث صحيحة، أو خلل في الترتيب"},{"level":"1 درجة","description":"مرحلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة فكرة التجاذب إلى جاليليو","نسبة رأي «الأثقل أسرع» إلى جاليليو","القول إن أينشتاين ألغى أفكار نيوتن كليًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-17T19:43:12.791Z"}'::jsonb),
('essay', 3, null::int, null, null, 'مثال: نظرية الانفجار العظيم. في منتصف ستينيات القرن الماضي حاول بعض العلماء إزالة تشويش مستمر في هوائي يُستخدم في علم الفلك دون جدوى، ثم عُرف أن هذا التشويش (مثل الصوت الذي يصدره التلفاز عند انقطاع البث) ناتج عن موجات معينة تصدر من الفضاء الخارجي. وقد عُدّ وجود هذه الموجات القادمة من كل اتجاهات الفضاء مشاهدة تجريبية تتفق مع ما تتوقعه النظرية، فدعمها؛ لأن النظرية العلمية إطار يفسر المشاهدات المدعومة بنتائج تجريبية.', '["تسمية النظرية: الانفجار العظيم","وصف الدليل: تشويش مستمر في هوائي فلكي","مصدر التشويش موجات من الفضاء الخارجي","توضيح أن المشاهدة اتفقت مع النظرية فدعمتها"]'::jsonb, '[]'::jsonb, '[{"element":"النظرية","marks":1},{"element":"الدليل","marks":1},{"element":"مصدره","marks":1},{"element":"كيفية الدعم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مثال صحيح مكتمل مع توضيح كيفية الدعم"},{"level":"2–3 درجات","description":"مثال صحيح مع وصف ناقص للدليل أو لكيفية الدعم"},{"level":"1 درجة","description":"تسمية النظرية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة دليل التشويش إلى نظرية الجاذبية الكونية","القول إن التشويش عطل في الجهاز فقط","إغفال ربط الدليل بالنظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.792Z"}'::jsonb)
