('mcq', 5, 2, 'التوقع تخمين علمي عن كيفية ارتباط متغيرين (طول النابض والكتلة) قبل اختباره؛ فهو فرضية.', '["التوقع لم يُختبر بعد ولم تُجمع له مشاهدات مترابطة، فلا يُعد قانونًا.","الحقيقة أمر ثابت بالمشاهدة، وتوقع الطالب لم يُختبر بعد.","","النموذج تمثيل لفكرة أو نظام، وليس تخمينًا عن ارتباط المتغيرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.792Z"}'::jsonb),
