('mcq', 3, 0, 'النظرية العلمية قد تكون تفسيرًا للقوانين، وهي تشتمل عليها ضمن عناصر البناء العلمي.', '["","القانون يصف ولا يفسر؛ والنظرية هي التي قد تفسر القوانين.","النظرية والقانون مختلفان في الوظيفة (التفسير والوصف)، ولا تتحول النظرية إلى قانون.","النظرية تشتمل على القوانين ضمن عناصر البناء العلمي، وقد تكون تفسيرًا لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('mcq', 4, 2, 'قد تُراجع القوانين والنظريات أو تُهمل مع الزمن، وتطور تفسير سقوط الأجسام مثال على ذلك.', '["تتابع المراجعات يدل على عكس ذلك؛ فالنظرية قابلة للمراجعة.","المراحل قدّمت تفسيرات متتالية لسبب السقوط، والوصف دون التفسير سمة القانون.","","كل مراجعة جاءت بسبب ملاحظات وتجارب جديدة، فالنظرية تحتاج إلى دعم تجريبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('mcq', 5, 1, 'من سمات النظرية العلمية أنها لا تتعارض مع نظرية أخرى في موضوع آخر من موضوعات العلم؛ لذا يحتاج التفسير الجديد إلى إعادة فحص.', '["حداثة التفسير لا تكفي، ومن سمات النظرية ألا تتعارض مع نظرية في موضوع آخر.","","لا تُلغى نظرية مدعومة بقوة لمجرد تعارضها مع تفسير جديد غير مدعوم.","التفسير لا يتحول إلى قانون؛ فالقانون يصف ولا يفسر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('mcq', 6, 2, 'النظريات قد تُراجع أو تُعدّل أو تُهمل مع الزمن عند ظهور ملاحظات جديدة، فعبارة «تبقى صحيحة إلى الأبد» ليست من سماتها.', '["هذه سمة صحيحة من سمات النظرية.","هذه سمة صحيحة؛ فالنظرية قد تفسر القوانين.","","هذه سمة صحيحة من سمات النظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('mcq', 7, 3, 'تتوافر في هذا التفسير سمات النظرية: يفسر المشاهدات، وتدعمه التجارب بقوة، ولا يتعارض مع نظرية أخرى.', '["غياب الدعم التجريبي يجعله فرضية مهما كانت شهرة صاحبه.","الوصف دون تفسير السبب قانون لا نظرية.","التعارض مع نظرية أخرى وضعف الدعم التجريبي يمنعان تسميته نظرية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من سمات النظرية العلمية: (1) تفسر المشاهدات والملاحظات المدعومة بنتائج تجريبية، ولا يُطلق اسم نظرية إلا على التفسير الذي تدعمه التجارب بقوة. (2) لا تتعارض مع نظرية أخرى في موضوع آخر من موضوعات العلم. (3) تشتمل على عناصر البناء العلمي كافة، وقد تكون تفسيرًا للقوانين، وهي أفضل تفسير ممكن لمبدأ عمل الأشياء. (4) قد تُراجع أو تُعدّل أو تُهمل مع الزمن.', '["تفسر المشاهدات المدعومة بالتجارب","لا تتعارض مع نظرية أخرى","تشتمل على عناصر البناء العلمي/ قد تفسر القوانين","قابلة للمراجعة مع الزمن"]'::jsonb, '[]'::jsonb, '[{"element":"السمة الأولى","marks":1},{"element":"السمة الثانية","marks":1},{"element":"السمة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاث سمات صحيحة موضحة"},{"level":"2 درجتان","description":"سمتان صحيحتان"},{"level":"1 درجة","description":"سمة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «تصف ولا تفسر» سمة للنظرية","القول إن النظرية ثابتة لا تتغير","القول إن النظرية تخمين لم يُختبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.794Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السمة الأولى: النظريات قد تُراجع وتُعدّل مع الزمن عندما توفر التجارب الجديدة ملاحظات جديدة؛ فرأي الإغريق (الأثقل يسقط أسرع) راجعه جاليليو (السرعة تعتمد على زمن السقوط لا الكتلة)، ثم جاء نيوتن ثم أينشتاين بمراجعات أخرى. السمة الثانية: النظرية قد تكون تفسيرًا للقوانين؛ فجاليليو وصف كيف تسقط الأجسام، ونيوتن فسّر سبب ذلك بقوة التجاذب بين الأرض والأجسام. (ويُقبل: النظرية تُقبل لأنها مدعومة بالتجارب، فقد بقيت أفكار جاليليو ونيوتن صحيحة لأن التجارب تدعمها.)', '["ذكر سمة المراجعة والتعديل","ربطها بمراحل التطور","ذكر سمة تفسير القوانين (أو الدعم التجريبي)","ربطها بعمل جاليليو ونيوتن"]'::jsonb, '[]'::jsonb, '[{"element":"السمة الأولى","marks":1},{"element":"ربطها بالمثال","marks":1},{"element":"السمة الثانية","marks":1},{"element":"ربطها بالمثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"سمتان صحيحتان مربوطتان بالمثال ربطًا صحيحًا"},{"level":"2–3 درجات","description":"سمتان دون ربط كافٍ، أو سمة واحدة مربوطة"},{"level":"1 درجة","description":"سمة واحدة دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أينشتاين أثبت خطأ نيوتن كليًّا","نسبة تفسير التجاذب إلى جاليليو","سرد المراحل دون استخراج السمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-17T19:43:12.795Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لا يُعدّ نظرية علمية مقبولة اليوم؛ لأن من سمات النظرية أن تفسر المشاهدات المدعومة بنتائج تجريبية وأن تدعمها التجارب بقوة، وهذا التفسير لا تدعمه التجارب: فعند إسقاط قطع نقد ملتصقة وقطعة منفردة معًا تصل جميعها إلى الأرض في الوقت نفسه تقريبًا رغم اختلاف أوزانها. لذلك رُوجع هذا التفسير مع الزمن (وهي سمة أخرى من سمات النظريات)، فبيّن جاليليو أن سرعة السقوط تعتمد على زمن السقوط لا على الكتلة، ثم فسّر نيوتن السقوط بقوة التجاذب. كما أن فكرة «البحث عن الأماكن الطبيعية» لا يمكن اختبارها تجريبيًّا.', '["الحكم: لا يُعد نظرية مقبولة اليوم","معيار الدعم التجريبي القوي","دليل تجريبي مخالف (سقوط الأجسام المختلفة الوزن معًا)","مراجعة التفسير وحلول تفسيرات أحدث محله"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المعيار","marks":1},{"element":"الدليل المخالف","marks":1},{"element":"المراجعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع المعيار والدليل والمراجعة"},{"level":"2–3 درجات","description":"حكم صحيح مع عنصر أو عنصرين من التعليل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"قبول التفسير أو لا إجابة"}]'::jsonb, '["قبول التفسير لأنه قديم ومشهور","الاعتقاد أن الأثقل يسقط أسرع دائمًا","إغفال الدليل التجريبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-17T19:43:12.795Z"}'::jsonb)
