('mcq', 1, 'في خريطة المفاهيم الآتية لخطوات الطريقة العلمية، ما الخطوة المناسبة للمربع (1)؟', null, '[{"src":"qimg/phys1/c1l1-map-step4.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. نصوص المربعات من الأعلى: «تحديد المشكلة»، «جمع المعلومات»، «وضع الفرضيات»، المربع الرابع فارغ ومكتوب فيه (1)، «تسجيل النتائج وتحليلها»، «الاستنتاج». صندوق اليسار: «النتائج تدعم الفرضية» وعلى سهمه الصاعد كلمة «تكرار». صندوق اليمين: «النتائج لا تدعم الفرضية» وعلى سهمه الصاعد «تعديل الفرضية»."}]'::jsonb, '["تعديل الفرضية","طرح سؤال بناءً على المشاهدات","إجراء التجارب لاختبار الفرضية","صياغة قانون علمي من النتائج"]'::jsonb, 'فهم', 'إكمال خريطة مفاهيمية', 'سهل', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('mcq', 2, 'في خريطة المفاهيم الآتية، ما الخطوة المناسبة للمربع (1)؟', null, '[{"src":"qimg/phys1/c1l1-map-step5.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. نصوص المربعات من الأعلى: «تحديد المشكلة»، «جمع المعلومات»، «وضع الفرضيات»، «إجراء التجارب لاختبار الفرضية»، المربع الخامس فارغ ومكتوب فيه (1)، «الاستنتاج». صندوق اليسار: «النتائج تدعم الفرضية» وعلى سهمه «تكرار». صندوق اليمين: «النتائج لا تدعم الفرضية» وعلى سهمه «تعديل الفرضية»."}]'::jsonb, '["تسجيل النتائج وتحليلها","وضع فرضية جديدة","تحديد المشكلة المدروسة","جمع المعلومات عن المشكلة"]'::jsonb, 'فهم', 'إكمال خريطة مفاهيمية', 'سهل', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('mcq', 3, 'في خريطة المفاهيم الآتية يخرج من الصندوق (1) سهم مكتوب عليه «تعديل الفرضية» يعود إلى خطوة وضع الفرضيات. ما العبارة المناسبة للصندوق (1)؟', null, '[{"src":"qimg/phys1/c1l1-map-rightbox.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. نصوص المربعات من الأعلى: «تحديد المشكلة»، «جمع المعلومات»، «وضع الفرضيات»، «إجراء التجارب لاختبار الفرضية»، «تسجيل النتائج وتحليلها»، «الاستنتاج». صندوق اليمين فارغ ومكتوب فيه (1)، وعلى سهمه الصاعد إلى «وضع الفرضيات» عبارة «تعديل الفرضية». صندوق اليسار فارغ ومكتوب فيه (2)، وعلى سهمه الصاعد إلى المربع الرابع كلمة «تكرار»."}]'::jsonb, '["النتائج تدعم الفرضية","تتحول الفرضية إلى نظرية","تحديد مشكلة جديدة","النتائج لا تدعم الفرضية"]'::jsonb, 'فهم', 'إكمال خريطة مفاهيمية', 'متوسط', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('mcq', 4, 'في خريطة المفاهيم الآتية، ما العبارة المناسبة للسهم (1) الذي يصل صندوق «النتائج تدعم الفرضية» بخطوة إجراء التجارب؟', null, '[{"src":"qimg/phys1/c1l1-map-repeat.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. نصوص المربعات من الأعلى: «تحديد المشكلة»، «جمع المعلومات»، «وضع الفرضيات»، «إجراء التجارب لاختبار الفرضية»، «تسجيل النتائج وتحليلها»، «الاستنتاج». صندوق اليسار: «النتائج تدعم الفرضية»، وعلى سهمه الصاعد إلى المربع الرابع الرمز (1) بدل الكلمة. صندوق اليمين: «النتائج لا تدعم الفرضية» وعلى سهمه الصاعد إلى «وضع الفرضيات» عبارة «تعديل الفرضية»."}]'::jsonb, '["إلغاء الفرضية والبدء بمشكلة جديدة","تكرار التجربة للتأكد من النتائج","تعديل الفرضية قبل اختبارها مجددًا","الاكتفاء بالنتيجة دون أي اختبار آخر"]'::jsonb, 'فهم', 'إكمال خريطة مفاهيمية', 'متوسط', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('mcq', 5, 'في خريطة المفاهيم الآتية، ما الخطوة المناسبة للمربع (1) الذي تبدأ به الخريطة؟', null, '[{"src":"qimg/phys1/c1l1-map-step1.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. المربع الأول في أعلى العمود فارغ ومكتوب فيه (1)، وتليه المربعات: «جمع المعلومات»، «وضع الفرضيات»، «إجراء التجارب لاختبار الفرضية»، «تسجيل النتائج وتحليلها»، «الاستنتاج». صندوق اليسار: «النتائج تدعم الفرضية» وعلى سهمه «تكرار». صندوق اليمين: «النتائج لا تدعم الفرضية» وعلى سهمه «تعديل الفرضية»."}]'::jsonb, '["الاستنتاج من النتائج","تسجيل النتائج وتحليلها","تعديل الفرضية المقترحة","تحديد المشكلة"]'::jsonb, 'تذكر', 'إكمال خريطة مفاهيمية', 'سهل', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('mcq', 6, 'أراد طالب رسم خريطة مفاهيم لخطوات الطريقة العلمية في عمود واحد من الأعلى إلى الأسفل. أيّ الترتيبات الآتية صحيح؟', null, null, '["تحديد المشكلة ← وضع الفرضيات ← إجراء التجارب ← تحليل النتائج ← الاستنتاج","وضع الفرضيات ← تحديد المشكلة ← إجراء التجارب ← تحليل النتائج ← الاستنتاج","تحديد المشكلة ← إجراء التجارب ← وضع الفرضيات ← تحليل النتائج ← الاستنتاج","تحديد المشكلة ← وضع الفرضيات ← الاستنتاج ← إجراء التجارب ← تحليل النتائج"]'::jsonb, 'تطبيق', 'ترتيب خطوات', 'متوسط', 'الكتاب ص 12 — الطريقة العلمية'),
('mcq', 7, 'في خريطة مفاهيم الطريقة العلمية يعود سهم من نهاية الخريطة إلى خطوة وضع الفرضيات. ما الذي يدل عليه هذا السهم؟', null, null, '["الطريقة العلمية تسير في اتجاه واحد وتنتهي دائمًا بالاستنتاج","يجب البدء من جديد بتحديد مشكلة أخرى مختلفة تمامًا","تُعدّل الفرضية وتُختبر من جديد إذا لم تدعمها النتائج","الفرضية تصبح نظرية بمجرد الوصول إلى الاستنتاج"]'::jsonb, 'تحليل', 'تفسير عنصر في خريطة', 'صعب', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('essay', 1, 'أكمل خريطة المفاهيم الآتية لخطوات الطريقة العلمية، بكتابة ما يناسب كل رقم من (1) إلى (5).', null, '[{"src":"qimg/phys1/c1l1-map-blank5.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. المربعات من الأعلى: «تحديد المشكلة»، مربع فارغ (1)، «وضع الفرضيات»، مربع فارغ (2)، مربع فارغ (3)، «الاستنتاج». صندوق اليسار فارغ (4) وعلى سهمه الصاعد إلى المربع (2) كلمة «تكرار». صندوق اليمين فارغ (5) وعلى سهمه الصاعد إلى «وضع الفرضيات» عبارة «تعديل الفرضية»."}]'::jsonb, null, 'فهم', 'إكمال خريطة مفاهيمية', 'متوسط', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('essay', 2, 'رسم طالب خريطة المفاهيم الآتية لخطوات الطريقة العلمية، فوقع فيها خطآن. حدّد كل خطأ، وعلّل لماذا هو خطأ، ثم اكتب التصحيح.', null, '[{"src":"qimg/phys1/c1l1-map-errors.svg","alt":"خريطة مفاهيم لخطوات الطريقة العلمية: عمود من ستة مربعات متصلة بأسهم من الأعلى إلى الأسفل. ومن المربع الأخير يخرج سهم إلى صندوق على اليسار وسهم إلى صندوق على اليمين. ومن صندوق اليسار يصعد خط ينتهي بسهم يدخل المربع الرابع، ومن صندوق اليمين يصعد خط ينتهي بسهم يدخل المربع الثالث. المربعات من الأعلى: «تحديد المشكلة»، «جمع المعلومات»، «إجراء التجارب لاختبار الفرضية»، «وضع الفرضيات»، «تسجيل النتائج وتحليلها»، «الاستنتاج». صندوق اليسار: «النتائج لا تدعم الفرضية» وعلى سهمه الصاعد إلى المربع الرابع («وضع الفرضيات») كلمة «تكرار». صندوق اليمين: «النتائج تدعم الفرضية» وعلى سهمه الصاعد إلى المربع الثالث («إجراء التجارب لاختبار الفرضية») عبارة «تعديل الفرضية»."}]'::jsonb, null, 'تقويم', 'تقويم خريطة مفاهيمية', 'صعب', 'الكتاب ص 12، 26 — خريطة مفاهيم خطوات الطريقة العلمية'),
('essay', 3, 'لاحظ طالب أن قطع النقد المعدنية الملتصقة والقطعة المنفردة تبدو كأنها تصل إلى الأرض معًا عند إسقاطها من الارتفاع نفسه. ارسم خريطة مفاهيم (بالكتابة: مربعات وأسهم) لخطوات الطريقة العلمية التي يتبعها لدراسة سؤاله: «هل يؤثر وزن الجسم في سرعة سقوطه؟»، مع كتابة ما يقابل كل خطوة في هذه الدراسة، ومسارَي «تكرار» و«تعديل الفرضية».', null, null, null, 'تطبيق', 'بناء خريطة مفاهيمية لموقف', 'صعب', 'الكتاب ص 9، 12، 26 — التجربة الاستهلالية وخطوات الطريقة العلمية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O20') and x.type = v.type and x.number = v.number);
