select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'بعد وضع الفرضيات تُصمَّم التجارب العلمية وتُنفَّذ لاختبار صحة الفرضية، ثم تُسجَّل النتائج وتُحلَّل.', '["تعديل الفرضية مكتوب على السهم الراجع إلى وضع الفرضيات، ولا يأتي مباشرة بعد وضعها.","طرح السؤال جزء من تحديد المشكلة في بداية الخريطة، لا بعد وضع الفرضيات.","","صياغة القانون ليست خطوة تلي وضع الفرضيات مباشرة؛ فالفرضية تُختبر أولًا بالتجارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-17T19:43:12.795Z"}'::jsonb),
('mcq', 2, 0, 'بعد تنفيذ التجارب تُسجَّل النتائج وتُنظَّم ثم تُحلَّل، ومن التحليل يُستخلص الاستنتاج.', '["","وضع الفرضيات خطوة سابقة في الخريطة، وتليها التجارب لا العكس.","تحديد المشكلة هو الخطوة الأولى في أعلى الخريطة.","جمع المعلومات يسبق وضع الفرضيات، لا يأتي بعد إجراء التجارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-17T19:43:12.795Z"}'::jsonb),
('mcq', 3, 3, 'إذا جاءت النتائج غير داعمة للفرضية، تُعدّل الفرضية وتُختبر من جديد؛ لذا يقود الصندوق (1) إلى «تعديل الفرضية».', '["إذا دعمت النتائج الفرضية فلا حاجة إلى تعديلها، بل تُكرر التجربة للتأكد.","الفرضية لا تُعدّل عند تحولها إلى نظرية؛ والتعديل سببه عدم دعم النتائج لها.","السهم يعود إلى وضع الفرضيات لتعديلها، لا إلى بداية مشكلة جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.796Z"}'::jsonb),
('mcq', 4, 1, 'يجب أن تكون التجارب والنتائج قابلة للتكرار، فتُعاد التجربة (من الباحث نفسه أو من باحثين آخرين) للحصول على النتائج نفسها.', '["النتائج تدعم الفرضية، فلا مبرر لإلغائها.","","التعديل يكون عندما لا تدعم النتائج الفرضية، لا عندما تدعمها.","يجب أن تكون التجارب والنتائج قابلة للتكرار، فلا يُكتفى بتجربة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.796Z"}'::jsonb),
('mcq', 5, 3, 'تبدأ الطريقة العلمية بطرح أسئلة بناءً على مشاهدات، أي بتحديد المشكلة.', '["الاستنتاج يأتي في نهاية الخريطة بعد تحليل النتائج.","تسجيل النتائج يأتي بعد إجراء التجارب لا في بدايتها.","تعديل الفرضية يكون بعد الاستنتاج إذا لم تدعمها النتائج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-17T19:43:12.796Z"}'::jsonb),
('mcq', 6, 0, 'تبدأ الطريقة العلمية بتحديد المشكلة، ثم وضع الفرضيات، ثم تصميم التجارب وتنفيذها لاختبارها، ثم تسجيل النتائج وتحليلها، ثم الاستنتاج.', '["","الفرضية تُوضع إجابةً عن مشكلة محددة، فتحديد المشكلة يسبقها.","التجارب تُصمم لاختبار الفرضية، فلا تسبق وضعها.","الاستنتاج يُبنى على تحليل نتائج التجارب، فلا يسبقها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-17T19:43:12.797Z"}'::jsonb),
('mcq', 7, 2, 'السهم الراجع (تعديل الفرضية) يبيّن أن الطريقة العلمية ليست خطوات في اتجاه واحد؛ فإذا لم تدعم النتائج الفرضية تُعدّل وتُختبر من جديد.', '["وجود السهم الراجع ينفي أن تكون الخطوات في اتجاه واحد فقط.","السهم يعود إلى وضع الفرضيات لا إلى تحديد المشكلة.","","الرجوع إلى وضع الفرضيات يعني مراجعتها، لا تحولها إلى نظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.797Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) جمع المعلومات. (2) إجراء التجارب لاختبار الفرضية. (3) تسجيل النتائج وتنظيمها وتحليلها. (4) النتائج تدعم الفرضية (فتُكرر التجربة للتأكد من الحصول على النتائج نفسها). (5) النتائج لا تدعم الفرضية (فتُعدّل الفرضية). (تُقبل الصياغات المكافئة، مثل: «المشاهدة والبحث عن المعلومات» في (1)، و«تحليل البيانات» في (3)، و«الفرضية مدعومة/ غير مدعومة» في (4) و(5).)', '["(1) جمع المعلومات","(2) إجراء التجارب لاختبار الفرضية","(3) تسجيل النتائج وتحليلها","(4) النتائج تدعم الفرضية","(5) النتائج لا تدعم الفرضية"]'::jsonb, '[]'::jsonb, '[{"element":"(1)","marks":1},{"element":"(2)","marks":1},{"element":"(3)","marks":1},{"element":"(4)","marks":1},{"element":"(5)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الإكمال الصحيح للخمسة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة صحيحة"},{"level":"1–2 درجة","description":"واحد أو اثنان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل الصندوقين (4) و(5)","وضع «الاستنتاج» في (3)","وضع «وضع الفرضيات» في (1)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.797Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطأ الأول: وضع «إجراء التجارب لاختبار الفرضية» قبل «وضع الفرضيات»؛ وهذا خطأ لأن التجارب تُصمَّم لاختبار فرضية موضوعة مسبقًا. التصحيح: وضع الفرضيات في المربع الثالث، ثم إجراء التجارب في المربع الرابع. الخطأ الثاني: تبديل الصندوقين الجانبيين؛ إذ جعل «النتائج لا تدعم الفرضية» يقود إلى «تكرار»، و«النتائج تدعم الفرضية» يقود إلى «تعديل الفرضية»؛ وهذا خطأ لأن الفرضية تُعدّل عندما لا تدعمها النتائج، وتُكرَّر التجربة عندما تدعمها للتأكد من الحصول على النتائج نفسها. التصحيح: «النتائج تدعم الفرضية» ← تكرار، و«النتائج لا تدعم الفرضية» ← تعديل الفرضية.', '["تحديد الخطأ الأول (ترتيب الفرضيات والتجارب)","تعليله وتصحيحه","تحديد الخطأ الثاني (تبديل الصندوقين)","تعليله وتصحيحه"]'::jsonb, '[]'::jsonb, '[{"element":"الخطأ الأول","marks":1},{"element":"تعليله وتصحيحه","marks":1},{"element":"الخطأ الثاني","marks":1},{"element":"تعليله وتصحيحه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين وتعليلهما وتصحيحهما"},{"level":"2–3 درجات","description":"تحديد الخطأين دون تعليل كافٍ، أو خطأ واحد كامل"},{"level":"1 درجة","description":"تحديد خطأ واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ترتيب المربعين الثالث والرابع صحيحًا","الظن أن الفرضية تُعدّل حتى لو دعمتها النتائج","تحديد الخطأ دون كتابة التصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-17T19:43:12.797Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تحديد المشكلة: هل يؤثر وزن الجسم في سرعة سقوطه؟ ← جمع المعلومات: قراءة آراء أرسطو وجاليليو حول السقوط ← وضع الفرضيات: «زمن السقوط لا يعتمد على وزن الجسم» ← إجراء التجارب: إسقاط قطعة نقد منفردة وقطع ملتصقة (2، 3، 4) معًا من الارتفاع نفسه وقياس زمن وصولها ← تسجيل النتائج وتحليلها: تسجيل الأزمنة في جدول ومقارنتها ← الاستنتاج: الأزمنة متساوية تقريبًا. ثم: إذا دعمت النتائج الفرضية ← تكرار التجربة (أو قيام زملاء بإعادتها) للتأكد من الحصول على النتائج نفسها؛ وإذا لم تدعمها ← تعديل الفرضية والعودة إلى خطوة وضع الفرضيات ثم اختبارها من جديد.', '["ترتيب الخطوات الست بأسهم صحيحة","صياغة فرضية قابلة للاختبار","تجربة مناسبة لاختبار الفرضية وتسجيل النتائج","مسار التكرار عند دعم النتائج","مسار تعديل الفرضية عند عدم دعمها"]'::jsonb, '[]'::jsonb, '[{"element":"ترتيب الخطوات","marks":1},{"element":"الفرضية","marks":1},{"element":"التجربة والنتائج","marks":1},{"element":"مسار التكرار","marks":1},{"element":"مسار التعديل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خريطة كاملة مرتبة مع تطبيق صحيح على الموقف والمسارين"},{"level":"3–4 درجات","description":"خريطة مرتبة مع نقص في التطبيق أو أحد المسارين"},{"level":"1–2 درجة","description":"ترتيب الخطوات دون تطبيق على الموقف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["صياغة الفرضية سؤالًا لا عبارة قابلة للاختبار","وضع الاستنتاج قبل تحليل النتائج","إغفال المسارين الراجعين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.797Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
