from (values
('mcq', 1, 'حسب طالب سرعة سيارة عائلية تسير على طريق سريع. أيّ النتائج الآتية منطقية تتوافق مع الخبرة؟', null, null, '["2 km/h","100 km/h","1000 km/h","10000 km/h"]'::jsonb, 'تطبيق', 'تقويم منطقية القيمة', 'سهل', 'الكتاب ص 12 — هل هذا منطقي؟'),
('mcq', 2, 'تسقط كرة نحاسية من السكون من ارتفاع 5 m تقريبًا. ما الزمن المنطقي الذي تحتاج إليه لتصل إلى سطح الأرض؟ (أهمل مقاومة الهواء)', null, null, '["نحو 1 s","نحو 0.002 s","نحو 17 s","نحو 60 s"]'::jsonb, 'تطبيق', 'تقويم منطقية القيمة', 'سهل', 'الكتاب ص 12 — هل هذا منطقي؟'),
('mcq', 3, 'حسب طالب مقاومة مصباح من العلاقة $R = \frac{V}{I}$ فحصل على جواب وحدته volt/ampere. ما تقويم هذه الوحدة؟', null, null, '["خاطئة؛ لأن وحدة المقاومة volt·ampere","صحيحة؛ لأن وحدة المقاومة ampere/volt","لا يمكن تقويمها؛ فالوحدات لا تهم ما دام الرقم صحيحًا","صحيحة؛ لأن volt/ampere تكافئ ohm"]'::jsonb, 'تطبيق', 'تقويم الوحدات', 'سهل', 'الكتاب ص 11 — تقويم الجواب (هل الوحدات صحيحة؟ هل الجواب منطقي؟)'),
('mcq', 4, 'حسب طالب مقاومة مصباح يمر فيه تيار مقداره 0.75 ampere عند فرق جهد 120 volt، فحصل على 90 ohm. ما تقويم جوابه من حيث المنطقية؟', null, null, '["منطقي؛ لأن الناتج أقل من 120 كما هو متوقع","غير منطقي؛ لأن الناتج يجب أن يكون أقل من 1","غير منطقي؛ فقسمة 120 على عدد أقل من 1 تعطي ناتجًا أكبر من 120","منطقي؛ لأن مقاومة المصابيح لا تتجاوز 100 ohm"]'::jsonb, 'تحليل', 'تقويم منطقية الجواب', 'متوسط', 'الكتاب ص 11 — تقويم الجواب (هل الوحدات صحيحة؟ هل الجواب منطقي؟)'),
('mcq', 5, 'دراجة تتحرك من السكون فتصل سرعتها إلى 6 m/s خلال 4 s، والعلاقة $v_f = at$. كتب طالب: $a = (6\ \text{m/s})(4\ \text{s}) = 24\ \text{m/s}^2$. ما تقويم جوابه؟', null, null, '["صحيح؛ لأن الوحدة m/s² وحدة تسارع مناسبة","خاطئ؛ فوحدة الضرب m لا m/s²، والصحيح 1.5 m/s²","خاطئ؛ إذ تجب قسمة الزمن على السرعة، والصحيح 0.67 m/s²","خاطئ؛ إذ يجب جمع السرعة والزمن، والصحيح 10 m/s²"]'::jsonb, 'تطبيق', 'تقويم الوحدات', 'متوسط', 'الكتاب ص 11 — مسائل تدريبية وتقويم الجواب'),
('mcq', 6, 'وزن طالب 627 N، فحسب زميله كتلته من العلاقة $F = mg$ (حيث $g = 9.80\ \text{m/s}^2$) فحصل على $6.14 \times 10^3\ \text{kg}$. ما تقويم الجواب؟', null, null, '["غير منطقي؛ والصحيح 64.0 kg","منطقي؛ لأن الكتلة أكبر دائمًا من الوزن","غير منطقي؛ والصحيح 0.0156 kg","منطقي؛ لأن كتلة الإنسان آلاف الكيلوجرامات"]'::jsonb, 'تطبيق', 'تقويم منطقية الجواب', 'متوسط', 'الكتاب ص 12، 27 — هل هذا منطقي؟ والسؤال 32'),
('mcq', 7, 'رجل وزنه 520 N يقف على الأرض بضغط مقداره 32500 N/m²، والعلاقة $P = \frac{F}{A}$. حسب طالب مساحة نعلي الرجل فحصل على 62.5 m². ما التقويم الصحيح لجوابه؟', null, null, '["منطقي؛ لأن الوحدة m² وحدة مساحة صحيحة","غير منطقي؛ والصحيح $1.69 \\times 10^7$ m²","منطقي؛ لأن الضغط الكبير يحتاج إلى مساحة كبيرة","غير منطقي رغم صحة الوحدة؛ والصحيح 0.016 m²"]'::jsonb, 'تقويم', 'تقويم الوحدات والمنطقية معًا', 'صعب', 'الكتاب ص 11 — المسألة التدريبية 4 وتقويم الجواب'),
('essay', 1, 'وُصل مصباح مقاومته 50.0 ohm بفرق جهد مقداره 9.0 volt، فحسب طالب التيار المار فيه وكتب: 450 ampere. قوّم جوابه من حيث: (أ) الوحدات. (ب) منطقية القيمة. ثم اكتب الجواب الصحيح علمًا بأن $V = IR$.', null, null, null, 'تطبيق', 'تقويم جواب عددي', 'متوسط', 'الكتاب ص 11 — المسألة التدريبية 1 وتقويم الجواب'),
('essay', 2, 'قوّم منطقية كل جواب من الأجوبة الآتية، مع بيان السبب، واقتراح قيمة منطقية تقريبية عند الحاجة: (أ) سرعة طالب يعدو في سباق 300 m/s. (ب) زمن سقوط قطعة نقد من يدك إلى الأرض (ارتفاع نحو 1 m) يساوي 0.4 s. (ج) كتلة كتاب مدرسي 45 kg.', null, null, null, 'تقويم', 'تقويم منطقية أجوبة', 'صعب', 'الكتاب ص 12 — هل هذا منطقي؟'),
('essay', 3, 'تتسارع دراجة نارية من السكون بتسارع مقداره 0.400 m/s² حتى تبلغ سرعتها 4.00 m/s، والعلاقة $v_f = at$. حسب طالب الزمن فكتب: $t = (4.00)(0.400) = 1.60\ \text{s}$. حلّل جوابه بتتبع الوحدات، ثم بيّن هل القيمة منطقية، واحسب الجواب الصحيح.', null, null, null, 'تحليل', 'تحليل جواب بالوحدات', 'صعب', 'الكتاب ص 11 — المسألة التدريبية 3 وتقويم الجواب')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
