from (values
('mcq', 1, 1, 'عدّاد السرعة في السيارة يقرأ عادة حتى 200 km/h تقريبًا، والسير على الطريق السريع يكون بنحو 100 km/h؛ فهي القيمة المنطقية.', '["هذه سرعة أبطأ من مشي الإنسان، وليست منطقية لسيارة على طريق سريع.","","هذه سرعة تقارب سرعة الطائرات، وتتجاوز كثيرًا ما يسجله عدّاد السيارة.","هذه قيمة غير واقعية إطلاقًا لسيارة؛ وتنتج غالبًا عن خطأ في التحويل أو الحساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-17T19:43:12.798Z"}'::jsonb),
('mcq', 2, 0, 'من الخبرة: الجسم الذي يسقط من ارتفاع نحو طابقين يصل إلى الأرض في زمن يقارب ثانية واحدة (الحساب يعطي نحو 1.0 s)؛ أما 0.002 s و17 s فغير منطقيتين.', '["","هذا زمن قصير جدًّا لا تستطيع العين ملاحظة السقوط خلاله، وهو غير منطقي لسقوط من 5 m.","هذا زمن طويل جدًّا؛ فالأجسام لا تستغرق ربع دقيقة لتسقط من ارتفاع طابقين تقريبًا.","دقيقة كاملة لسقوط من 5 m قيمة بعيدة عن الخبرة تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-17T19:43:12.798Z"}'::jsonb),
('mcq', 3, 3, 'بما أن $1\ \text{ohm} = 1\ \text{volt/ampere}$، فإن الوحدة الناتجة هي وحدة المقاومة نفسها، كما هو متوقع.', '["قسمة الجهد على التيار تعطي volt/ampere لا volt·ampere.","ampere/volt مقلوب وحدة المقاومة، فلا تكافئ ohm.","التحقق من الوحدات خطوة أساسية في تقويم الجواب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.798Z"}'::jsonb),
('mcq', 4, 2, '$R = \frac{120}{0.75} = 160\ \text{ohm}$؛ فقسمة 120 على عدد أقل قليلًا من 1 تعطي ناتجًا أكبر قليلًا من 120، وجواب 90 ohm غير منطقي.', '["القسمة على عدد أقل من 1 تكبّر الناتج، فلا يُتوقع أن يكون أقل من 120.","الناتج يكون أقل من 1 لو قُسم عدد صغير على عدد كبير، والعكس هنا.","","لا توجد قاعدة كهذه، والحساب يعطي 160 ohm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.799Z"}'::jsonb),
('mcq', 5, 1, 'بإعادة كتابة العلاقة: $a = \frac{v_f}{t} = \frac{6\ \text{m/s}}{4\ \text{s}} = 1.5\ \text{m/s}^2$. أما ضرب السرعة في الزمن فيعطي وحدة m، وهذا يكشف الخطأ.', '["الطالب كتب الوحدة دون حسابها؛ فحاصل ضرب m/s في s يساوي m.","","هذا ناتج قسمة الزمن على السرعة (4 ÷ 6)، والصحيح $a = \\frac{v_f}{t}$.","هذا ناتج جمع العددين 6 و4، ولا معنى فيزيائيًّا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.799Z"}'::jsonb),
('mcq', 6, 0, 'كتلة الإنسان عشرات الكيلوجرامات، فجواب آلاف الكيلوجرامات غير منطقي (نتج عن ضرب 627 في 9.80). والصحيح: $m = \frac{F}{g} = \frac{627}{9.80} = 64.0\ \text{kg}$.', '["","الكتلة والوزن كميتان مختلفتان، ولا مبرر لهذه القاعدة؛ والجواب ناتج عن الضرب بدل القسمة.","هذا ناتج قسمة 9.80 على 627 (قلب العلاقة)، وهو أيضًا غير منطقي لكتلة إنسان.","كتلة الإنسان عشرات الكيلوجرامات لا آلافها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.799Z"}'::jsonb),
('mcq', 7, 3, '$A = \frac{F}{P} = \frac{520}{32500} = 0.016\ \text{m}^2$. والطالب قسم الضغط على الوزن فحصل على 62.5 m²، وهي مساحة غرفة كبيرة لا نعلين؛ فالجواب غير منطقي رغم أن وحدته صحيحة.', '["صحة الوحدة وحدها لا تكفي؛ فمساحة نعلين لا تكون عشرات الأمتار المربعة.","هذا ناتج ضرب الوزن في الضغط، وهو أبعد عن المنطق؛ والصحيح $A = \\frac{F}{P}$.","الضغط يكبر كلما صغرت المساحة لقوة ثابتة، فالتعليل معكوس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.799Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) وحدة التيار ampere، وهي تنتج من قسمة volt على ohm، فالوحدة المكتوبة مناسبة، لكن الطالب لو ضرب volt في ohm لما حصل على ampere؛ ما يدل على أنه أخطأ في العملية. (ب) القيمة غير منطقية: قسمة 9.0 على 50.0 (عدد أكبر منه) يجب أن تعطي ناتجًا أقل من 1، لا 450 (الذي هو حاصل الضرب). الجواب الصحيح: $I = \frac{V}{R} = \frac{9.0}{50.0} = 0.18\ \text{ampere}$.', '["إعادة كتابة العلاقة $I = \\frac{V}{R}$","تقويم الوحدة: volt/ohm = ampere، وحاصل الضرب لا يعطي ampere","تقويم المنطقية: الناتج يجب أن يكون أقل من 1","الجواب الصحيح 0.18 ampere"]'::jsonb, '["$I = \\frac{V}{R}$","$I = \\frac{9.0\\ \\text{volt}}{50.0\\ \\text{ohm}}$","$I = 0.18\\ \\text{ampere}$"]'::jsonb, '[{"element":"تقويم الوحدات","marks":1},{"element":"تقويم المنطقية","marks":1},{"element":"إعادة كتابة العلاقة","marks":1},{"element":"الجواب الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح للوحدات والمنطقية مع الجواب الصحيح"},{"level":"2–3 درجات","description":"جواب صحيح مع تقويم ناقص، أو تقويم صحيح دون جواب"},{"level":"1 درجة","description":"جواب صحيح دون أي تقويم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول 450 ampere لأن الوحدة مكتوبة صحيحة","كتابة الجواب الصحيح 5.6 ampere (قسمة 50.0 على 9.0)","إغفال التحقق من المنطقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-17T19:43:12.799Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) غير منطقي: 300 m/s تقارب سرعة الصوت، والعدّاء يقطع 100 m في نحو 10 s أو أكثر، فسرعته نحو 10 m/s أو أقل. (ب) منطقي: السقوط من ارتفاع اليد إلى الأرض يستغرق أقل من ثانية بقليل (نحو 0.4–0.5 s)، وهذا يتوافق مع الخبرة. (ج) غير منطقي: الكتاب المدرسي يُحمل بيد واحدة بسهولة، فكتلته نحو 0.5–1 kg، أما 45 kg فتقارب كتلة طالب. (تُقبل أي قيمة مقترحة معللة من الرتبة نفسها.)', '["(أ) غير منطقي مع السبب","قيمة منطقية للعدّاء (نحو 10 m/s)","(ب) منطقي مع السبب","(ج) غير منطقي مع السبب","قيمة منطقية لكتلة الكتاب (نحو 1 kg)"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الحكم والسبب","marks":1},{"element":"(أ) القيمة المقترحة","marks":1},{"element":"(ب) الحكم والسبب","marks":1},{"element":"(ج) الحكم والسبب","marks":1},{"element":"(ج) القيمة المقترحة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح معلل للثلاثة مع اقتراح قيم منطقية"},{"level":"3–4 درجات","description":"تقويم صحيح لاثنين أو ثلاثة مع نقص في التعليل أو القيم"},{"level":"1–2 درجة","description":"تقويم صحيح لواحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على (ب) بأنها غير منطقية لأنها أقل من ثانية","الاكتفاء بالحكم دون مقارنة بالخبرة","اقتراح قيم غير منطقية بديلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-17T19:43:12.800Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بتتبع الوحدات: حاصل ضرب m/s في m/s² يساوي m²/s³، وهي ليست وحدة زمن؛ فالطالب كتب الوحدة s دون أن تنتج من الحساب، وهذا يكشف أنه ضرب بدل أن يقسم. وإعادة كتابة العلاقة الصحيحة: $t = \frac{v_f}{a}$، ووحدتها $\frac{\text{m/s}}{\text{m/s}^2} = \text{s}$. القيمة: $t = \frac{4.00}{0.400} = 10.0\ \text{s}$. ومنطقيًّا: التسارع صغير (تزداد السرعة 0.4 m/s كل ثانية)، فالوصول إلى 4.00 m/s يحتاج إلى نحو عشر ثوانٍ، لا إلى ثانية ونصف.', '["وحدة حاصل الضرب m²/s³ ليست وحدة زمن","إعادة كتابة العلاقة $t = \\frac{v_f}{a}$","الجواب الصحيح 10.0 s","تعليل منطقية القيمة (السرعة تزداد 0.4 m/s كل ثانية)"]'::jsonb, '["$t = \\frac{v_f}{a}$","$t = \\frac{4.00\\ \\text{m/s}}{0.400\\ \\text{m/s}^2}$","$t = 10.0\\ \\text{s}$"]'::jsonb, '[{"element":"تحليل الوحدات","marks":1},{"element":"إعادة كتابة العلاقة","marks":1},{"element":"الجواب الصحيح","marks":1},{"element":"تقويم المنطقية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل وحدات صحيح وجواب صحيح وتعليل للمنطقية"},{"level":"2–3 درجات","description":"جواب صحيح مع تحليل ناقص للوحدات أو المنطقية"},{"level":"1 درجة","description":"جواب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول 1.60 s لأن الوحدة مكتوبة s","كتابة الجواب 0.1 s (قسمة التسارع على السرعة)","إغفال الأرقام المعنوية (كتابة 10 s بدل 10.0 s)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-17T19:43:12.800Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O21') and x.type = v.type and x.number = v.number
