from (values
('mcq', 1, 'أيّ العبارات الآتية تقارن بين القانون العلمي والنظرية العلمية مقارنة صحيحة؟', null, null, '["القانون أعلى مرتبة من النظرية","النظرية قانون لم يُثبت بعد","القانون يفسر والنظرية تصف","النظرية قد تكون تفسيرًا للقوانين"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('mcq', 2, 'ما الفرق الرئيس بين الفرضية والنظرية العلمية؟', null, null, '["الفرضية تخمين يحتاج إلى اختبار، والنظرية تفسير تدعمه التجارب بقوة","الفرضية تفسير تدعمه التجارب، والنظرية تخمين يحتاج إلى اختبار","الفرضية تصف ظاهرة متكررة، والنظرية تصف ظاهرة نادرة","لا فرق بينهما؛ فكلاهما رأي شخصي للعالم"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('mcq', 3, 'قال طالب: «عندما تُثبت النظرية العلمية بالتجارب تتحول إلى قانون علمي». ما التقويم الصحيح لقوله؟', null, null, '["صحيح؛ لأن القانون نظرية ثبتت صحتها نهائيًّا","خاطئ؛ فالقانون يصف والنظرية تفسر","خاطئ؛ لأن النظرية لا تُدعم بالتجارب أبدًا","صحيح؛ لأن القوانين لا تحتاج إلى مشاهدات"]'::jsonb, 'تحليل', 'تقويم تصور خاطئ', 'متوسط', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('mcq', 4, 'صنّف العبارتين: (1) «زاوية سقوط الشعاع الضوئي على السطح العاكس تساوي زاوية انعكاسه». (2) «جميع الكتل في الكون تنجذب إلى كتل أخرى ويجذب بعضها بعضًا».', null, null, '["الأولى نظرية علمية، والثانية قانون علمي","كلتاهما قانون علمي","الأولى قانون علمي، والثانية نظرية علمية","الأولى فرضية، والثانية نظرية علمية"]'::jsonb, 'تحليل', 'تصنيف مقارن', 'متوسط', 'الكتاب ص 14 — أمثلة على القانون والنظرية'),
('mcq', 5, 'يقارن الجدول الآتي بين القانون العلمي والنظرية العلمية. في أيّ صف جاءت المقارنة صحيحة؟', '{"headers":["الصف","وجه المقارنة","القانون العلمي","النظرية العلمية"],"rows":[["1","الوظيفة","يفسر سبب الظاهرة","تصف الظاهرة"],["2","الصورة الغالبة","معادلة رياضية تربط متغيرات","إطار يجمع عناصر البناء العلمي"],["3","مثال","الجاذبية الكونية","حفظ الشحنة"],["4","المراجعة مع الزمن","لا يُراجع أبدًا","لا تُراجع أبدًا"]]}'::jsonb, null, '["الصف 2","الصف 1","الصف 3","الصف 4"]'::jsonb, 'تحليل', 'تحليل جدول مقارنة', 'صعب', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('mcq', 6, 'توقّع طالب قبل التجربة أن زمن سقوط قطعة النقد يعتمد على كتلتها، أما نيوتن ففسّر سقوط الأجسام بقوة تجاذب بين الأرض والأجسام وقد دعمت التجارب تفسيره بقوة. ما التصنيف الصحيح؟', null, null, '["توقع الطالب نظرية، وتفسير نيوتن فرضية","كلاهما فرضية لأنهما يتعلقان بالسقوط","توقع الطالب قانون، وتفسير نيوتن نظرية","توقع الطالب فرضية، وتفسير نيوتن نظرية"]'::jsonb, 'تحليل', 'تصنيف مقارن', 'متوسط', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('mcq', 7, 'أيّ الزوجين الآتيين يعبّر عن السؤال الذي يجيب عنه كلٌّ من القانون العلمي والنظرية العلمية؟', null, null, '["القانون: لماذا يحدث؟ والنظرية: ماذا يحدث؟","القانون: ماذا يحدث؟ والنظرية: لماذا يحدث؟","كلاهما يجيب عن: لماذا يحدث؟","كلاهما يجيب عن: ماذا يحدث فقط؟"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('essay', 1, 'ما الفرق بين النظرية العلمية والقانون العلمي؟ وما الفرق بين الفرضية والنظرية العلمية؟ أعطِ مثالًا مناسبًا لكل من القانون والنظرية والفرضية.', null, null, null, 'تحليل', 'مقارنة مع أمثلة', 'متوسط', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('essay', 2, 'صمّم جدولًا تقارن فيه بين الفرضية والقانون العلمي والنظرية العلمية من حيث: (أ) المقصود بكل منها. (ب) علاقتها بالتجارب والمشاهدات. (ج) وظيفتها (تخمين/ وصف/ تفسير). (د) مثال.', null, null, null, 'تحليل', 'مقارنة متعددة الأوجه', 'صعب', 'الكتاب ص 12، 14، 26 — القانون والنظرية والفرضية (السؤال 28)'),
('essay', 3, 'في دراسة سقوط الأجسام ظهرت ثلاث عبارات: (1) «ربما تسقط قطعة النقد الأثقل أسرع من الأخف» (قالها طالب قبل التجربة). (2) «سرعة سقوط الجسم تعتمد على زمن سقوطه لا على كتلته» (وصف تؤكده مشاهدات متكررة). (3) «تسقط الأجسام بسبب قوة تجاذب بين الأرض وبينها» (تفسير تدعمه التجارب بقوة). صنّف كل عبارة إلى فرضية أو قانون أو نظرية، وقارن بين العبارتين (2) و(3)، ثم بين (1) و(3).', null, null, null, 'تحليل', 'تصنيف ومقارنة', 'صعب', 'الكتاب ص 9، 12، 14 — الفرضية والقانون والنظرية في سقوط الأجسام')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
