from (values
('mcq', 1, 3, 'القانون يصف الظاهرة ولا يفسر سببها، والنظرية إطار تفسيري قد يكون تفسيرًا للقوانين.', '["ليس أحدهما أعلى مرتبة؛ فلكل منهما وظيفة: القانون يصف والنظرية تفسر.","النظرية تفسير تدعمه التجارب بقوة، وليست قانونًا ناقص الإثبات.","العكس هو الصحيح: القانون يصف الظاهرة والنظرية تفسرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.800Z"}'::jsonb),
('mcq', 2, 0, 'الفرضية تخمين علمي عن كيفية ارتباط المتغيرات يحتاج إلى اختبار، أما النظرية فإطار تفسيري لا يطلق إلا على التفسير الذي تدعمه بقوة نتائج التجارب.', '["","المقارنة معكوسة: الفرضية هي التخمين، والنظرية هي المدعومة بالتجارب.","وصف الظاهرة المتكررة من شأن القانون، والنظرية تفسر لا تصف.","كلاهما ليس رأيًا شخصيًّا: الفرضية تخمين علمي قابل للاختبار، والنظرية مدعومة تجريبيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('mcq', 3, 1, 'القانون يصف ما يحدث، والنظرية تفسر لماذا يحدث، ولا يتحول أحدهما إلى الآخر بزيادة الدعم التجريبي.', '["القانون ليس نظرية مُثبتة؛ فالنظرية تبقى تفسيرًا مهما بلغ دعمها التجريبي.","","الحكم صحيح لكن التعليل خاطئ؛ فالنظرية لا تُسمّى نظرية إلا إذا دعمتها التجارب بقوة.","القوانين مبنية على مشاهدات مترابطة متكررة، فالتعليل خاطئ والحكم خاطئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('mcq', 4, 2, 'العبارة الأولى قانون الانعكاس (تصف ظاهرة متكررة)، والثانية نظرية الجاذبية الكونية.', '["التصنيف معكوس: الأولى قانون الانعكاس، والثانية نظرية الجاذبية الكونية.","الثانية نص نظرية الجاذبية الكونية لا قانون.","","الأولى ليست تخمينًا، بل قانون مبني على مشاهدات متكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('mcq', 5, 0, 'في الصف 2: القانون يُعبَّر عنه غالبًا بمعادلة رياضية تصف العلاقة بين متغيرين أو أكثر، والنظرية إطار يجمع عناصر البناء العلمي؛ وهذه مقارنة صحيحة.', '["","المقارنة في الصف 1 معكوسة: القانون يصف الظاهرة، والنظرية تفسرها.","المثالان في الصف 3 معكوسان: حفظ الشحنة قانون، والجاذبية الكونية نظرية.","الصف 4 خاطئ؛ فالقوانين والنظريات قد تُراجع أو تُهمل مع الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('mcq', 6, 3, 'التوقع تخمين علمي عن ارتباط متغيرين (الزمن والكتلة) قبل الاختبار فهو فرضية، وتفسير نيوتن تفسير تدعمه التجارب بقوة فهو نظرية.', '["التصنيف معكوس: التوقع غير المختبر فرضية، والتفسير المدعوم بقوة نظرية.","تفسير نيوتن مدعوم بقوة بالتجارب، فهو نظرية لا فرضية.","التوقع لم يُختبر ولم تُجمع له مشاهدات مترابطة، فلا يكون قانونًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('mcq', 7, 1, 'القانون يقدم وصفًا لما يحدث في ظاهرة متكررة، والنظرية تفسر سبب حدوثها.', '["الزوج معكوس؛ فالقانون يصف ولا يفسر السبب.","","القانون لا يفسر سبب حدوث الظاهرة.","النظرية تتجاوز الوصف إلى تفسير المشاهدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-17T19:43:12.801Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القانون العلمي قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة، ويُعبّر عنه غالبًا بمعادلة رياضية، وهو يصف ولا يفسر؛ مثاله: قانون الانعكاس. أما النظرية العلمية فإطار يجمع عناصر البناء العلمي ويفسر المشاهدات المدعومة بنتائج تجريبية، وقد تكون تفسيرًا للقوانين؛ مثالها: نظرية الجاذبية الكونية. والفرضية تخمين علمي عن كيفية ارتباط المتغيرات لم يُختبر بعد؛ مثالها: «ربما يعتمد زمن سقوط الجسم على وزنه». أما النظرية فلا يُطلق اسمها إلا على تفسير تدعمه بقوة نتائج التجارب.', '["القانون يصف والنظرية تفسر","مثال صحيح على القانون","مثال صحيح على النظرية","الفرضية تخمين غير مختبر والنظرية مدعومة بقوة بالتجارب","مثال صحيح على الفرضية"]'::jsonb, '[]'::jsonb, '[{"element":"فرق القانون والنظرية","marks":1},{"element":"مثال القانون","marks":1},{"element":"مثال النظرية","marks":1},{"element":"فرق الفرضية والنظرية","marks":1},{"element":"مثال الفرضية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الفرقان صحيحان مع الأمثلة الثلاثة"},{"level":"3–4 درجات","description":"الفرقان مع نقص في الأمثلة، أو فرق واحد مع أمثلته"},{"level":"1–2 درجة","description":"فرق واحد دون أمثلة أو أمثلة دون فروق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النظرية تصبح قانونًا عند إثباتها","عدّ نظرية الجاذبية الكونية قانونًا","وصف الفرضية بأنها رأي شخصي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-17T19:43:12.802Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الفرضية: (أ) تخمين علمي عن كيفية ارتباط المتغيرات بعضها مع بعض. (ب) تسبق التجربة، وتُصمم التجارب لاختبارها. (ج) تخمين يقترح علاقة. (د) «طول النابض يزداد بزيادة الكتلة المعلقة». القانون: (أ) قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة. (ب) مبني على مشاهدات مترابطة متكررة. (ج) يصف الظاهرة ولا يفسر سببها، وغالبًا بمعادلة رياضية. (د) قانون حفظ الشحنة. النظرية: (أ) إطار يجمع عناصر البناء العلمي في موضوع ما. (ب) تفسر المشاهدات المدعومة بنتائج تجريبية، ولا تُسمّى نظرية إلا إذا دعمتها التجارب بقوة. (ج) تفسر سبب الظاهرة وقد تفسر القوانين. (د) نظرية الجاذبية الكونية.', '["المقصود بالثلاثة","العلاقة بالتجارب والمشاهدات للثلاثة","الوظيفة للثلاثة","مثال صحيح لكل منها"]'::jsonb, '[]'::jsonb, '[{"element":"المقصود","marks":1},{"element":"العلاقة بالتجارب","marks":1},{"element":"الوظيفة","marks":1},{"element":"الأمثلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جدول مكتمل صحيح في الأوجه الأربعة"},{"level":"2–3 درجات","description":"جدول صحيح في وجهين أو ثلاثة"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل وظيفة القانون التفسير","جعل الفرضية لاحقة للتجربة","تكرار المثال نفسه للقانون والنظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.802Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة (1) فرضية: تخمين عن ارتباط متغيرين (سرعة السقوط والكتلة) لم يُختبر بعد. العبارة (2) قانون (وصف): تجمع مشاهدات مترابطة لظاهرة متكررة وتصف العلاقة بين السرعة والزمن دون تفسير السبب. العبارة (3) نظرية: تفسير لسبب السقوط تدعمه التجارب بقوة. المقارنة بين (2) و(3): الأولى تصف كيف يسقط الجسم، والثانية تفسر لماذا يسقط، وقد تكون النظرية تفسيرًا لما يصفه القانون. المقارنة بين (1) و(3): كلتاهما تتعلق بالسقوط، لكن (1) تخمين ينتظر الاختبار، وقد تبيّن بالتجربة أنه غير صحيح، بينما (3) تفسير مدعوم بقوة بنتائج التجارب.', '["(1) فرضية","(2) قانون","(3) نظرية","مقارنة (2) و(3): وصف مقابل تفسير","مقارنة (1) و(3): تخمين غير مختبر مقابل تفسير مدعوم"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (1)","marks":1},{"element":"تصنيف (2)","marks":1},{"element":"تصنيف (3)","marks":1},{"element":"مقارنة (2) و(3)","marks":1},{"element":"مقارنة (1) و(3)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للثلاث مع مقارنتين صحيحتين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع مقارنة واحدة أو مقارنتين ناقصتين"},{"level":"1–2 درجة","description":"تصنيف صحيح لعبارة أو عبارتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف العبارة (2) نظرية لأنها لعالم مشهور","تصنيف العبارة (1) قانونًا","المقارنة دون ذكر معيار الوصف والتفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-17T19:43:12.802Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
