select (select id from public.objectives where code = 'P1-C1-L1-O23'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا تُغيَّر النظريات العلمية أو تُعدَّل؟', null, null, '["لأن العلماء يفضّلون تغيير النظريات دوريًّا كل مدة زمنية محددة","لأن النظريات تُبنى أصلًا على الآراء الشخصية لأصحابها","لتعكس المكتشفات الجديدة عندما تتولد معلومات جديدة من تجارب لاحقة","لأن كل نظرية تتحول تلقائيًّا إلى قانون مع مرور الزمن"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 13 — مراجعة النماذج والنظريات'),
('mcq', 2, 'كان الاعتقاد السائد في القرن التاسع عشر أن العلامات الخطية التي تُرى على سطح المريخ قنوات، ثم أثبت العلماء بعد تطور المناظير الفلكية أنه لا توجد مثل هذه العلامات. ما الذي يوضحه هذا المثال؟', null, null, '["البيانات الجديدة من أدوات أدق قد تنقض اعتقادًا سابقًا فيُراجع","المناظير الحديثة أقل دقة من المناظير القديمة","الاعتقادات العلمية القديمة لا تُراجع مهما ظهرت بيانات","الصور الحديثة أثبتت وجود قنوات أكثر عددًا"]'::jsonb, 'فهم', 'تفسير مثال تاريخي', 'متوسط', 'الكتاب ص 13 — مراجعة النماذج والنظريات'),
('mcq', 3, 'إذا لم تؤكد البيانات الجديدة صحة نموذج علمي معتمد، فما الذي يجب فعله؟', null, null, '["إلغاء النموذج فورًا دون أي فحص","إعادة اختبار النموذج والبيانات كليهما","تجاهل البيانات الجديدة لأن النموذج معتمد","تحويل النموذج إلى قانون علمي"]'::jsonb, 'تذكر', 'تذكر إجراء', 'سهل', 'الكتاب ص 13 — مراجعة النماذج والنظريات'),
('mcq', 4, 'عندما تُثار تساؤلات حول نموذج علمي معتمد، ما أول ما يقوم به الفيزيائيون؟', null, null, '["يستبدلون بالنموذج نموذجًا جديدًا مباشرة دون فحص التساؤلات","يرفضون التساؤلات لأن النموذج اعتُمد سابقًا من العلماء","يعلنون أن النموذج صحيح دائمًا ولا يحتاج إلى أي فحص","يتفحصون التساؤلات بعناية للتأكد من صحتها قبل أي تغيير"]'::jsonb, 'فهم', 'توضيح إجراء', 'متوسط', 'الكتاب ص 13 — مراجعة النماذج والنظريات'),
('mcq', 5, 'لماذا تعاقب ظهور نماذج متعددة للذرة عبر الزمن؟', null, null, '["لأن كل عالم يضع نموذجًا جديدًا دون الحاجة إلى دليل","لأن الذرة نفسها تغيّر تركيبها عبر الزمن","بهدف تفسير المشاهدات والقياسات الحديثة","لأن النماذج القديمة لم تعتمد على أي تجارب"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 13 — النماذج العلمية'),
('mcq', 6, 'لماذا راجع جاليليو رأي الفلاسفة الإغريق في سقوط الأجسام؟', null, null, '["لأن ملاحظاته بيّنت أن سرعة السقوط لا تعتمد على الكتلة","لأن رأي الإغريق لم يكن مكتوبًا في صورة معادلات رياضية","لأنه أراد إرجاع سبب السقوط إلى تحدّب الفضاء (الزمكان)","لأن نيوتن طلب منه تعديل رأي الإغريق في السقوط"]'::jsonb, 'فهم', 'تفسير مراجعة', 'متوسط', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('mcq', 7, 'حصل طالب في تجربة واحدة على نتيجة تتعارض مع نظرية علمية مدعومة بتجارب كثيرة. ما الإجراء العلمي المناسب؟', null, null, '["إلغاء النظرية فورًا لأن نتيجة واحدة خالفتها","تجاهل النتيجة نهائيًّا لأن النظرية ثبتت إلى الأبد","تحويل النظرية إلى فرضية تنتظر الاختبار","إعادة التجربة للتأكد من تكرار النتيجة قبل أي تعديل"]'::jsonb, 'تحليل', 'اتخاذ قرار في موقف', 'صعب', 'الكتاب ص 12، 13 — قابلية التكرار ومراجعة النظريات'),
('essay', 1, 'فسّر لماذا تُراجَع النظريات العلمية أو تُعدَّل، مستشهدًا بمثال المريخ.', null, null, null, 'فهم', 'تفسير مع مثال', 'متوسط', 'الكتاب ص 13 — مراجعة النماذج والنظريات'),
('essay', 2, 'مرّ تفسير سقوط الأجسام بأربع مراحل: الإغريق، ثم جاليليو، ثم نيوتن، ثم أينشتاين. فسّر سبب كل مراجعة من المراجعات الثلاث.', null, null, null, 'تحليل', 'تفسير تطور تاريخي', 'صعب', 'الكتاب ص 14 — تطور نظرية سقوط الأجسام'),
('essay', 3, 'قال أحد الأشخاص: «ما دامت النظريات العلمية تُراجع وتُعدّل، فالعلم غير موثوق». قوّم هذا القول.', null, null, null, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 13، 14، 28 — مراجعة النظريات (السؤال 43)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O23') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'إذا تولدت معلومات جديدة عن تجارب لاحقة فيجب تغيير النظريات لتعكس المكتشفات الجديدة.', '["التغيير لا يكون دوريًّا ولا بقرار مسبق، بل استجابة لمعلومات جديدة.","النظريات مدعومة بنتائج تجريبية، لا بالآراء الشخصية.","","النظرية لا تتحول إلى قانون، والتعديل سببه بيانات جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 2, 0, 'تطور المناظير الفلكية وفّر مشاهدات جديدة أدق أظهرت عدم وجود القنوات؛ فرُوجع الاعتقاد السابق ليتفق مع البيانات الجديدة.', '["","العكس هو الصحيح؛ فتطور المناظير هو الذي كشف خطأ الاعتقاد.","المثال نفسه يبيّن أن الاعتقاد القديم روجع وتُرك.","الصور الحديثة أظهرت عدم وجود هذه القنوات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 3, 1, 'إذا لم تؤكد البيانات الجديدة صحة النموذج وجب إعادة اختبار كليهما: النموذج والبيانات.', '["لا يُلغى النموذج فورًا؛ فقد تكون البيانات الجديدة نفسها خاطئة.","","النموذج المعتمد ليس فوق المراجعة، ولا تُتجاهل البيانات.","عدم تأكيد البيانات للنموذج لا يحوّله إلى قانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 4, 3, 'يقوم الفيزيائيون أولًا بتفحص التساؤلات بعناية للتأكد من صحتها: هل يستطيع أي شخص الحصول على النتائج نفسها؟ هل هناك متغيرات أخرى؟', '["الاستبدال المباشر يتجاهل احتمال خطأ التساؤلات؛ فالفحص يسبق التغيير.","اعتماد النموذج سابقًا لا يمنع مراجعته عند ظهور تساؤلات.","النماذج العلمية قابلة للمراجعة، ولا توصف بالصحة الدائمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 5, 2, 'تعاقب ظهور نماذج ذرية جديدة بهدف تفسير المشاهدات والقياسات الحديثة.', '["النماذج الجديدة ظهرت لتفسير مشاهدات وقياسات جديدة، لا دون دليل.","تركيب الذرة لم يتغير؛ الذي تغير هو المشاهدات والقياسات المتاحة.","","النماذج تعتمد على التجريب؛ والتغيير سببه قياسات أحدث لم تفسرها القديمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 6, 0, 'تتغير النظريات وتُعدّل عندما توفر التجارب الجديدة ملاحظات جديدة؛ وقد وضح جاليليو أن سرعة سقوط الأجسام تعتمد على زمن سقوطها لا على كتلتها، فخالف رأي الإغريق.', '["","سبب المراجعة تعارض الرأي مع الملاحظات لا طريقة كتابته.","فكرة تحدّب الزمكان افترضها أينشتاين لاحقًا، لا جاليليو.","نيوتن جاء بعد جاليليو وبنى على رأيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.803Z"}'::jsonb),
('mcq', 7, 3, 'يجب أن تكون التجارب والنتائج قابلة للتكرار؛ فتُفحص النتيجة الجديدة ويُعاد إجراء التجربة، فإن تكررت المعلومات الجديدة وجب تعديل النظرية لتعكسها.', '["نتيجة واحدة لم تتكرر قد تكون ناتجة عن خطأ؛ فالنتائج يجب أن تكون قابلة للتكرار.","النظريات قابلة للمراجعة، فلا تُتجاهل النتيجة بل تُفحص.","النظرية المدعومة بتجارب كثيرة لا تعود فرضية بسبب نتيجة واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-17T19:43:12.804Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُراجع النظريات والنماذج العلمية لأنها تفسر المشاهدات المتاحة في زمنها؛ فإذا تولدت معلومات جديدة عن تجارب أو مشاهدات لاحقة (غالبًا بأدوات أدق) ولم تتفق مع النظرية، وجب تغييرها لتعكس المكتشفات الجديدة بعد التأكد من صحة البيانات. مثال المريخ: كان الاعتقاد السائد في القرن التاسع عشر أن العلامات الخطية على سطح المريخ قنوات، وبعد تطور المناظير الفلكية أثبت العلماء أنه لا توجد مثل هذه العلامات، فتُرك ذلك الاعتقاد. وفي الوقت الحالي وجد العلماء بأجهزة أفضل دلائل على أن الماء كان موجودًا على سطح المريخ في الماضي، وكل اكتشاف جديد يفتح تساؤلات جديدة.', '["سبب المراجعة: معلومات جديدة من تجارب أو مشاهدات لاحقة","التعديل ليعكس المكتشفات الجديدة","وصف الاعتقاد القديم عن قنوات المريخ","دور تطور المناظير في نقضه"]'::jsonb, '[]'::jsonb, '[{"element":"السبب","marks":1},{"element":"الهدف من التعديل","marks":1},{"element":"الاعتقاد القديم","marks":1},{"element":"دور الأدوات الحديثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح مع مثال مكتمل"},{"level":"2–3 درجات","description":"تفسير صحيح مع مثال ناقص، أو مثال دون تفسير كافٍ"},{"level":"1 درجة","description":"ذكر المثال أو السبب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النظريات تتغير لأنها آراء","الادعاء أن الصور الحديثة أكدت وجود القنوات","إغفال دور البيانات الجديدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-17T19:43:12.804Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المراجعة الأولى (من الإغريق إلى جاليليو): رأى الإغريق أن الأجسام الأكبر كتلة تسقط أسرع، لكن الملاحظات والتجارب أظهرت أن الأجسام المختلفة الكتلة تسقط معًا تقريبًا، فوضح جاليليو أن سرعة السقوط تعتمد على زمن السقوط لا على الكتلة. المراجعة الثانية (نيوتن): رأي جاليليو وصف كيف تسقط الأجسام دون أن يفسر السبب، فأرجع نيوتن سبب السقوط إلى قوة تجاذب بين الأرض والأجسام. المراجعة الثالثة (أينشتاين): لتفسير قوة التجاذب نفسها افترض أينشتاين أنها ناتجة عن الكتلة التي تؤدي إلى تحدّب الفضاء (الزمكان) حولها، مع بقاء مقترحات جاليليو ونيوتن صحيحة. فالنظرية تتغير وتُعدّل عندما توفر التجارب الجديدة ملاحظات جديدة.', '["سبب المراجعة الأولى: الملاحظات خالفت ربط السرعة بالكتلة","سبب المراجعة الثانية: الحاجة إلى تفسير سبب السقوط","سبب المراجعة الثالثة: تفسير أعمق لقوة التجاذب","المراجعة لا تعني إلغاء ما ثبت صحته (أفكار جاليليو ونيوتن ما زالت صحيحة)"]'::jsonb, '[]'::jsonb, '[{"element":"المراجعة الأولى","marks":1},{"element":"المراجعة الثانية","marks":1},{"element":"المراجعة الثالثة","marks":1},{"element":"استنتاج عام","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للمراجعات الثلاث مع استنتاج عام"},{"level":"2–3 درجات","description":"تفسير مراجعتين أو ثلاث دون استنتاج"},{"level":"1 درجة","description":"تفسير مراجعة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أينشتاين ألغى أفكار نيوتن","نسبة فكرة التجاذب إلى جاليليو","سرد المراحل دون تفسير سبب المراجعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.804Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. فمراجعة النظريات دليل على قوة المنهج العلمي لا ضعفه؛ لأن العلم يبني نظرياته على مشاهدات ونتائج تجريبية قابلة للتكرار، فإذا ظهرت بيانات جديدة لا تتفق مع نموذج أو نظرية، يُعاد اختبار النموذج والبيانات كليهما، ثم تُعدّل النظرية لتعكس المكتشفات الجديدة. وهذا يجعل المعرفة العلمية تتحسن باستمرار وتقترب أكثر من تفسير الطبيعة. كما أن التعديل لا يعني إلغاء كل ما سبق؛ فمقترحات جاليليو ونيوتن في سقوط الأجسام ما زالت صحيحة رغم إضافة أينشتاين. وكل اكتشاف جديد يفتح مجالات جديدة للاستكشاف.', '["الحكم: القول غير صحيح","المراجعة مبنية على أدلة تجريبية جديدة قابلة للتكرار","المراجعة تحسّن المعرفة وتقربها من تفسير الطبيعة","التعديل لا يلغي ما ثبت (مثال)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"أساس المراجعة","marks":1},{"element":"أثرها في تحسين المعرفة","marks":1},{"element":"مثال داعم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل متكامل ومثال"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو دون مثال"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد القول أو لا إجابة"}]'::jsonb, '["تأييد القول","القول إن العلم لا يتغير أبدًا","إغفال دور الأدلة التجريبية في المراجعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-17T19:43:12.804Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C1-L1-O23') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
