from (values
('mcq', 1, 'ما المقصود بخط المواءمة الأفضل في الرسم البياني؟', null, null, '["خط منكسر يصل كل نقطة بالنقطة التي تليها","خط يمر بالنقطتين الأولى والأخيرة فقط","أفضل خط بياني يمر بالنقاط كلها تقريبًا","خط أفقي يمر بأعلى نقطة في الرسم"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 10 — الرسوم البيانية وخط المواءمة الأفضل'),
('mcq', 2, 'تمثل اللوحات الأربع الآتية نقاط البيانات نفسها، وفي كل لوحة خط مختلف. أيّ لوحة تُظهر خط المواءمة الأفضل؟', null, '[{"src":"qimg/phys1/c1l1-fit-panels.svg","alt":"أربع لوحات بيانية مرقمة (1) إلى (4)، في كل منها المحور الأفقي x من 0 إلى 7 والمحور الرأسي y من 0 إلى 20 بتدريج 4، وفي كل لوحة النقاط الست نفسها: (1، 2.6)، (2، 5.6)، (3، 6.6)، (4، 9.6)، (5، 10.6)، (6، 13.4). اللوحة (1): خط منكسر يصل النقاط بالترتيب. اللوحة (2): خط مستقيم من (0، 0.87) تقريبًا إلى (6.6، 14.4) تقريبًا تتوزع النقاط فوقه وتحته بفروق صغيرة. اللوحة (3): خط مستقيم يبدأ من نقطة الأصل ويمر بالنقطتين الأوليين ثم يرتفع فوق بقية النقاط. اللوحة (4): خط مستقيم يمر بالنقطتين الأخيرتين (5، 10.6) و(6، 13.4) وتقع النقاط الأخرى فوقه."}]'::jsonb, '["اللوحة (1)","اللوحة (2)","اللوحة (3)","اللوحة (4)"]'::jsonb, 'فهم', 'تمييز خط المواءمة', 'سهل', 'الكتاب ص 10 — الرسوم البيانية وخط المواءمة الأفضل'),
('mcq', 3, 'يمثل المنحنى الآتي المسافة التي تقطعها كتلة في 5 s بدلالة القوة المؤثرة فيها، مع خط المواءمة الأفضل. ما ميل خط المواءمة الأفضل؟', null, '[{"src":"qimg/phys1/c1l1-fit-slope.svg","alt":"منحنى بياني: المحور الأفقي «القوة (N)» من 0 إلى 30 بتدريج 5، والمحور الرأسي «المسافة (cm)» من 0 إلى 160 بتدريج 20. نقاط البيانات: (5، 26)، (10، 49)، (15، 76)، (20، 99)، (25، 126)، (30، 150). خط المواءمة الأفضل خط مستقيم يبدأ من نقطة الأصل (0، 0) ويمر بالنقطة (30، 150)."}]'::jsonb, '["5.0 cm/N","5.2 cm/N","0.20 N/cm","150 cm/N"]'::jsonb, 'تطبيق', 'حساب الميل من الرسم', 'متوسط', 'الكتاب ص 12، 28 — تجربة قياس التغير والسؤال 39'),
('mcq', 4, 'يمثل المنحنى الآتي طول نابض بدلالة الكتلة المعلّقة به، مع خط المواءمة الأفضل. أيّ المعادلات الآتية تربط طول النابض $L$ (cm) بالكتلة $m$ (g)؟', null, '[{"src":"qimg/phys1/c1l1-fit-spring.svg","alt":"منحنى بياني: المحور الأفقي «الكتلة المعلّقة (g)» من 0 إلى 250 بتدريج 50، والمحور الرأسي «طول النابض (cm)» من 0 إلى 28 بتدريج 4. نقاط البيانات: (50، 14.6)، (100، 17.0)، (150، 19.4)، (200، 22.1)، (250، 24.4). خط المواءمة الأفضل خط مستقيم يقطع المحور الرأسي عند 12.0 ويمر بالنقطة (250، 24.5)."}]'::jsonb, '["$L = 0.050m$","$L = 20m + 12.0$","$L = 12.0m + 0.050$","$L = 0.050m + 12.0$"]'::jsonb, 'تطبيق', 'كتابة معادلة من الرسم', 'متوسط', 'الكتاب ص 12، 28 — تجربة قياس التغير والسؤال 39'),
('mcq', 5, 'يمثل المنحنى الآتي كتلة عينات من مادة بدلالة حجمها، مع خط المواءمة الأفضل. باستخدام الخط، ما حجم عينة من المادة نفسها كتلتها 280 g؟', null, '[{"src":"qimg/phys1/c1l1-fit-volume.svg","alt":"منحنى بياني: المحور الأفقي «الحجم (cm³)» من 0 إلى 50 بتدريج 10، والمحور الرأسي «الكتلة (g)» من 0 إلى 400 بتدريج 40. نقاط البيانات: (10، 78)، (20، 162)، (30، 238)، (40، 322)، (50، 398). خط المواءمة الأفضل خط مستقيم يبدأ من نقطة الأصل ويمر بالنقطة (50، 400)."}]'::jsonb, '["2240 cm³","0.029 cm³","35 cm³","30 cm³"]'::jsonb, 'تطبيق', 'التوقع من خط المواءمة', 'متوسط', 'الكتاب ص 27 — السؤال 38 وخط المواءمة'),
('mcq', 6, 'علّق طالب حلقات معدنية متماثلة بنابض وقاس طوله، فحصل على بيانات الجدول الآتي. باستخدام خط المواءمة الأفضل لهذه البيانات، ما الطول المتوقع للنابض عند تعليق 5 حلقات؟', '{"headers":["عدد الحلقات","طول النابض (cm)"],"rows":[["0","10.0"],["1","12.1"],["2","13.9"],["3","16.0"]]}'::jsonb, null, '["10.0 cm","20.0 cm","18.0 cm","26.7 cm"]'::jsonb, 'تطبيق', 'التوقع بقيم جديدة', 'صعب', 'الكتاب ص 12 — تجربة قياس التغير'),
('mcq', 7, 'رُسم منحنى طول نابض (cm) على المحور الرأسي بدلالة الكتلة المعلّقة به (g) على المحور الأفقي. ما وحدة ميل خط المواءمة الأفضل؟', null, null, '["g/cm","cm·g","cm","cm/g"]'::jsonb, 'فهم', 'تحديد وحدة الميل', 'سهل', 'الكتاب ص 10، 28 — خط المواءمة والسؤال 39d'),
('essay', 1, 'علّق طالب أثقالًا مختلفة بشريط مطاطي وقاس استطالته، فحصل على بيانات الجدول الآتي. (أ) صف كيف تمثل البيانات بيانيًّا وترسم خط المواءمة الأفضل. (ب) احسب ميل الخط واكتب معادلة تربط الاستطالة $x$ بالقوة $F$. (ج) ما الثابت في المعادلة وما وحدته؟ (د) توقع الاستطالة عند قوة مقدارها 7.0 N.', '{"headers":["القوة (N)","الاستطالة (cm)"],"rows":[["1.0","2.1"],["2.0","3.9"],["3.0","6.0"],["4.0","8.1"],["5.0","9.9"]]}'::jsonb, null, null, 'تطبيق', 'تمثيل بياني وكتابة معادلة وتوقع', 'متوسط', 'الكتاب ص 12، 28 — تجربة قياس التغير والسؤال 39'),
('essay', 2, 'يمثل المنحنى الآتي درجة حرارة ماء يُسخَّن بدلالة الزمن، مع خط المواءمة الأفضل. (أ) استخدم الخط لكتابة معادلة تربط درجة الحرارة $T$ ($\text{°C}$) بالزمن $t$ (min). (ب) توقع درجة حرارة الماء بعد 8.0 min. (ج) هل تتوقع أن يبقى هذا التوقع صحيحًا لو مددت الخط إلى 30 min؟ علّل.', null, '[{"src":"qimg/phys1/c1l1-fit-temp.svg","alt":"منحنى بياني: المحور الأفقي «الزمن (min)» من 0 إلى 6 بتدريج 1، والمحور الرأسي «درجة الحرارة (°C)» من 0 إلى 50 بتدريج 5. نقاط البيانات: (0، 20.0)، (1، 24.2)، (2، 27.8)، (3، 32.1)، (4، 35.9)، (5، 40.0). خط المواءمة الأفضل خط مستقيم من (0، 20) إلى (5، 40)."}]'::jsonb, null, 'تحليل', 'كتابة معادلة والتوقع وتقويمه', 'صعب', 'الكتاب ص 10 — الرسوم البيانية وخط المواءمة الأفضل'),
('essay', 3, 'مثّل طالب بيانات تجربة بيانيًّا، ثم وصل كل نقطة بالتي تليها بخط منكسر، وحين أراد توقع قيمة جديدة مدّ القطعة الأخيرة من الخط المنكسر فقط. قوّم طريقته، واقترح الطريقة الصحيحة للتمثيل والتوقع.', null, null, null, 'تقويم', 'تقويم طريقة تمثيل', 'صعب', 'الكتاب ص 10 — الرسوم البيانية وخط المواءمة الأفضل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
