('mcq', 1, 2, 'خط المواءمة الأفضل هو أفضل خط بياني يمر بالنقاط كلها تقريبًا، فتتوزع النقاط حوله.', '["وصل النقاط بخط منكسر لا يمثل الاتجاه العام للبيانات.","الخط الأفضل يراعي النقاط كلها لا نقطتين فقط.","","الخط الأفقي عند أعلى نقطة لا يمثل العلاقة بين المتغيرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.805Z"}'::jsonb),
('mcq', 2, 1, 'في اللوحة (2) يمر الخط المستقيم بالنقاط كلها تقريبًا، وتتوزع النقاط فوقه وتحته بفروق صغيرة؛ فهو خط المواءمة الأفضل.', '["الخط في اللوحة (1) منكسر يصل النقاط بعضها ببعض، ولا يمثل الاتجاه العام.","","الخط في اللوحة (3) يمر بنقطة الأصل وبالنقطتين الأوليين، وتقع النقاط الأخرى كلها تحته.","الخط في اللوحة (4) يمر بالنقطتين الأخيرتين فقط، وتقع النقاط الأخرى كلها فوقه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-17T19:43:12.805Z"}'::jsonb),
('mcq', 3, 0, 'من نقطتين على خط المواءمة (0، 0) و(30 N، 150 cm): الميل = $\frac{150 - 0}{30 - 0} = 5.0\ \text{cm/N}$.', '["","هذا ناتج استخدام نقطة بيانات واحدة (26 cm عند 5 N) بدل نقطتين على خط المواءمة.","هذا مقلوب الميل؛ قُسم التغير في القوة على التغير في المسافة.","هذه قيمة المسافة عند 30 N، لا الميل؛ لم تُقسم على التغير في القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.805Z"}'::jsonb),
('mcq', 4, 3, 'المقطع الرأسي (طول النابض دون كتل) 12.0 cm، والميل $\frac{24.5 - 12.0}{250 - 0} = 0.050\ \text{cm/g}$؛ فالمعادلة $L = 0.050m + 12.0$.', '["أُهمل المقطع الرأسي؛ فطول النابض عند كتلة صفرية 12.0 cm لا صفر.","هذا مقلوب الميل؛ قُسم التغير في الكتلة على التغير في الطول.","بُدّل بين الميل والمقطع الرأسي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-17T19:43:12.805Z"}'::jsonb),
('mcq', 5, 2, 'ميل الخط $\frac{400}{50} = 8.0\ \text{g/cm}^3$، فالمعادلة $m = 8.0V$، ومنها $V = \frac{280}{8.0} = 35\ \text{cm}^3$ (ويمكن قراءتها من الخط مباشرة عند 280 g).', '["هذا ناتج ضرب الكتلة في الميل (280 × 8.0) بدل القسمة عليه.","هذا ناتج قسمة الميل على الكتلة (8.0 ÷ 280)، أي العلاقة مقلوبة.","","هذا حجم أقرب نقطة بيانات (238 g)، لا القراءة من خط المواءمة عند 280 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-17T19:43:12.806Z"}'::jsonb),
('mcq', 6, 1, 'خط المواءمة: $L = 2.0n + 10.0$ (الطول يزداد 2.0 cm تقريبًا لكل حلقة، وطول النابض دون حلقات 10.0 cm)؛ فعند $n = 5$: $L = 2.0(5) + 10.0 = 20.0\ \text{cm}$.', '["هذا ناتج ضرب الميل (2.0 cm لكل حلقة) في 5 مع إهمال طول النابض الأصلي 10.0 cm.","","هذا الطول المتوقع عند 4 حلقات لا 5.","افتُرض أن الطول يتناسب طرديًّا مع عدد الحلقات من نقطة الأصل (16.0 × 5 ÷ 3)، مع أن للنابض طولًا ابتدائيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.806Z"}'::jsonb),
