(c) قياس كتلة كيس أرز باستخدام ميزان.', null, null, null, 'تطبيق', 'تطبيق المفهوم على مواقف', 'صعب', 'الكتاب ص 16 — القياس')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
