from (values
('mcq', 1, 1, 'القياس هو مقارنة كمية مجهولة بأخرى معيارية، فنحصل على عدد يبيّن كم مرة تحتوي الكمية المجهولة على الكمية المعيارية.', '["التقدير بالنظر لا يتضمن مقارنة بكمية معيارية، فهو تخمين لا قياس.","","هذا وصف لاستخدام معامل التحويل في تحليل الوحدات، وليس تعريف القياس.","الوصف بالكلمات وصف نوعي، أما القياس فيعطي مقدارًا كميًّا يُعبَّر عنه بالأرقام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.807Z"}'::jsonb),
('mcq', 2, 2, 'الكمية المعيارية هي الوحدة المتفق عليها التي نقارن بها، وهي هنا الكيلوجرام (kg)، أما كتلة العربة فهي الكمية المجهولة.', '["كتلة العربة هي الكمية المجهولة التي نريد معرفتها، وليست الكمية المعيارية.","الميزان أداة القياس التي تُجري المقارنة، وليس الكمية المعيارية.","","عدد العجلات لا علاقة له بقياس الكتلة ولا يُعد كمية معيارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.807Z"}'::jsonb),
('mcq', 3, 1, 'الكمية المجهولة هي ما نريد معرفة مقداره، وهي طول النابض، ويُقارن بالمتر (m) بوصفه الكمية المعيارية.', '["المتر هو الكمية المعيارية التي نقارن بها، وليس الكمية المجهولة.","","المسطرة أداة القياس، وليست الكمية التي نريد معرفة مقدارها.","التدريجات أجزاء من الكمية المعيارية على الأداة، وليست الكمية المجهولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-17T19:43:12.807Z"}'::jsonb),
('mcq', 4, 3, 'العبارة «طول الطالب 165 cm» تتضمن عددًا ووحدة معيارية، فهي نتيجة مقارنة كمية مجهولة (الطول) بكمية معيارية (السنتيمتر)، أي نتيجة قياس.', '["«جيد إلى حد ما» وصف نوعي لا عدد فيه ولا وحدة، ولذلك يُعبَّر عن ضغط الدم بالأرقام مثل $\\frac{110}{60}$.","«ساخن جدًا» وصف يختلف من شخص لآخر، ولا يتضمن مقارنة بكمية معيارية.","المقارنة بين طولي طالبين دون عدد ووحدة معيارية ليست نتيجة قياس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('mcq', 5, 2, 'القياسات تحوّل مشاهداتنا إلى مقادير كمية يمكن التعبير عنها بالأرقام، فيمكن مقارنتها وتحليلها وتعميمها.', '["لكل قياس حدود دقة وهامش خطأ، فالقياس لا يجعل النتائج خالية من الخطأ.","القياس نفسه يعتمد على كمية معيارية، أي على وحدة متفق عليها، فلا يغني عنها.","","القياس يجعل الوصف موضوعيًا بالأرقام، لا معتمدًا على رأي الشخص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('mcq', 6, 0, 'لأن القياس مقارنة كمية مجهولة بأخرى معيارية، فلا بد من وجود كمية معيارية (وحدة) تُقارن بها الكمية المجهولة.', '["","يمكن القياس بأدوات غير إلكترونية مثل المسطرة والميزان ذي الكفتين.","القيمة المقبولة تُستعمل للحكم على ضبط القياس، ولا يتوقف عليها إجراء القياس نفسه.","تكرار القياس يفيد في الحكم على تقارب النتائج، لكنه ليس شرطًا لحدوث القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('mcq', 7, 2, 'ينقص النتيجة ذكر الوحدة المعيارية التي قورن بها الطول؛ فالعدد 150 وحده لا معنى له؛ فالقياس مقارنة بكمية معيارية، ولذلك يجب ذكر الوحدة (مثل 150 cm) ليُفهم أن الطول يساوي 150 مرة من السنتيمتر.', '["ذكر الأداة قد يفيد في معرفة الدقة، لكن غيابه لا يجعل العدد بلا معنى كما يفعل غياب الوحدة.","عدد مرات التكرار لا يحدد معنى العدد 150؛ فالمشكلة في غياب الكمية المعيارية.","","اسم القائس لا يؤثر في معنى النتيجة؛ فالنتيجة تحتاج إلى وحدة معيارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القياس هو مقارنة كمية مجهولة بأخرى معيارية. عند قياس كتلة العربة بالميزان ذي الكفتين تكون الكمية المجهولة هي كتلة العربة، والكمية المعيارية هي الكيلوجرام (kg).', '["القياس مقارنة كمية مجهولة بأخرى معيارية","الكمية المجهولة: كتلة العربة","الكمية المعيارية: الكيلوجرام (kg)"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف القياس","marks":1},{"element":"تحديد الكمية المجهولة","marks":1},{"element":"تحديد الكمية المعيارية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يعرّف القياس ويحدد الكميتين المجهولة والمعيارية بشكل صحيح"},{"level":"2 درجتان","description":"يعرّف القياس ويحدد إحدى الكميتين، أو يحدد الكميتين دون تعريف صحيح"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الميزان هو الكمية المعيارية","الخلط بين الكمية المجهولة والمعيارية","تعريف القياس بأنه تقدير الكمية بالنظر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة الأولى وصف نوعي لا يتضمن عددًا ولا مقارنة بكمية معيارية، ويختلف تفسيرها من شخص لآخر. أما العبارة الثانية فتعبّر عن ضغط الدم بالأرقام الناتجة عن مقارنة الكمية المجهولة بكمية معيارية باستخدام جهاز قياس الضغط، فهي نتيجة قياس؛ لأن القياسات تحوّل المشاهدات إلى مقادير كمية يمكن التعبير عنها بالأرقام.', '["العبارة الأولى وصف نوعي بلا أرقام ولا معيار","العبارة الثانية مقدار كمي ناتج عن مقارنة بكمية معيارية","القياس يحوّل المشاهدات إلى مقادير كمية بالأرقام"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير العبارة الأولى","marks":1},{"element":"تفسير العبارة الثانية","marks":1},{"element":"ربط ذلك بمفهوم القياس","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يفسر العبارتين ويربطهما بمفهوم القياس"},{"level":"2 درجتان","description":"يفسر العبارتين دون ربط واضح بمفهوم القياس"},{"level":"1 درجة","description":"يفسر عبارة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بالقول إن الثانية أدق دون تفسير","إغفال أن القياس يتطلب كمية معيارية","عدّ أي عبارة تصف الحالة الصحية قياسًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الكمية المجهولة: طول النابض، والكمية المعيارية: المتر (m). (b) الكمية المجهولة: زمن السباق، والكمية المعيارية: الثانية (s). (c) الكمية المجهولة: كتلة كيس الأرز، والكمية المعيارية: الكيلوجرام (kg).', '["(a) طول النابض / المتر (m)","(b) زمن السباق / الثانية (s)","(c) كتلة كيس الأرز / الكيلوجرام (kg)"]'::jsonb, '[]'::jsonb, '[{"element":"الموقف (a)","marks":1},{"element":"الموقف (b)","marks":1},{"element":"الموقف (c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحدد الكميتين في المواقف الثلاثة"},{"level":"2 درجتان","description":"يحدد الكميتين في موقفين"},{"level":"1 درجة","description":"يحدد الكميتين في موقف واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أداة القياس (المسطرة، الساعة، الميزان) هي الكمية المعيارية","ذكر الجرام بدل الكيلوجرام بوصفه الوحدة المعيارية للكتلة","تبديل الكمية المجهولة بالمعيارية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-17T19:43:12.808Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
