from (values
('mcq', 1, 'لماذا يستخدم العلماء النظام الدولي للوحدات (SI) في التعبير عن نتائج قياساتهم؟', null, null, '["لأنه يجعل نتائج القياسات خالية من الأخطاء","لتعميم النتائج بوحدات متفق عليها يفهمها الناس جميعًا","لأنه يسمح لكل دولة باستخدام وحداتها الخاصة بها دون اتفاق","لأنه يغني عن استخدام أدوات القياس في المختبر"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 16 — النظام الدولي للوحدات'),
('mcq', 2, 'ما الذي يجعل التحويل بين وحدات النظام الدولي سهلًا؟', null, null, '["أن جميع وحداته أساسية فلا حاجة إلى التحويل بينها","أن معامل التحويل بين أي وحدتين فيه يساوي 12","أن التحويل يتم بالضرب أو القسمة على قوة ملائمة للعدد 10","أن جميع الكميات فيه تقاس بوحدة المتر"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 17 — ميزات النظام الدولي (سهولة التحويل)'),
('mcq', 3, 'التحويل من المتر إلى الكيلومتر أسهل من التحويل من القدم إلى الميل. ما سبب ذلك؟', null, null, '["لأن الكيلومتر وحدة أساسية والميل وحدة مشتقة منها","لأن الكيلومتر يساوي $10^3$ مرة من المتر","لأن القدم أطول من المتر فيصعب تحويله","لأن الميل أصغر من القدم فيصعب تحويله"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 17 — ميزات النظام الدولي (سهولة التحويل)'),
('mcq', 4, 'كيف حُدّدت وحدات الكميات الأساسية مثل الطول والكتلة في النظام الدولي للوحدات؟', null, null, '["بالقياس المباشر اعتمادًا على وحدات معيارية محفوظة","باشتقاقها من وحدات الطاقة والشحنة الكهربائية","بترك كل دولة تحدد قيمها حسب حاجتها واستخدامها","بتقديرها بأجزاء جسم الإنسان مثل الشبر والقدم"]'::jsonb, 'تذكر', 'تذكر', 'متوسط', 'الكتاب ص 16 — النظام الدولي للوحدات'),
('mcq', 5, 'سجّل فريق بحثي أطوال عينات بوحدة البوصة، وسجّل فريق آخر في بلد مختلف أطوال العينات نفسها بوحدة المتر. ما المشكلة المتوقعة، وما حلها؟', null, null, '["لا توجد مشكلة؛ لأن الطول هو الكمية نفسها مهما اختلفت الوحدة","صعوبة مقارنة النتائج، والحل استخدام وحدات النظام الدولي","قياسات الفريق الأول خاطئة دائمًا، والحل إعادة القياس بأداة إلكترونية","اختلاف الكمية المقيسة، والحل أن يقيس الفريقان الكتلة بدلًا من الطول"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 16 — النظام الدولي للوحدات'),
('mcq', 6, 'أُعيد تعريف المتر المعياري بأنه المسافة التي يقطعها الضوء في الفراغ في $\frac{1}{299792458}$ ثانية. ما سبب ذلك؟', null, null, '["لأن الضوء ينتشر في الفراغ بسرعة متغيرة","لأن الثانية وحدة مشتقة من المتر","لأن طرق قياس الزمن أدق من طرق قياس الطول","لأن تعريف المتر بالضوء يلغي الحاجة إلى الوحدات"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 17 — الوحدتان المعياريتان للكيلوجرام والمتر'),
('mcq', 7, 'أيّ العبارات الآتية تصف النظام الدولي للوحدات (SI) وصفًا صحيحًا؟', null, null, '["نظام وحدات يستخدم في الفيزياء فقط ويتضمن ثلاث كميات أساسية","نظام جميع وحداته أساسية ولا يحتوي على وحدات مشتقة","نظام تختلف وحداته من دولة إلى أخرى بحسب الاتفاق المحلي","النظام الأوسع انتشارًا في العالم، ويتضمن سبع كميات أساسية"]'::jsonb, 'تذكر', 'تذكر', 'صعب', 'الكتاب ص 16 — النظام الدولي للوحدات'),
('essay', 1, 'ما النظام الدولي للوحدات؟ وعلّل استخدام العلماء له، مع ذكر ميزتين له.', null, null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 16، 17، 26 — النظام الدولي للوحدات'),
('essay', 2, 'إذا علمت أن الميل يساوي 5280 قدمًا، وأن الكيلومتر يساوي 1000 m، فعلّل: التحويل من المتر إلى الكيلومتر أسهل من التحويل من القدم إلى الميل. وضّح إجابتك بتحويل 3500 m إلى km.', null, null, null, 'فهم', 'تعليل مع مثال', 'متوسط', 'الكتاب ص 17 — ميزات النظام الدولي (سهولة التحويل)'),
('essay', 3, 'مختبران: الأول يسجّل الكتل بالرطل والأطوال بالبوصة، والثاني يسجّلها بالكيلوجرام والمتر. قوّم الوضع: ما المشكلات التي قد تنتج عند تبادل النتائج بينهما؟ وما الحل الأفضل؟ ولماذا؟', null, null, null, 'تقويم', 'تقويم موقف', 'صعب', 'الكتاب ص 16 — النظام الدولي للوحدات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
