from (values
('mcq', 1, 1, 'من المفيد لتعميم النتائج بشكل مفهوم لدى الناس جميعًا استخدام وحدات قياس متفق عليها، والنظام الدولي هو النظام الأوسع انتشارًا في جميع أنحاء العالم.', '["النظام الدولي يوحّد الوحدات، لكنه لا يزيل أخطاء القياس التي تعتمد على الأداة والطريقة.","","العكس صحيح؛ فالنظام الدولي وحدات موحّدة متفق عليها لا وحدات خاصة بكل دولة.","الوحدات لا تغني عن الأدوات؛ فالقياس يحتاج إلى أداة تقارن الكمية بالوحدة المعيارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 2, 2, 'سهولة التحويل ميزة من ميزات النظام الدولي؛ فللتحويل بين وحداته نضرب أو نقسم على الرقم 10 مرفوعًا إلى قوة ملائمة، باستخدام البادئات.', '["في النظام الدولي وحدات أساسية وأخرى مشتقة، ونحتاج إلى التحويل بين أجزاء الوحدات ومضاعفاتها.","العدد 12 يرتبط بأنظمة أخرى (مثل القدم والبوصة)، أما النظام الدولي فيعتمد على قوى العشرة.","","لكل كمية أساسية وحدتها الخاصة؛ فالكتلة بالكيلوجرام والزمن بالثانية مثلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 3, 1, 'الكيلومتر جزء من النظام الدولي، ويساوي $10^3$ m، فيتم التحويل بتحريك الفاصلة العشرية، بينما العلاقة بين القدم والميل ليست قوة للعدد 10.', '["الكيلومتر ليس وحدة أساسية (الوحدة الأساسية للطول هي المتر)، والسهولة سببها قوى العشرة.","","المتر أطول من القدم، وطول الوحدة ليس سبب سهولة التحويل أصلًا.","الميل أكبر بكثير من القدم، وهذه المقارنة لا تفسر سهولة التحويل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 4, 0, 'حُدّدت وحدات الكميات الأساسية باستخدام القياس المباشر، معتمدة على وحدات معيارية لكل من الطول والكتلة محفوظة في دائرة دولية للأوزان والمقاييس.', '["","العكس هو الصحيح؛ فوحدات الطاقة والشحنة مشتقة من الوحدات الأساسية.","لو حددت كل دولة قيمها لما كانت الوحدات متفقًا عليها عالميًا.","أجزاء الجسم تختلف من شخص لآخر، فلا تصلح وحدات معيارية متفقًا عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 5, 1, 'اختلاف الوحدات يصعّب فهم النتائج ومقارنتها وتعميمها؛ لذلك يُفضَّل استخدام وحدات متفق عليها، وهي وحدات النظام الدولي الأوسع انتشارًا.', '["الكمية واحدة، لكن اختلاف الوحدات يجعل الأعداد مختلفة ويصعّب المقارنة والتعميم.","","استخدام وحدة غير دولية لا يجعل القياس خاطئًا، بل يصعّب فهمه ومقارنته.","الكمية المقيسة واحدة (الطول)، والمشكلة في الوحدة لا في الكمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 6, 2, 'لما كانت طرق قياس الزمن أدق من طرق قياس الطول، عُرّف المتر بدلالة المسافة التي يقطعها الضوء في الفراغ في زمن محدد، فيصبح المعيار أدق.', '["سرعة الضوء في الفراغ ثابتة، ولذلك صلحت أساسًا للتعريف.","الثانية وحدة أساسية للزمن، وليست مشتقة من المتر.","","التعريف يحدد وحدة المتر بدقة أكبر، ولا يلغي الحاجة إلى الوحدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-17T19:43:12.809Z"}'::jsonb),
('mcq', 7, 3, 'النظام الدولي للوحدات هو النظام الأوسع انتشارًا في جميع أنحاء العالم، ويتضمن سبع كميات أساسية، وتشتق منها الوحدات الأخرى.', '["يستخدم في العلوم والحياة اليومية، ويتضمن سبع كميات أساسية لا ثلاثًا.","يحتوي النظام على وحدات مشتقة مثل الجول (J) والكولوم (C).","وحدات النظام الدولي متفق عليها عالميًا، وهذا سبب استخدامه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-17T19:43:12.810Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظام الدولي للوحدات (SI) نظام وحدات قياس متفق عليها، وهو الأوسع انتشارًا في العالم، ويتضمن سبع كميات أساسية تشتق منها الوحدات الأخرى. يستخدمه العلماء لأن استخدام وحدات متفق عليها يجعل تعميم النتائج مفهومًا لدى الناس جميعًا. ومن ميزاته: (1) الانتشار والاتفاق العالمي مما يسهّل تبادل النتائج ومقارنتها. (2) سهولة التحويل بين وحداته بالضرب أو القسمة على 10 مرفوعًا إلى قوة ملائمة.', '["تعريف النظام الدولي: نظام وحدات متفق عليها الأوسع انتشارًا","تعميم النتائج بشكل مفهوم للجميع","سهولة التحويل بقوى العشرة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النظام","marks":1},{"element":"الميزة الأولى (تعميم النتائج)","marks":1},{"element":"الميزة الثانية (سهولة التحويل)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يعرّف النظام ويعلل استخدامه بميزتين صحيحتين"},{"level":"2 درجتان","description":"يذكر عنصرين من الثلاثة"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بالقول إنه نظام عالمي دون تعليل","الادعاء أنه يجعل القياسات خالية من الخطأ","إغفال ميزة سهولة التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-17T19:43:12.810Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العلاقة بين المتر والكيلومتر قوة للعدد 10 ($1\ \text{km} = 10^3\ \text{m}$)، فيتم التحويل بتحريك الفاصلة العشرية ثلاث منازل، أما العلاقة بين القدم والميل فعدد غير منتظم (5280) يحتاج إلى قسمة طويلة. مثال: $3500\ \text{m} \times \frac{1\ \text{km}}{1000\ \text{m}} = 3.5\ \text{km}$.', '["العلاقة بين m وkm قوة للعدد 10","العلاقة بين القدم والميل عدد غير منتظم","3500 m = 3.5 km"]'::jsonb, '["$1\\ \\text{km} = 1000\\ \\text{m} = 10^3\\ \\text{m}$","$3500\\ \\text{m} \\times \\frac{1\\ \\text{km}}{1000\\ \\text{m}} = 3.5\\ \\text{km}$"]'::jsonb, '[{"element":"تعليل سهولة التحويل في النظام الدولي","marks":1},{"element":"المقارنة مع القدم والميل","marks":1},{"element":"التحويل الصحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يعلل ويقارن ويحوّل بشكل صحيح"},{"level":"2 درجتان","description":"يعلل ويقارن دون تحويل صحيح، أو العكس"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الضرب في 1000 بدل القسمة فيحصل على 3500000 km","تعليل السهولة بأن الكيلومتر وحدة أساسية","إغفال المقارنة بالقدم والميل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-17T19:43:12.810Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المشكلات: صعوبة مقارنة النتائج مباشرة، والحاجة إلى تحويلات بمعاملات غير منتظمة، واحتمال الوقوع في أخطاء أثناء التحويل أو سوء فهم النتائج. الحل الأفضل: أن يستخدم المختبران وحدات النظام الدولي (kg وm)؛ لأنها وحدات متفق عليها والأوسع انتشارًا، فتصبح النتائج مفهومة لدى الجميع ويسهل تعميمها، كما أن التحويل بين وحداتها سهل بقوى العشرة.', '["صعوبة المقارنة وتبادل النتائج","أخطاء محتملة في التحويل بمعاملات غير منتظمة","الحل: النظام الدولي لأنه متفق عليه وسهل التحويل"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر مشكلة المقارنة والتعميم","marks":1},{"element":"ذكر مشكلة التحويل وأخطائه","marks":1},{"element":"اقتراح الحل مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر المشكلتين ويقترح الحل مع تعليل صحيح"},{"level":"2 درجتان","description":"يذكر مشكلة واحدة ويقترح الحل معللًا، أو المشكلتين دون حل"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن قياسات المختبر الأول خاطئة","اقتراح الحل دون تعليل","الخلط بين اختلاف الوحدة واختلاف الكمية المقيسة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-17T19:43:12.811Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
